window.NAHJ = window.NAHJ || {parts: {}};
window.NAHJ.parts = window.NAHJ.parts || {};
window.NAHJ.parts.m = {"m1":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُنْ فِي الْفِتْنَةِ كَابْنِ اللَّبُونِ، لاَ ظَهْرٌ فَيُرْكَبَ، وَلاَ ضَرْعٌ فَيُحْلَبَ.","ob":"Sois dans la sédition une petite chamelle [de deux ans] qu'on ne peut encore ni monter, ni traire.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m2":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَزْرَى بِنَفْسِهِ مَنِ اسْتَشْعَرَ الطَّمَعَ، وَرَضِيَ بِالذُّلِّ مَنْ كَشَفَ عَنْ ضُرِّهِ، وَهَانَتْ عَلَيْهِ نَفْسُهُ مَنْ أَمَّرَ عليه لِسَانَهُ.","ob":"Méprise soi-même celui dont le naturel tend vers l'avidité; accepte l'avilissement celui qui exhibe son malheur; dédaigne soi-même celui qui se laisse guider par sa langue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m3":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْبُخْلُ عَارٌ، وَالْجُبْنُ مَنْقَصَةٌ، وَالْفَقْرُ يُخْرِسُ الْفَطِنَ عَنْ حُجَّتِهِ، وَالْمُقِلُّ غَرِيبٌ فِي بَلْدَتِهِ.","ob":"L'avarice est honteuse, la couardise est un défaut, la pauvreté fait taire l'argument de l'intelligent et le pauvre est étranger dans sa cité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m4":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعَجْزُ آفَةٌ، وَالصَّبْرُ شَجَاعَةٌ، وَالزُّهْدُ ثَرْوَةٌ، وَالْوَرَعُ جُنَّةٌ، وَنِعْمَ الْقَرِينُ الرِّضَى.","ob":"L'impuissance est une affection, la patience est du courage, la tempérance est une richesse, la piété est une précaution et le contentement est le meilleur des compagnons.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m5":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعِلْمُ وِرَاثَةٌ كَرِيمَةٌ، وَالْآدَابُ حُلَلٌ مُجَدَّدَةٌ، وَالْفِكْرُ مِرْآةٌ صَافِيَةٌ.","ob":"La science est un héritage noble, la bonne éducation est une tenue nouvelle et la pensée est un miroir clair.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m6":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"صَدْرُ الْعَاقِلِ صُنْدُوقُ سِرِّهِ، وَالْبَشَاشَةُ حِبَالَةُ الْمَوَدَّةِ، وَالِاحْتِمَالُ قَبْرُ الْعُيُوبِ.","ob":"La poitrine du sage est la boîte de ses secrets, l'affabilité est le filet qui retient l'amabilité et la patience est le tombeau des défauts.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m7":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الصَّدَقَةُ دَوَاءٌ مُنْجِحٌ، وَأَعْمَالُ الْعِبَادِ فِي عَاجِلِهِمْ، نُصْبُ أَعْيُنِهِمْ فِي آجالهم.","ob":"L'aumône est un remède efficace; les bonnes actions des serviteurs ici-bas apparaissent devant leurs yeux dans l'Au-delà.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m8":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اعْجَبُوا لِهذَا الْإِنْسَانِ يَنْظُرُ بِشَحْمٍ، وَيَتَكَلَّمُ بِلَحْمٍ، وَيَسْمَعُ بِعَظْمٍ، وَيَتَنَفَّسُ مِنْ خَرْمٍ.","ob":"Emerveillez-vous devant cet homme qui voit grâce à la graisse de la prunelle, parle avec la langue carnée, entend grâce aux osselets des oreilles et respire d'une fente!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m9":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِذَا أَقْبَلَتِ الدُّنْيَا عَلَى أَحَدٍ أَعَارَتْهُ مَحَاسِنَ غَيْرِهِ، وَإِذَا أَدْبَرَتْ عَنْهُ سَلَبَتْهُ مَحَاسِنَ نَفْسِهِ.","ob":"Si la vie offre la prospérité à un homme, elle lui prête les vertus des autres; dans le cas contraire, elle lui enlève ses propres vertus.","obNotes":[],"an":"Quand le sort favorise un être il lui prête les qualités des autres, et quand il lui tourne le dos il le dépouille de ses propres qualités.","anIntro":"","anNotes":[],"diff":null}]},"m10":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"خَالِطُوا النَّاسَ مُخَالَطَةً إِنْ مِتُّمْ مَعَهَا بَكَوْا عَلَيْكُمْ، وَإِنْ عِشْتُمْ حَنُّوا إِلَيْكُمْ.","ob":"Communiquez-vous avec les gens de telle manière que si vous mourez ils vous pleureront et si vous vivez ils tendront vers vous.","obNotes":[],"an":"Fréquentez les hommes de sorte qu'ils vous pleurent à votre mort et vous chérissent de votre vivant.","anIntro":"","anNotes":[],"diff":null}]},"m11":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا قَدَرْتَ عَلَى عَدُوِّكَ فَاجْعَلِ الْعَفْوَ عَنْهُ شُكْراً لِلْقُدْرَةِ عَلَيْهِ.","ob":"Si tu l'emportes sur ton ennemi fais que le pardon soit le remerciement pour l'avoir vaincu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m12":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"أَعْجَزُ النَّاسِ مَنْ عَجَزَ عَنِ اكْتِسَابِ الْإِخْوَانِ، وَأَعْجَزُ مِنْهُ مَنْ ضَيَّعَ مَنْ ظَفِرَ بِهِ مِنْهُمْ.","ob":"Le plus impuissant parmi les hommes est celui qui n'arrive pas à acquérir des amis, mais celui qui les perd après les avoir acquis est plus impuissant encore.","obNotes":[],"an":"Le plus impuissant des hommes est celui qui n'a pas su se faire des amis, le plus impuissant encore est celui qui perd ceux qu'il aurait acquis.","anIntro":"","anNotes":[],"diff":null}]},"m13":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا وَصَلَتْ إِلَيْكُمْ أَطْرَافُ النِّعَمِ فَلَا تُنَفِّرُوا أَقْصَاهَا بِقِلَّةِ الشُّكْرِ.","ob":"Si les prémices des grâces arrivent chez vous, n'effarouchez pas celles qui vont suivre.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m14":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ ضَيَّعَهُ الْأَقْرَبُ أُتِيحَ لَهُ الْأَبْعَدُ.","ob":"Beaucoup de personnes qui ont perdu leurs parents trouveront parmi les étrangers des individus qui leur viennent en aide.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m15":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا كُلُّ مَفْتُونٍ يُعَاتَبُ.","ob":"On ne peut pas en vouloir à tous ceux qui se trouvent impliqués dans une sédition.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m18":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي الَّذِينَ اعْتَزَلُوا الْقِتَالَ مَعَهُ: خَذَلُوا الْحَقَّ، وَلَمْ يَنْصُرُوا الْبَاطِلَ.","ob":"(Il dit au sujet de ceux qui avaient cessé de combattre avec lui): Ils se sont éloignés de la vérité sans pour autant aider le mensonge.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m19":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ جَرَى فِي عِنَانِ أَمَلِهِ عَثَرَ بِأَجَلِهِ.","ob":"Celui qui court à bride laissée derrière ses espoirs sera trébuché par sa mort.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m20":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَقِيلُوا ذَوِي الْمُرُوءَاتِ عَثَرَاتِهِمْ، فَمَا يَعْثُرُ عَاثِرٌ إِلَّا ويد اللّٰهِ بيده يَرْفَعُهُ.","ob":"Relevez les honnêtes gens de leurs faux pas, car dès qu'un d'eux trébuche Dieu lui tend la main pour le relever.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m21":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قُرِنَتِ الْهَيْبَةُ بِالْخَيْبَةِ، وَالْحَيَاءُ بِالْحِرْمَانِ، وَالْفُرْصَةُ تَمُرُّ مَرَّ السَّحَابِ، فَانْتَهِزُوا فُرَصَ الْخَيْرِ.","ob":"Craindre une chose c'est en être frustré et avoir honte c'est se priver. L'occasion passe comme les nuages, profitez donc des occasions du bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m22":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَنَا حَقٌّ، فَإِنْ أُعْطِينَاهُ، وَإِلاَّ رَكِبْنَا أَعْجَازَ الإبِلِ، وَإِنْ طَالَ السُّرَى.","ob":"Nous avons un droit qui doit nous être donné, sinon nous serions pris en croupe tant que le voyage de nuit dure.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m23":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَبْطَأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ حَسَبُهُ.","ob":"Celui dont les actions traînent n'avancera pas grâce à son lignage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m24":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مِنْ كَفَّارَاتِ الذُّنُوبِ الْعِظَامِ إِغَاثَةُ الْمَلْهُوفِ، وَالتَّنْفِيسُ عَنِ الْمَكْرُوبِ.","ob":"Parmi les grandes expiations des péchés on compte l'aide fournie aux affligés et la consolation des malheureux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m25":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَابْنَ آدَمَ، إِذَا رَأَيْتَ رَبَّكَ سُبْحَانَهُ يُتَابِعُ عَلَيْكَ نِعَمَهُ وَأَنْتَ تَعْصِيهِ فَاحْذَرْهُ.","ob":"O fils d'Adam, si tu vois ton Seigneur continuant de te donner Ses grâces et tu Lui désobéis, prends garde!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m26":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَضْمَرَ أَحَدٌ شَيْئاً إِلَّا ظَهَرَ فِي فَلَتَاتِ لِسَانِهِ، وصفحات وَجْهِهِ.","ob":"Nul ne peut cacher ses intentions sans qu'elles n'apparaissent dans les lapsus de sa langue et les traits de son visage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m27":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"امْشِ بِدَائِكَ مَا مَشَى بِكَ.","ob":"Malgré ta maladie, continue de travailler tant que tu peux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m28":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَفْضَلُ الزُّهْدِ إِخْفَاءُ الزُّهْدِ.","ob":"La meilleure ascèse est celle qui est cachée.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m29":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا كُنْتَ فِي إِدْبَارٍ، وَالْمَوْتُ فِي إِقْبَالٍ، فَمَا أسْرَعَ الْمُلْتَقَى.","ob":"Tu fuis la mort et elle te suit; bientôt vous vous rencontrerez.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m30":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْحَذَرَ الْحَذَرَ! فَوَاللهِ لَقَدْ سَتَرَ، حتَّى كَأَنَّهُ قَدْ غَفَرَ.","ob":"Prenez garde! Dieu t'a protégé, comme s'il t'avait pardonné.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m31":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وسُئِلَ عَنِ الْإِيمَانِ، فَقَالَ: الْإِيمَانُ عَلَى أَرْبَعِ دَعَائِمَ: عَلَى الصَّبْرِ، والْيَقِينِ، وَالْعَدْلِ، وَالْجِهَادِ. وَالصَّبْرُ مِنْهَا عَلَى أَربَعِ شُعَبٍ: عَلَى الشَّوْقِ، وَالشَّفَقِ، وَالزُّهْدِ، وَالتَّرَقُّبِ: فَمَنِ اشْتَاقَ إِلَى الْجَنَّةِ سَلاَ عَنِ الشَّهَوَاتِ، وَمَنْ أشْفَقَ مِنَ النَّارِ اجْتَنَبَ الْمُحَرَّمَاتِ، وَمَنْ زَهِدَ فِي الدُّنْيَا اسْتَهَانَ بِالْمُصِيبَاتِ؛ وَمَنِ ارْتَقَبَ الْمَوْتَ سَارَعَ إِلَى الْخَيْرَاتِ.","ob":"(On lui demande d'expliquer la foi; il dit): La foi repose sur quatre piliers: la patience, la certitude, la justice et le <i>jihād</i>. La patience s'embranche en: le désir ardent, la crainte, l'ascèse et l'attente: celui qui désire ardemment le Paradis oublie les passions; celui qui craint le Feu évite les choses illicites; celui qui méprise le monde dédaigne les malheurs; et celui qui s'attend à la mort se hâte vers les œuvres de bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"وَالْيَقِينُ مِنْهَا عَلَى أَرْبَعِ شُعَبٍ: عَلَى تَبْصِرَةِ الْفِطْنَةِ، وَتَأَوُّلِ الْحِكْمَةِ، وَمَوْعِظَةِ الْعِبْرَةِ، وَسُنَّةِ الأوَّلِينَ. فَمَنْ تَبَصَّرَ فِي الْفِطْنَةِ تَبَيَّنَتْ لَهُ الْحِكْمَةُ، وَمَنْ تَبَيَّنَتْ لَهُ الْحِكْمَةُ عَرَفَ الْعِبْرَةَ فَكَأَنَّمَا كَانَ فِي الْأَوَّلِينَ.","ob":"La certitude comprend elle aussi quatre embranchements: la prudence discriminatoire, la sagesse interprétative, la considération attentive, la tradition (Sunna) des anciens. Celui qui réfléchit prudemment entrevoit la sagesse, considère le pour et le contre et tire des leçons de vie; il sera parmi les premiers.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[3],"ar":"وَالْعَدْلُ مِنْهَا عَلَى أَرْبَعِ شُعَبٍ: عَلَى غائِصِ الْفَهْمِ، وَغَوْرِ الْعِلْمِ، وَزُهْرَةِ الْحُكْمِ، وَرَسَاخَةِ الْحِلْمِ، فَمَنْ فَهِمَ عَلِمَ غَوْرَ الْعِلْمِ؛ وَمَنْ عَلِمَ غَوْرَ الْعِلْمِ صَدَرَ عَنْ شَرَائِعِ الْحُكْمِ؛ وَمَنْ حَلُمَ لَمْ يُفَرِّطْ فِي أَمْرِهِ وَعَاشَ فِي النَّاسِ حَمِيداً.","ob":"Quant à la justice, elle renferme également quatre idées: la compréhension profonde, la science approfondie, le bon jugement et la longanimité bien ancrée. Celui qui comprend connaît l'abîme de la science; celui-ci puise des législations idoines; l'homme indulgent n'exagère pas et vit honoré entre les hommes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[4],"ar":"وَالْجِهَادُ مِنْهَا عَلَى أَرْبَعِ شُعَبٍ: عَلَى الْأَمْرِ بِالْمَعْرُوفِ، وَالنَّهْيِ عَنِ الْمُنكَرِ، وَالصِّدْقِ فِي الْمَوَاطِنِ، وَشَنَآنِ الْفَاسِقِينَ: فَمَنْ أَمَرَ بِالْمَعْرُوفِ شَدَّ ظُهُورَ الْمُؤمِنِينَ، وَمَنْ نَهَى عَنِ الْمُنْكَرِ أَرْغَمَ أُنُوفَ الْكَافِرِينَ؛ وَمَنْ صَدَقَ فِي الْمَوَاطِنِ قَضَى مَا عَلَيْهِ؛ وَمَنْ شَنِئَ الْفَاسِقِينَ وَغَضِبَ لله، غَضِبَ اللّٰهُ لَهُ وَأَرْضَاهُ يَوْمَ الْقِيَامَةِ.","ob":"Le <i>jihād</i> englobe à son tour : ordonner le convenable, interdire le blâmable, être véridique dans les combats pour la justice et haïr les vicieux. Celui qui ordonne le convenable épaule les croyants; celui qui interdit le blâmable contraint les athées à croire; celui qui combat fait son devoir et celui qui hait les vicieux et se met en colère pour la cause de Dieu, Dieu se met en colère pour lui et le récompense le Jour du jugement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[5],"ar":"وَالْكُفْرُ عَلَى أَرْبَعِ دَعَائِمَ: عَلَى التَّعَمُّقِ وَالتَّنَازُعِ، وَالزَّيْغِ، وَالشِّقَاقِ: فَمَنْ تَعَمَّقَ لَمْ يُنِبْ إِلَى الْحَقِّ؛ وَمَنْ كَثُرَ نِزَاعُهُ بِالْجَهْلِ دَامَ عَمَاهُ عَنِ الْحَقِّ؛ وَمَنْ زَاغَ سَاءَتْ عِنْدَهُ الْحَسَنَةُ، وَحَسُنَتْ عِنْدَهُ السَّيِّئَةُ، وَسَكِرَ سُكْرَ الضَّلاَلَةِ، وَمَنْ شَاقَّ وَعُرَتْ عَلَيْهِ طُرُقُهُ، وَأَعْضَلَ عَلَيْهِ أَمْرُهُ، وَضَاقَ عَلَيْهِ مَخْرَجُهُ.","ob":"De même, l'athéisme comprend quatre piliers: les conjectures, les disputes doctrinales, l'éloignement de la voie juste et l'opiniâtreté. Celui qui se perd dans les suppositions et les soupçons ne retourne pas à la vérité; celui qui patauge dans l'ignorance est aveuglé constamment devant la vérité; celui qui erre confond le bien et le mal et se rend à l'ivresse de l'égarement; et celui qui s'attache obstinément à ses opinions connaîtra des chemins ardus, se trouvera devant un dilemme et ne trouvera pas une issue résolvante.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[6],"ar":"وَالشَّكُّ عَلَى أَرْبَعِ شُعَب: عَلَى التَّمَارِي، وَالْهَوْلِ، وَالتَّرَدُّدِ، وَالِاسْتِسْلَامِ: فَمَنْ جَعَلَ الْمِرَاءَ دَيْدَناً لَمْ يُصْبِحْ لَيْلُهُ؛ وَمَنْ هَالَهُ مَا بَيْنَ يَدَيْهِ نَكَصَ عَلَى عَقِبَيْهِ؛ وَمَن تَرَدَّدَ فِي الرَّيْبِ وَطِئَتْهُ سَنَابِكُ الشَّيَاطِينِ؛ وَمَنِ اسْتَسْلَمَ لِهَلَكَةِ الدُّنْيَا وَالْآخِرَةِ هَلَكَ فِيهِمَا.","ob":"Finalement, le scepticisme englobe quatre embranchements: la dispute [doctrinale], l'appréhension, l'hésitation et la sujétion. Celui qui s'habitue à la dispute vivra dans une nuit sans lendemain; celui qui a peur des difficultés qui entravent la voie de la foi fera marche arrière; celui qui hésite dans ses conjectures sera piétiné par les sabots des diables; et celui qui s'assujettit à la perdition de la vie terrestre et de l'autre monde périra dans les deux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m32":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فَاعِلُ الْخَيْرِ خَيْرٌ مِنْهُ، وَفَاعِلُ الشَّرِّ شَرٌّ مِنْهُ.","ob":"Le philanthrope l'emporte sur le bien et le misanthrope est pire que le mal.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m33":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُنْ سَمَحاً وَلَا تَكُنْ مُبَذِّراً، وَكُنْ مُقَدِّراً وَلَا تَكُنْ مُقَتِّراً.","ob":"Sois généreux et non prodigue; sois économe et non avare.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m34":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَشْرَفُ الْغِنَى تَرْكُ الْمُنَى.","ob":"La richesse la plus noble consiste à délaisser les choses désirées.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m35":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَسْرَعَ إِلَى النَّاسِ بِمَا يَكْرَهُونَ، قَالُوا فِيهِ بِمَا لَا يَعْلَمُونَ.","ob":"Celui qui se hâte de faire ce que les gens haïssent, sera châtié par leurs médisances.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m36":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَطَالَ الْأَمَلَ أَسَاءَ الْعَمَلَ.","ob":"Celui qui se fie à la réalisation des désirs fait mal son travail.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m37":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام وَقَدْ لَقِيَهُ عِنْدَ مَسِيرِهِ إِلَى الشَّامِ دَهَاقِينُ الْأَنْبَارِ، فَتَرَجَّلُوا لَهُ وَاشْتَدُّوا بَيْنَ يَدَيْهِ، فَقَالَ: مَا هذَا الَّذِي صَنَعْتُمُوهُ؟ فقالوا: خُلُقٌ مِنَّا نُعَظِّمُ بِهِ أُمَرَاءَنَا، فَقَالَ: وَاللهِ مَا يَنْتَفِعُ بِهذَا أُمَرَاؤُكُمْ! وَإِنَّكُمْ لَتَشُقُّونَ عَلَى أَنْفُسِكُمْ فِي دُنْيَاكُمْ، وَتَشْقَوْنَ بِهِ فِي آخِرَتِكُمْ. وَمَا أخْسَرَ الْمَشَقَّةَ وَرَاءَهَا الْعِقَابُ، وَأَرْبَحَ الدَّعَةَ مَعَهَا الْأَمَانُ مِنَ النَّارِ!","ob":"(Pendant sa marche vers Damas, les chefs des Anbar-s [les cultivateurs de la Perse] le rencontrèrent, descendirent de leurs montures et accoururent vers lui; il dit): Qu'avez-vous fait? (Ils dirent: c'est une façon héritée pour vénérer nos princes). Et lui de dire: Vos princes ne tirent aucun profit de ce que vous faites. Vous vous fatiguez dans ce monde et vous serez malheureux dans l'autre monde. Combien est perdante la fatigue suivie de châtiment et gagnant votre repos si vous êtes garantis contre le Feu!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m38":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِابْنِهِ الْحَسَنِ: يَا بُنَيَّ، احْفَظْ عَنِّي أَرْبَعاً، وَأَرْبَعاً، لَا يَضُرَّكَ مَا عَمِلْتَ مَعَهُنَّ: إِنَّ أَغْنَى الْغِنَى الْعَقْلُ، وَأَكْبَرَ الْفَقْرِ الْحُمْقُ، وَأَوْحَشَ الْوَحْشَةِ الْعُجْبُ، وَأَكْرَمَ الْحَسَبِ حُسْنُ الْخُلُقِ.","ob":"(Il dit à son fils al-Ḥasan): Mon fils, retiens de moi quatre suivis de quatre autres, qui t'épargnent toute nuisance: la richesse par excellence est l'intelligence; l'extrême pauvreté est la sottise; la solitude la plus triste est l'orgueil; et le lignage le plus noble est le bon caractère.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"يَا بُنَيَّ، إِيَّاكَ وَمُصَادَقَةَ الْأَحْمَقِ، فَإِنَّهُ يُرِيدُ أَنْ يَنْفَعَكَ فَيَضُرَّكَ؛ وَإِيَّاكَ وَمُصَادَقَةَ الْبَخِيلِ، فَإِنَّهُ يَقْعُدُ عَنْكَ أَحْوَجَ مَا تَكُونُ إِلَيْهِ؛ وَإِيَّاكَ وَمُصَادَقَةَ الْفَاجِرِ، فَإِنَّهُ يَبِيعُكَ بِالتَّافِهِ، وَإِيَّاكَ وَمُصَادَقَةَ الْكَذَّابِ، فَإِنَّهُ كَالسَّرَابِ: يُقَرِّبُ عَلَيْكَ الْبَعِيدَ، وَيُبَعِّدُ عَلَيْكَ الْقَرِيبَ.","ob":"Mon fils, abstiens-toi de nouer amitié avec un sot, car même s'il veut te faire du bien il te nuit; Ne sois pas l'ami d'un avare, car il s'abstient de te prêter ce dont tu as besoin; de même, éloigne-toi du pervers, car il te vendra pour peu d'argent; finalement, garde-toi d'être l'ami d'un menteur, car il est comme le mirage: il te fait rapprocher ce qui est loin et vice versa.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m39":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا قُرْبَةَ بِالنَّوَافِلِ إِذَا أَضَرَّتْ بِالْفَرَائِضِ.","ob":"On ne se rapproche pas de Dieu par les œuvres surérogatoires en laissant tomber les obligations.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m40":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِسَانُ الْعَاقِلِ وَرَاءَ قَلْبِهِ، وَقَلْبُ الْأَحْمَقِ وَرَاءَ لِسَانِهِ.","ob":"La langue du sage se trouve derrière son cœur [elle est contrôlée par l'examen attentif] et le cœur du sot se trouve derrière sa langue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m41":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وقد رُوِيَ عنه عليه السلام هذا المعنى بلفظ آخر، وهو قوله: قَلبُ الْأَحْمَقِ فِي فِيهِ، وَلِسَانُ الْعَاقِلِ فِي قَلْبِهِ.","ob":"(Autre version): Le cœur du sot est dans sa bouche et la langue du sage est dans son cœur. (Les deux phrases ont le même sens).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m42":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِبَعْضِ أَصْحَابِهِ فِي عِلَّةٍ اعْتَلَّهَا: جَعَلَ اللّٰهُ مَا كَانَ مِنْ شَكْوَاكَ حطّاً لِسَيِّئَاتِكَ، فَإِنَّ الْمَرَضَ لَا أَجْرَ فِيهِ، وَلكِنَّهُ يَحُطُّ السَّيِّئَاتِ، وَيَحُتُّهَا حَتَّ الْأَوْرَاقِ. وَإِنَّمَا الْأَجْرُ فِي الْقَوْلِ بِاللِّسَانِ، وَالْعَمَلِ بِالْأَيْدِي وَالْأَقْدَامِ، وَإِنَّ اللّٰهَ سُبْحَانَهُ يُدْخِلُ بِصِدْقِ النِّيَّةِ وَالسَّرِيرَةِ الصَّالِحَةِ مَنْ يَشَاءُ مِنْ عِبَادِهِ الْجَنَّةَ.","ob":"(Il dit à l'un de ses amis qui était malade): Que Dieu diminue tes mauvaises actions en contrepartie de tes plaintes. La maladie n'a pas de récompense, mais elle minimise les fautes et les frotte pour les enlever. Car la récompense s'attribue aux paroles de la langue et aux actions des mains et des pieds. Et Dieu reçoit dans le Paradis ceux qu'Il veut parmi ses serviteurs dont l'intention et le for intérieur sont véridiques.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m43":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي ذِكْرِ خَبَّابِ بْنِ الْأَرَتِّ: يَرْحَمُ اللَّهُ خَبَّابَ بْنَ الْأَرَتِّ، فَلَقَدْ أَسْلَمَ رَاغِباً، وَهَاجَرَ طَائِعاً، وَقَنِعَ بِالْكَفَافِ، وَرَضِيَ عَنِ اللَّهِ، وَعَاشَ مُجَاهِداً.","ob":"(Il dit au sujet de Khabbāb ibn al-Aratt): Que Dieu ait en pitié Khabbāb ibn al-Aratt! Il est entré dans l'Islam de plein gré, a émigré par obéissance, s'est contenté de vivre frugalement, a fait la volonté de Dieu et a vécu dans le <i>jihād</i>.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m44":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"طُوبَى لِمَنْ ذَكَرَ الْمَعَادَ، وَعَمِلَ لِلْحِسَابِ، وَقَنِعَ بِالْكَفَافِ، وَرَضِيَ عَنِ اللهِ.","ob":"Heureux celui qui se rappelle du Jour de la Résurrection, qui travaille pour le Jugement, se contente d'une vie moyenne et est agréé de Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m45":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَوْ ضَرَبْتُ خَيْشُومَ الْمُؤْمِنِ بِسَيْفِي هَذَا عَلَى أَنْ يُبْغِضَنِي مَا أَبْغَضَنِي، وَلَوْ صَبَبْتُ الدُّنْيَا بِجَمَّاتِهَا عَلَى الْمُنَافِقِ عَلَى أَنْ يُحِبَّنِي مَا أَحَبَّنِي. وَذَلِكَ أَنَّهُ قُضِيَ فَانْقَضَى عَلَى لِسَانِ النَّبِيِّ الْأُمِّيِّ صلى اللّٰه عليه وآله وسلَم؛ أَنَّهُ قَالَ: يَا عَلِيُّ، لَا يُبْغِضُكَ مُؤْمِنٌ، وَلَا يُحِبُّكَ مُنَافِقٌ.","ob":"Si je tranchais la gorge d'un croyant par mon épée pour qu'il me haïsse, il ne me haïrait pas; si j'offrais tous les biens terrestres à l'hypocrite pour qu'il m'aime, il ne m'aimerait pas. Car il est dit que le Prophète analphabète avait dit: O 'Alī, le croyant ne te haïra pas et l'hypocrite ne t'aimera pas.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m46":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"سَيِّئَةٌ تَسُوءُكَ خَيْرٌ عِنْدَ اللَّهِ مِنْ حَسَنَةٍ تُعْجِبُكَ.","ob":"Un malheur qui te fait du mal est mieux vu par Dieu qu'un bonheur qui te plaît.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m47":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قَدْرُ الرَّجُلِ عَلَى قَدْرِ هِمَّتِهِ، وَصِدْقُهُ عَلَى قَدْرِ مُرُوءَتِهِ، وَشَجَاعَتُهُ عَلَى قَدْرِ أَنَفَتِهِ، وَعِفَّتُهُ عَلَى قَدْرِ غَيْرَتِهِ.","ob":"La valeur de l'homme se mesure par son aspiration aux grandes choses, sa véracité est fonction de ses qualités viriles, son courage égalise sa pudeur et son abstinence de ce qui est illicite se mesure par son zèle.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m48":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الظَّفَرُ بالْحَزْمِ، وَالْحَزْمُ بِإِجَالَةِ الرَّأْيِ، وَالرَّأْيُ بِتَحْصِينِ الْأَسْرَارِ.","ob":"La victoire s'acquiert par la fermeté, celle-ci par l'examen des possibilités et le discernement par la conservation des secrets.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m49":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"احْذَرُوا صَوْلَةَ الْكَرِيمِ إذَا جَاعَ، واللَّئِيمِ إِذَا شَبِعَ.","ob":"Prenez garde contre l'attaque de l'homme noble s'il a faim et celle de l'ignoble s'il est rassasié.","obNotes":[],"an":"Redoutez la révolte du généreux affamé et celle de l'infâme rassasié. Le cœur de l'homme est méfiant. Il devient affable envers celui qui se le concilie. La personne à qui il revient le mieux de pardonner est celle qui dispose du pouvoir le plus large pour punir.","anIntro":"","anNotes":[],"diff":null}]},"m50":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قُلُوبُ الرِّجَالِ وَحْشِيَّةٌ، فَمَنْ تَأَلَّفَهَا أَقْبَلَتْ عَلَيْهِ.","ob":"Les cœurs des hommes sont sauvages; celui qui les apprivoise les attire.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m51":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"عَيْبُكَ مَسْتُورٌ مَا أَسْعَدَكَ جَدُّكَ.","ob":"Tes défauts sont cachés tant que tu es servi par la chance.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m52":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَوْلَى النَّاسِ بِالْعَفْوِ أَقْدَرُهُمْ عَلَى الْعُقُوبَةِ.","ob":"Les gens les plus dignes de pardon sont ceux qui sont les plus capables de punir.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m53":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"السَّخَاءُ مَا كَانَ ابْتِدَاءً؛ فَأَمَّا مَا كَانَ عَنْ مَسْأَلَةِ فَحَيَاءٌ وَتَذَمُّمٌ.","ob":"La générosité est une vertu innée; mais quand elle s'exerce occasionnellement elle devient une crainte du blâme et une fuite de la censure.","obNotes":[],"an":"La vraie générosité est volontaire. Celle qui est accordée sur demande l'est par complaisance et pour éviter le blâme.","anIntro":"","anNotes":[],"diff":null}]},"m54":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا غِنَى كَالْعَقْلِ؛ وَلَا فَقْرَ كَالْجَهْلِ؛ وَلَا مِيرَاثَ كَالْأَدَبِ؛ وَلَا ظَهِيرَ كَالْمُشَاوَرَةِ.","ob":"Il n'y a pas de richesse plus grande que l'intelligence, ni de pauvreté plus grande que l'ignorance, ni d'héritage meilleur que les valeurs morales, ni d'aide plus efficace que la consultation.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m55":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الصَّبْرُ صَبْرَانِ: صَبْرٌ عَلَى مَا تَكْرَهُ، وَصَبْرٌ عَمَّا تُحِبُّ.","ob":"La patience est dichotomique: supporter ce que tu hais et attendre ce que tu aimes.","obNotes":[],"an":"La patience est double: l'une face à ce que vous détestez et l'autre devant ce qui vous séduit.","anIntro":"","anNotes":[],"diff":null}]},"m56":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْغِنَى فِي الْغُرْبَةِ وَطَنٌ، وَالْفَقْرُ فِي الْوَطَنِ غُرْبَةٌ.","ob":"La richesse te procure une patrie à l'étranger, et la pauvreté dans la patrie est un exil.","obNotes":[],"an":"La richesse en exil est patrie, la misère dans la patrie est exil.","anIntro":"","anNotes":[],"diff":null}]},"m57":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْقَنَاعَةُ مَالٌ لَا يَنْفَدُ. (قال الرضيّ: وقد رُوِيَ هذا الكلام عن النبيّ صلي اللّٰه عليه وآله وسلّم).","ob":"La tempérance est un trésor inépuisable. (al-Raḍī attribue cette phrase au Prophète).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m58":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْمَالُ مَادَّةُ الشَّهَوَاتِ.","ob":"L'argent est la matière qui forme les passions.","obNotes":[],"an":"Les biens alimentent les désirs.","anIntro":"","anNotes":[],"diff":null}]},"m59":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ حَذَّرَكَ كَمَنْ بَشَّرَكَ.","ob":"Celui qui te prévient ressemble à celui qui t'annonce une bonne nouvelle.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m60":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اللِّسَانُ سَبُعٌ، إِنْ خُلِّيَ عَنْهُ عَقَرَ.","ob":"La langue est une bête fauve qui mord si on la lâche.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m61":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْمَرْأَةُ عَقْرَبٌ حُلْوَةُ اللَّسْبَةِ","ob":"La femme est un scorpion dont la piqûre est douce.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m62":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا حُيِّيْتَ بِتَحِيَّةٍ فَحَيِّ بِأَحْسَنَ مِنْهَا، وإِذَا أُسْدِيَتْ إِلَيْكَ يَدٌ فَكَافِئْهَا بِمَا يُرْبِي عَلَيْهَا، وَالْفَضْلُ مَعَ ذلِكَ لِلْبَادِئِ.","ob":"Lorsqu'on te salue réponds par une salutation meilleure. Lorsqu'une main est tendue à toi récompense-la de surcroît, car le mérite en revient à celui qui commence.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m63":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الشَّفِيعُ جَنَاحُ الطَّالِبِ.","ob":"L'intercesseur est l'aide du solliciteur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m64":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَهْلُ الدُّنْيَا كَرَكْبٍ يُسَارُ بِهِمْ وَهُمْ نِيَامٌ.","ob":"Les gens du monde ressemblent à des caravaniers qui traversent des distances tout en étant endormis.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m65":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فَقْدُ الْأَحِبَّةِ غُرْبَةٌ.","ob":"La perdition des bien-aimés est un exil.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m66":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فَوْتُ الْحَاجَةِ أَهْوَنُ مِنْ طَلَبِهَا إِلَى غَيْرِ أَهْلِهَا.","ob":"Manquer un besoin est plus facile que de le requérir pour ceux qui en sont indignes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m67":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"لَا تَسْتَحِ مِنْ إِعْطَاءِ الْقَلِيلِ، فَإِنَّ الْحِرْمَانَ أَقَلُّ مِنْهُ.","ob":"N'aie pas honte d'offrir un piètre don à quelqu'un, car l'en priver totalement a un impact plus dur.","obNotes":[],"an":"N'aie pas honte de donner peu car la privation sera bien moindre.","anIntro":"","anNotes":[],"diff":null}]},"m68":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعَفَافُ زِينَةُ الفقير، والشُّكْرُ زِينَةُ الغِنَى.","ob":"La sobriété est la parure de la pauvreté, et le remerciement est celle de la richesse.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m69":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا لَمْ يَكُنْ مَا تُرِيدُ فَلَا تُبَلْ مَا كُنْتَ.","ob":"Si ce que tu veux ne se fait pas n'en tiens pas compte.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m70":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَرَى الْجَاهِلَ إِلَّا مُفْرِطاً أَوْ مُفَرِّطاً.","ob":"Tu ne vois l'ignorant que dépassant les bornes ou dissipant son argent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m71":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا تَمَّ الْعَقْلُ نَقَصَ الْكَلاَمُ.","ob":"L'homme complètement intelligent est avare en ses paroles.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m72":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الدَّهرُ يُخْلِقُ الْأَبْدَانَ، وَيُجَدِّدُ الْآمَالَ، وَيُقَرِّبُ الْمَنِيَّةَ، ويُبَاعِدُ الْأُمْنِيَّةَ.","ob":"Le temps use les corps, renouvelle les espoirs, fait approcher la mort et éloigner les souhaits.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m73":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مَنْ نَصَبَ نَفْسَهُ لِلنَّاسِ إِمَاماً فَلْيَبْدَأْ بِتَعْلِيمِ نَفْسِهِ قَبْلَ تَعْلِيمِ غَيْرِهِ، وَلْيَكُنْ تَأْدِيبُهُ بِسِيرَتِهِ قَبْلَ تَأْدِيبِهِ بِلِسَانِهِ؛ وَمُعَلِّمُ نَفْسِهِ وَمُؤَدِّبُهَا أَحَقُّ بِالْإِجْلَالِ مِنْ مُعَلِّمِ النَّاسِ وَمُؤَدِّبِهِمْ.","ob":"Que celui qui se dresse comme imam devant les hommes commence par apprendre avant les autres. Qu'il donne une bonne éducation par sa conduite et non seulement par sa langue. Car celui qui est son propre maître et éducateur est plus digne de vénération que celui qui est le maître et l'éducateur des hommes.","obNotes":[],"an":"L'Imām dit: Celui qui s'érige en maître pour éduquer les autres doit commencer par son auto-éducation. Il doit édifier les autres par sa conduite avant de les édifier par ses paroles; un maître qui veille à être son propre éducateur, mérite plus de vénération que celui qui éduque les gens et les instruit.","anIntro":"","anNotes":[],"diff":null}]},"m74":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"نَفْسُ الْمَرْءِ خُطَاهُ إِلَى أَجَلِهِ.","ob":"La respiration de l'homme constitue autant de pas vers sa mort.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m75":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُلُّ مَعْدُود مُنْقَضٍ، وَكُلُّ مُتَوَقَّعٍ آتٍ.","ob":"Tout ce qu'on peut compter connaîtra un terme, et tout auquel on peut s'attendre aura lieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m76":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ الْأُمُورَ إذا اشْتَبَهَتْ اعْتُبِرَ آخِرُهَا بِأَوَّلِهَا.","ob":"Quand les choses se brouillent dans l'esprit, elles se terminent comme elles avaient commencé.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m77":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَمِنْ خَبَرِ ضِرَارِ بْنِ حَمْزَةَ الضَّبَائِيِّ عِنْدَ دُخُولِهِ عَلَى مُعَاوِيَةَ وَمَسْأَلَتِهِ لَهُ عَنْ أَمِيرِ الْمُؤْمِنِينَ: وَقَالَ: فَأَشْهَدُ لَقَدْ رَأَيْتُهُ فِى بَعْضِ مَوَاقِفِهِ وَقَدْ أَرْخَى اللَّيْلُ سُدُولَهُ وَهُوَ قَائِمٌ فِى مِحْرَابِهِ قَابِضٌ عَلَى لِحْيَتِهِ يَتَمَلْمَلُ تَمَلْمُلَ السَّلِيمِ، وَيَبْكِى بُكَاءَ الْحَزِينِ، وَيَقُولُ: يَا دُنْيَا يَا دُنْيَا، إِلَيْكِ عَنِّى، أَبِى تَعَرَّضْتِ؟ أَمْ إِلَيَّ تَشَوَّقْتِ؟ لَا حَانَ حِينُكِ! هَيْهَاتَ! غُرِّى غَيْرِى، لَا حَاجَةَ لِى فِيكِ، قَدْ طَلَّقْتُكِ ثَلَاثاً لَا رَجْعَةَ فِيهَا! فَعَيْشُكِ قَصِيرٌ، وَخَطَرُكِ يَسِيرٌ، وَأَمَلُكِ حَقِيرٌ. آهِ مِنْ قِلَّةِ الزَّادِ، وَطُولِ الطَّرِيقِ، وَبُعْدِ السَّفَرِ، وَعَظِيمِ الْمَوْرِدِ!","ob":"(Ḍirār ibn Ḥamza al-Ḍabā'ī raconte à Mu'āwiya qu'il avait vu le Prince des Croyants pendant la nuit, tenant sa barbe entre les mains, se tournant et se retournant comme s'il était piqué par un serpent, se lamentant et disant): O monde! Va-t-en! Est-ce à moi que tu t'attaques? Cherches-tu à me séduire? Tu es loin de réussir! Trompe un autre que moi; je n'ai nul besoin de toi. Je t'ai répudié trois fois d'une façon irréversible! La vie que tu donnes est courte, ton importance est minime et l'espoir en toi est médiocre. Oh! que les provisions sont peu nombreuses, la route longue, le voyage fatiguant et le but à atteindre difficile!","obNotes":[],"an":"O monde! va-t-en! Est-ce à moi que tu t'attaques? Cherches-tu à me séduire? Tu es loin d'y réussir. Trompe un autre que moi. Je n'ai nul besoin de toi. Je t'ai répudié trois fois, d'une manière définitive. Ton séjour est court, ton importance minime et l'espoir en toi est infime. Je souffre de la pénurie de la provision, de la longueur du chemin, de l'étendue du voyage et de l'ampleur du but à atteindre.","anIntro":"","anNotes":[],"diff":null}]},"m78":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"ومن كَلَامٍ لَهُ عليه السلام لِلسَّائِلِ الشَّامِيِّ لَمَّا سَأَلَهُ: أكان مَسِيرُنَا إِلَى الشَّامِ بِقَضَاءٍ مِنَ اللَّهِ وقدر؟ بَعْدَ كَلَامٍ طَوِيلٍ هَذَا مُخْتَارُهُ: وَيْحَكَ! لَعَلَّكَ ظَنَنْتَ قَضَاءً لَازِماً، وَقَدَراً حَاتِماً! ولو كَانَ ذَلِكَ كَذَلِكَ لَبَطَلَ الثَّوَابُ وَالْعِقَابُ، وَسَقَطَ الْوَعْدُ وَالْوَعِيدُ. إِنَّ اللَّهَ سُبْحَانَهُ أَمَرَ عِبَادَهُ تَخْيِيراً، وَنَهَاهُمْ تَحْذِيراً، وَكَلَّفَ يَسِيراً، وَلَمْ يُكَلِّفْ عَسِيراً، وَأَعْطَى عَلَى الْقَلِيلِ كَثِيراً؛ وَلَمْ يُعْصَ مَغْلُوباً، وَلَمْ يُطَعْ مُكْرِهاً، وَلَمْ يُرْسِلِ الْأَنْبِيَاءَ لَعِباً، وَلَمْ يُنْزِلِ الكتاب لِلْعِبَادِ عَبَثاً، وَلَا خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا: «ذَٰلِكَ ظَنُّ الَّذِينَ كَفَرُوا، فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِنَ النَّارِ».","ob":"(Un damascène lui demande si sa campagne contre le pays de Shām est déterminée par Dieu; il lui répond brièvement): Malheur à toi! Il se peut que tu croies au déterminisme [deux mots arabes sont utilisés ici: Al Qada' et Al Oadar. Al Qada' est la prescience divine des faits qui s'accomplissent en un lieu et temps déterminés. Al Qadar est l'accomplissement des choses lorsque leurs causes existent. Or, ni Al Qada', ni Al Qadar n'obligent le serviteur à accomplir ses actes]. S'il en est ainsi, il n'y aura ni récompense, ni punition, ni promesse, ni admonition. Dieu, qu'Il soit loué, a donné Ses ordres à Ses serviteurs tout en leur donnant le choix, les a avertis de s'abstenir [du mal], leur a imposé des devoirs faisables sans grandes difficultés; pour ce peu qu'Il a demandé, il a donné beaucoup en contrepartie; Il ne veut pas être désobéi ou obéi à contre-cœur; Il n'a pas envoyé les Prophètes par divertissement, ni fait descendre le Livre sans but, ni créé les cieux et la terre -et ce qu'il y a entre eux- en vain. C'est l'opinion des athées; malheur à eux à cause du Feu!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m79":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"خُذِ الْحِكْمَةَ أَنَّى كَانَتْ، فَإِنَّ الْحِكْمَةَ تَكُونُ فِي صَدْرِ الْمُنَافِقِ فَتَلَجْلَجُ فِي صَدْرِهِ حَتَّى تَخْرُجَ فَتَسْكُنَ إِلَى صَوَاحِبِهَا فِي صَدْرِ الْمُؤْمِن.","ob":"Prends la sagesse là où tu la trouves. Etant dans le cœur de l'hypocrite, elle se meut jusqu'à en sortir pour trouver la demeure de ses compagnes [les autres vertus] dans le cœur du croyant.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m80":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ، فَخُذِ الْحِكْمَةَ وَلَوْ مِنْ أَهْلِ النِّفَاقِ.","ob":"La sagesse est le but que le croyant a à atteindre. Prends donc la sagesse de chez les hypocrites mêmes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m81":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قِيمَةُ كُلِّ امْرِئٍ مَا يُحْسِنُهُ.","ob":"La valeur de tout individu se mesure par ce qu'il fait d'une façon parfaite.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m82":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"أُوصِيكُمْ بِخَمْسٍ لَوْ ضَرَبْتُمْ إِلَيْهَا آبَاطَ الْإِبِلِ، لَكَانَتْ لِذَلِكَ أَهْلًا: لَا يَرْجُوَنَّ أَحَدٌ مِنْكُمْ إِلَّا رَبَّهُ، وَلَا يَخَافَنَّ إِلَّا ذَنْبَهُ، وَلَا يَسْتَحِيَنَّ أَحَدٌ إِذَا لَمْ يَعْلَمِ الشَّيْءَ أَنْ يَتَعَلَّمَهُ، وَعَلَيْكُمْ بِالصَّبْرِ، فَإِنَّ الصَّبْرَ مِنَ الْإِيمَانِ كَالرَّأْسِ مِنَ الْجَسَدِ، وَلَا خَيْرَ فِي جَسَدٍ لَا رَأْسَ مَعَهُ، وَلَا فِي إِيمَانٍ لَا صَبْرَ مَعَهُ.","ob":"Je vous recommande cinq conseils dignes d'être suivis là où vous allez: Que chacun de vous n'espère qu'en Dieu, ne redoute que ses propres fautes, n'ait point honte d'avouer son ignorance s'il est interrogé sur une chose qu'il ignore et d'apprendre ce qu'il ne sait pas. Soyez patients, car la patience est pour la foi ce qu'est la tête pour le corps. Or, un corps sans tête ne sert à rien, et une foi sans patience est inutile.","obNotes":[],"an":"Je vous recommande cinq choses qui justifieraient toute peine pour y parvenir: Que chacun de vous n'espère qu'en Dieu, ne redoute que le péché, n'ait point honte s'il est interrogé sur une chose qu'il ignore, de répondre: je ne sais pas; qu'il n'ait point honte d'apprendre ce qu'il ignore; pratiquez la patience car elle est pour la foi ce qu'est la tête pour le corps; un corps sans tête est inutile, de même qu'une foi sans patience.","anIntro":"","anNotes":[],"diff":null}]},"m83":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِرَجُلٍ أَفْرَطَ فِي الثَّنَاءِ عَلَيْهِ، وَكَانَ لَهُ مُتَّهِماً: أَنَا دُونَ مَا تَقُولُ، وَفَوْقَ مَا فِي نَفْسِكَ.","ob":"(Il dit à un homme qui auparavant l'accusait et maintenant il le loue exagéramment): Je suis au-dessous de tes paroles mais au-dessus de tes pensées.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m86":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رَأْيُ الشَّيْخِ أَحَبُّ إِلَيَّ مِنْ جَلَدِ الْغُلاَمِ.","ob":"L'opinion du vieillard m'est plus aimable que la fermeté du jeune dans le combat.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m87":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"عَجِبْتُ لِمَنْ يَقْنَطُ وَمَعَهُ الِاسْتِغْفَارُ.","ob":"M'étonne celui qui désespère malgré la demande du pardon.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m88":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"كَانَ فِى الْأَرْضِ أَمَانَانِ مِنْ عَذَابِ اللَّهِ، وَقَدْ رُفِعَ أَحَدُهُمَا، فَدُونَكُمُ الْآخَرَ فَتَمَسَّكُوا بِهِ: أَمَّا الْأَمَانُ الَّذِى رُفِعَ فَهُوَ رَسُولُ اللَّهِ صَلَّى اللّٰه عَلَيْهِ وَآلِهِ وَسَلَّمّ، وَأَمَّا الْأَمَانُ الْبَاقِى فَالِاسْتِغْفَارُ. قَالَ اللَّهُ تَعَالَى: «وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ».","ob":"Il y avait sur la terre une double sécurité qui éloigne le châtiment de Dieu. La première était la présence parmi vous du Messager d'Allah (s). Après sa mort, il vous sert à vous attacher à la deuxième: demander pardon à Dieu qui dit: «Allah n'est point tel qu'Il les châtie, alors que tu es au milieu d'eux. Et Allah n'est point tel qu'Il les châtie alors qu'ils demandent pardon» (8,33).","obNotes":[],"an":"Sur la terre existaient deux protections contre le châtiment divin; l'une a été enlevée; tournez-vous vers la deuxième et tenez-vous fermement à elle. La protection enlevée était dans la personne du Messager d'Allah (s); l'autre qui nous reste est le repentir. Dieu a dit: «Dieu ne les châtiera pas tant que tu es au milieu d'eux; Dieu ne les châtiera pas quand ils se repentent».","anIntro":"","anNotes":[],"diff":null}]},"m89":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَصْلَحَ مَا بَيْنَهُ وَبَيْنَ اللّٰهِ أَصْلَحَ اللّٰهُ مَا بَيْنَهُ وَبَيْنَ النَّاسِ، وَمَنْ أَصْلَحَ أَمْرَ آخِرَتِهِ أَصْلَحَ اللّٰهُ لَهُ أَمْرَ دُنْيَاهُ، وَمَنْ كَانَ لَهُ مِنْ نَفْسِهِ وَاعِظٌ كَانَ عَلَيْهِ مِنَ اللّٰهِ حَافِظٌ.","ob":"Celui qui se réconcilie avec Dieu, Celui-ci le réconcilie avec les gens. Celui qui se rectifie en vue d'hériter l'autre monde, Dieu arrange ses affaires ici-bas. Celui qui met en œuvre ce qu'il prêche sera gardé par Dieu.","obNotes":[],"an":"Celui qui entretient de bonnes relations avec Dieu, Dieu veillera à ce que de bonnes relations s'établissent entre lui et les autres.","anIntro":"","anNotes":[],"diff":null}]},"m90":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْفَقِيهُ كُلُّ الْفَقِيهِ مَنْ لَمْ يُقَنِّطِ النَّاسَ مِنْ رَحْمَةِ اللهِ، وَلَمْ يُؤْيِسْهُمْ مِنْ رَوْحِ اللهِ، وَلَمْ يُؤْمِنْهُمْ مِنْ مَكْرِ اللَّهِ.","ob":"Le vrai jurisconsulte est celui qui ne fait pas désespérer les hommes de la miséricorde de Dieu, ne les décourage pas de Sa bienveillance et ne les garantit pas contre le châtiment imprévu de Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m91":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ هذِهِ الْقُلُوبَ تَمَلُّ كَمَا تَمَلُّ الْأَبْدَانُ، فَابْتَغُوا لَهَا طَرَائِفَ الحِكَم.","ob":"Ces cœurs s'ennuient comme les corps; exposez-leur des maximes nouvellement acquises.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m92":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَوْضَعُ الْعِلْمِ مَا وُقِفَ عَلَى اللِّسَانِ، وَأَرْفَعُهُ مَا ظَهَرَ فِي الْجَوَارِحِ وَالْأَرْكَانِ.","ob":"Le savoir le plus bas est celui qui émane des lèvres, et le plus élevé est celui qui se manifeste à travers les mains et la tête.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m93":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَقُولَنَّ أَحَدُكُمْ: «اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنَ الْفِتْنَةِ» لِأَنَّهُ لَيْسَ أَحَدٌ إِلَّا وَهُوَ مُشْتَمِلٌ عَلَى فِتْنَةٍ، وَلَكِنْ مَنِ اسْتَعَاذَ فَلْيَسْتَعِذْ مِنْ مُضِلَّاتِ الْفِتَنِ، فَإِنَّ اللَّهَ سُبْحَانَهُ يَقُولُ: «وَاعْلَمُوا أَنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ»، وَمَعْنَى ذَلِكَ أَنَّهُ يَخْتَبِرُهُمْ بِالْأَمْوَالِ وَالْأَوْلَادِ لِيَتَبَيَّنَ السَّاخِطَ لِرِزْقِهِ، وَالرَّاضِيَ بِقِسْمِهِ، وَإِنْ كَانَ سُبْحَانَهُ أَعْلَمَ بِهِمْ مِنْ أَنْفُسِهِمْ، وَلَكِنْ لِتَظْهَرَ الْأَفْعَالُ الَّتِى بِهَا يُسْتَحَقُّ الثَّوَابُ وَالْعِقَابُ، لِأَنَّ بَعْضَهُمْ يُحِبُّ الذُّكُورَ وَيَكْرَهُ الْإِنَاثَ، وَبَعْضَهُمْ يُحِبُّ تَثْمِيرَ الْمَالِ، وَيَكْرَهُ انْثِلَامَ الْحَالِ. (قال الرضىّ: وهذا من غريب ما سُمِع منه فى التفسير).","ob":"Que personne parmi vous ne dise: «Notre Seigneur, je Te demande de me sauver de la sédition», car il n'y a personne qui soit exempt des germes de celle-ci. Et que celui qui recourt à Dieu demande de ne pas être mis à l'épreuve, car Dieu dit «Sachez que vos biens et vos enfants ne sont qu'une épreuve» (8,28). Cela veut dire que Dieu éprouve les hommes à travers leurs biens et leurs enfants pour qu'on sache ceux qui se révoltent contre leur part des biens et ceux qui l'acceptent. Bien que Dieu connaisse leurs positions respectives, il faut que leurs actions qui méritent la récompense ou le châtiment soient déclarées publiquement. Car quelques-uns aiment leur fils et haïssent leurs filles, d'autres préfèrent fructifier leurs biens et n'aiment pas qu'ils diminuent. (al-Raḍī de commenter: c'est une des étranges interprétations imputées à 'Alī).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m94":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَسُئِلَ عن الْخَيْرِ مَا هُوَ؟ فَقَالَ: لَيْسَ الْخَيْرُ أَنْ يَكْثُرَ مَالُكَ وولدك، وَلَكِنَّ الْخَيْرَ أَنْ يَكْثُرَ عِلْمُكَ، وَأَنْ يَعْظُمَ حِلْمُكَ، وَأَنْ تُبَاهِيَ النَّاسَ بِعِبَادَةِ رَبِّكَ؛ فَإِنْ أَحْسَنْتَ حَمِدْتَ اللَّهَ، وَإِنْ أَسَأْتَ اسْتَغْفَرْتَ اللَّهَ. وَلَا خَيْرَ فِى الدُّنْيَا إِلَّا لِرَجُلَيْنِ: رَجُلٍ أَذْنَبَ ذُنُوباً فَهُوَ يَتَدَارَكُهَا بِالتَّوْبَةِ، وَرَجُلٍ يُسَارِعُ فِى الْخَيْرَاتِ.","ob":"(On lui demande de définir le bien, il dit): Le bien n'implique pas l'augmentation de tes biens et de tes enfants, mais plutôt l'augmentation de ton savoir et de ta longanimité; le bien veut que tu rivalises les gens dans l'adoration de ton Seigneur. Si tu fais bien tu loues Dieu, si tu fais mal tu lui demandes pardon. Il n'y a de bien dans l'autre monde que pour deux hommes: un qui commet des péchés mais s'en repent, et un autre qui fait du bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m95":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَقِلُّ عَمَلٌ مَعَ التَّقْوَى، وَكَيْفَ يَقِلُّ مَا يُتَقَبَّلُ؟","ob":"Une action faite avec piété ne s'amenuise pas du fait qu'elle a été acceptée.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m96":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ أَوْلَى النَّاسِ بِالْأَنْبِيَاءِ أَعْلَمُهُمْ بِمَا جَاءُوا بِهِ ، ثُمَّ تَلاَ: «إِنَّ أَوْلَى النَّاسِ بِإِبْرَاهِيمَ لَلَّذِينَ اتَّبَعُوهُ وَهَٰذَا النَّبِيُّ وَالَّذِينَ آمَنُوا» الآية، ثُمَّ قَالَ: إِنَّ وَلِيَّ مُحَمَّد مَنْ أَطَاعَ اللّٰهَ وإِنْ بَعُدَتْ لُحْمَتُهُ، وَإِنَّ عَدُوَّ مُحَمَّد مَنْ عَصَى اللّٰهَ وَإِنْ قَرُبَتْ قَرَابَتُهُ!","ob":"Les gens les plus dignes des prophètes sont ceux qui connaissent le plus leurs enseignements. «Certes les hommes les plus dignes de se réclamer d'Abraham, sont ceux qui l'ont suivi, ainsi que ce Prophète, et ceux qui ont la foi» (3,68). L'ami de Muḥammad est celui qui obéit à Dieu bien qu'il ne soit pas de son lignage, et l'ennemi de Muḥammad est celui qui désobéit à Dieu, même s'il est son parent le plus proche!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m97":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"نَوْمٌ عَلَى يَقِينٍ خَيْرٌ مِنْ صَلَاةٍ فِى شَكٍّ.","ob":"Dormir en état de croyance certaine vaut mieux que prier en état de doute.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m98":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اعْقِلُوا الْخَبَرَ إِذَا سَمِعْتُمُوهُ عَقْلَ رِعَايَةٍ لَا عَقْلَ رِوَايَةٍ، فَإِنَّ رُوَاةَ الْعِلْمِ كَثِيرٌ، وَرُعَاتَهُ قَلِيلٌ.","ob":"Comprenez en profondeur la nouvelle que vous entendez. Nombreux sont ceux qui rapportent des nouvelles, mais ceux qui les écoutent et les méditent sont une minorité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m100":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"اللَّهُمَّ إِنَّكَ أَعْلَمُ بِى مِنْ نَفْسِى، وَأَنَا أَعْلَمُ بِنَفْسِى مِنْهُمْ.","ob":"Mon Dieu, Tu me connais mieux que moi-même et je me connais mieux que les autres.","obNotes":[],"an":"A des gens qui le louaient en sa présence l'Imām dit: Seigneur! Vous me connaissez mieux que moi-même; je me connais mieux qu'ils ne me connaissent. Faites que nous soyons meilleur que ce qu'ils pensent et pardonnez-nous ce qu'ils ignorent de nous.","anIntro":"","anNotes":[],"diff":null}]},"m102":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَأْتِى عَلَى النَّاسِ زَمَانٌ لَا يُقَرَّبُ فِيهِ إِلَّا الْمَاحِلُ، وَلَا يُظَرَّفُ فِيهِ إِلَّا الْفَاجِرُ، وَلَا يُضَعَّفُ فِيهِ إِلَّا الْمُنْصِفُ، يَعُدُّونَ الصَّدَقَةَ فِيهِ غُرْماً، وَصِلَةَ الرَّحِمِ مَنّاً، وَالْعِبَادَةَ اسْتِطَالَةً عَلَى النَّاسِ! فَعِنْدَ ذَلِكَ يَكُونُ السُّلْطَانُ بِمَشُورَةِ النِّسَاءِ، وَإِمَارَةِ الصِّبْيَانِ، وَتَدْبِيرِ الْخِصْيَانِ!","ob":"Un temps viendra où les gens n'accueilleront que le calomniateur, ne trouveront beau que le libertin et ne taxeront de faiblesse que l'équitable. Alors, ils considéreront l'aumône comme une taxe, la consanguinité comme une faveur et l'adoration comme un empiètement sur les droits d'autrui! En ce temps-là, le pouvoir s'exercera par le moyen des conseils des femmes, des ordres des garçons et de la direction des eunuques!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m103":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَرُئِيَ عَلَيْهِ إِزَارٌ خَلَقٌ مَرْقُوعٌ فَقِيلَ لَهُ فِى ذَلِكَ، فَقَالَ: يَخْشَعُ لَهُ الْقَلْبُ، وَتَذِلُّ بِهِ النَّفْسُ، وَيَقْتَدِى بِهِ الْمُؤْمِنُونَ.","ob":"(On le voit porter un vieux manteau raccommodé; on lui demande pourquoi le porte-t-il; il répond): Il attendrit le cœur, humilie l'âme et fournit un sujet d'imitation aux croyants.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"إِنَّ الدُّنْيَا وَالْآخِرَةَ عَدُوَّانِ مُتَفَاوِتَانِ، وَسَبِيلَانِ مُخْتَلِفَانِ؛ فَمَنْ أَحَبَّ الدُّنْيَا وَتَوَلَّاهَا أَبْغَضَ الْآخِرَةَ وَعَادَاهَا، وَهُمَا بِمَنْزِلَةِ الْمَشْرِقِ وَالْمَغْرِبِ، وَمَاشٍ بَيْنَهُمَا؛ كُلَّمَا قَرُبَ مِنْ وَاحِدٍ بَعُدَ مِنَ الْآخَرِ، وَهُمَا بَعْدُ ضَرَّتَانِ!","ob":"Ce monde et l'autre monde sont deux ennemis inconciliables et deux voies distinctes. Celui qui aime le monde ici-bas et le rend maître de ses comportements hait l'autre monde et le considère comme son ennemi. Ce sont deux antipodes, comme l'orient et l'occident. Celui qui, en marchant, s'approche de l'un, s'éloigne de l'autre. On dirait deux co-épouses!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m104":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَعَنْ نَوْفٍ الْبَكَالِيِّ، قَالَ: رَأَيْتُ أَمِيرَ الْمُؤْمِنِينَ عليه السلام ذَاتَ لَيْلَةٍ، وَقَدْ خَرَجَ مِنْ فِرَاشِهِ، فَنَظَرَ فِي النُّجُومِ فَقَالَ لِي: يَا نَوْفُ، أراقد أَنْتَ أَمْ رَامِقٌ؟ فَقُلْتُ: بَلْ رَامِقٌ؛ فَقَالَ:","ob":"(Nawf al-Bakālī raconte qu'il vit le Prince des Croyants quitter son lit un soir pour regarder les étoiles et lui dit: O Nawf, es-tu couché ou non? Etant éveillé, 'Alī lui dit):","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"يَا نَوْفُ، طُوبَى لِلزَّاهِدِينَ فِى الدُّنْيَا، الرَّاغِبِينَ فِى الْآخِرَةِ، أُولَئِكَ قَوْمٌ اتَّخَذُوا الْأَرْضَ بِسَاطاً، وَتُرَابَهَا فِرَاشاً، وَمَاءَهَا طِيباً، وَالْقُرْآنَ شِعَاراً، وَالدُّعَاءَ دِثَاراً، ثُمَّ قَرَضُوا الدُّنْيَا قَرْضاً عَلَى مِنْهَاجِ الْمَسِيحِ.","ob":"O Nawf, bienheureux sont ceux qui font peu de cas du monde et désirent l'autre monde. Ce sont des gens qui font de la terre un tapis, de son sol un lit, de ses eaux un odorant, du Coran un livre de lecture intime, de l'invocation un signe d'obédience à Dieu; puis ils ont coupé le monde en petits morceaux d'après la méthode d'ascèse du Christ.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[3],"ar":"يَا نَوْفُ، إِنَّ داوود عليه السلام قَامَ فِى مِثْلِ هَذِهِ السَّاعَةِ مِنَ اللَّيْلِ فَقَالَ: إِنَّهَا لَسَاعَةٌ لَا يَدْعُو فِيهَا عَبْدٌ إِلَّا اسْتُجِيبَ لَهُ، إِلَّا أَنْ يَكُونَ عَشَّاراً أَوْ عَرِيفاً أَوْ شُرْطِيّاً، أَوْ صَاحِبَ عَرْطَبَةٍ أَوْ صَاحِبَ كَوْبَةٍ.","ob":"O Nawf, David s'est réveillé à cette même heure de la nuit pour dire: c'est une heure où les serviteurs invoquent Dieu et Lui les exauce, sauf s'ils sont des publicains, des espions, des policiers, des joueurs de cymbale ou de tambour.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m105":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ اللَّهَ افْتَرَضَ عَلَيْكُمْ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ لَكُمْ حُدُوداً، فَلَا تَعْتَدُوهَا؛ وَنَهَاكُمْ عَنْ أَشْيَاءَ، فَلَا تَنْتَهِكُوهَا؛ وَسَكَتَ لَكُمْ عَنْ أَشْيَاءَ وَلَمْ يَدَعْهَا نِسْيَاناً، فَلَا تَتَكَلَّفُوهَا.","ob":"Dieu vous a imposé des devoirs que vous ne devez pas perdre de vue; Il vous a établi des obligations que vous ne devez pas dépasser; Il vous a interdit des actions que vous ne devez pas faire; et Il vous a permis des choses - non par oubli - que vous n'êtes pas tenus de vous en abstenir.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m106":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَتْرُكُ النَّاسُ شَيْئاً مِنْ أَمْرِ دِينِهِمْ لِاسْتِصْلَاحِ دُنْيَاهُمْ إِلَّا فَتَحَ اللَّهُ عَلَيْهِمْ مَا هُوَ أَضَرُّ مِنْهُ.","ob":"Dès que les hommes se libèrent de quelques devoirs religieux pour les remplacer par des actes mondains, Dieu leur envoie des difficultés plus dures.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m107":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رُبَّ عَالِمٍ قَدْ قَتَلَهُ جَهْلُهُ، وَعِلْمُهُ مَعَهُ لَا يَنْفَعُهُ.","ob":"Il se peut qu'un savant soit tué par son ignorance tandis que sa science ne lui sert de rien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m108":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَقَدْ عُلِّقَ بِنِيَاطِ هَذَا الْإِنْسَانِ بَضْعَةٌ هِيَ أَعْجَبُ مَا فِيهِ: وذلك الْقَلْبُ. وَذَلِكَ أَنَّ لَهُ مَوَادَّ مِنَ الْحِكْمَةِ وَأَضْدَاداً مِنْ خِلَافِهَا؛ فَإِنْ سَنَحَ لَهُ الرَّجَاءُ أَذَلَّهُ الطَّمَعُ، وَإِنْ هَاجَ بِهِ الطَّمَعُ أَهْلَكَهُ الْحِرْصُ، وَإِنْ مَلَكَهُ الْيَأْسُ قَتَلَهُ الْأَسَفُ، وَإِنْ عَرَضَ لَهُ الْغَضَبُ اشْتَدَّ بِهِ الْغَيْظُ، وَإِنْ أَسْعَدَهُ الرِّضَى نَسِيَ التَّحَفُّظَ، إنْ غَالَهُ الْخَوْفُ شَغَلَهُ الْحَذَرُ، وَإِنِ اتَّسَعَ لَهُ الْأَمْرُ اسْتَلَبَتْهُ الْغِرَّةُ، وَإِنْ أَفَادَ مَالًا أَطْغَاهُ الْغِنَى، وَإِنْ أَصَابَتْهُ مُصِيبَةٌ فَضَحَهُ الْجَزَعُ، وَإِنْ عَضَّتْهُ الْفَاقَةُ شَغَلَهُ الْبَلَاءُ، وَإِنْ جَهَدَهُ الْجُوعُ قَعَدَ بِهِ الضَّعْفُ، وَإِنْ أَفْرَطَ بِهِ الشِّبَعُ كَظَّتْهُ الْبِطْنَةُ. فَكُلُّ تَقْصِيرٍ بِهِ مُضِرٌّ، وَكُلُّ إِفْرَاطٍ لَهُ مُفْسِدٌ.","ob":"Un morceau de viande suspendu aux veines de cet homme est le muscle le plus merveilleux: il s'agit du cœur ; siège de la sagesse et de ses contraires. Si l'homme voit poindre l'espérance il sera humilié par la convoitise. Si celle-ci apparaît, elle sera matée par l'avarice. Si l'homme est victime du désespoir, il sera tué par l'affliction. S'il se fâche, il deviendra sujet à une grande colère. S'il est heureux et satisfait il oubliera la circonspection. S'il a une grande peur, il deviendra prudent et prendra ses précautions. S'il est bien à l'aise il sera volé par la négligence. S'il gagne de l'argent la richesse le rendra injuste. S'il lui arrive un malheur il sera confondu par la peur. S'il est mordu par la pauvreté il sera préoccupé par la misère. S'il est exténué par la faim il tombera de faiblesse. S'il mange avec exagération il sera pris par les douleurs de l'estomac. Toute insuffisance lui est nuisible et toute exagération le corrompt.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m110":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يُقِيمُ أَمْرَ اللَّهِ سُبْحَانَهُ إِلَّا مَنْ لَا يُصَانِعُ، وَلَا يُضَارِعُ، وَلَا يَتَّبِعُ الْمَطَامِعَ.","ob":"N'obéit à l'ordre de Dieu que celui qui ne flatte point, qui ne recherche point les vanités et qui ne suit point l'avidité des ambitions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m113":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا مَالَ أَعْوَدُ مِنَ الْعَقْلِ، وَلَا وَحْدَةَ أَوْحَشُ مِنَ الْعُجْب، وَلَا عَقْلَ كَالتَّدْبِيرِ، وَلَا كَرَمَ كَالتَّقْوَى، وَلَا قَرين كَحُسْنِ الخُلْقِ، وَلَا مِيرَاثَ كَالْأَدَبِ، وَلَا قَائِدَ كَالتَّوْفِيقِ، وَلَا تِجَارَةَ كَالْعَمَلِ الصَّالِحِ، وَلَا رِبْحَ كَالثَّوَابِ، وَلَا وَرَعَ كالْوُقُوفِ عِنْدَ الشُّبْهَةِ، وَلَا زُهْدَ كَالزُّهْدِ فِي الْحَرَامِ، وَلَا عِلْمَ كَالتَّفَكُّرِ، وَلَا عِبَادَةَ كَأَدَاءِ الْفَرائِضِ، وَلَا إِيمَانَ كَالْحَيَاءِ وَالصَّبْرِ، وَلَا حَسَبَ كَالتَّوَاضُعِ، وَلَا شَرَفَ كَالْعِلْمِ، وَلَا عِزَّ كالحِلم، ولا مُظَاهَرَةَ أَوْثَقُ مِن المُشاورة.","ob":"Il n'y a d'argent plus utile que l'intelligence, ni de solitude plus amère que d'être infatué de soi-même. Pas d'intelligence comme le maniement d'une affaire, de générosité comme la piété, de compagnon comme le bon caractère, d'héritage comme la bonne éducation, de crainte comme l'arrêt du doute, d'ascèse comme le refus de l'illicite, de science comme la ratiocination, de culte comme l'exécution des obligations, de foi comme la pudeur et la patience, de lignage comme l'humilité, de dignité comme la science, d'honneur comme la clémence et d'assistance comme la consultation.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m114":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا اسْتَوْلَى الصَّلَاحُ عَلَى الزَّمَانِ وَأَهْلِهِ، ثُمَّ أَسَاءَ رَجُلٌ الظَّنَّ بِرَجُلٍ، لَمْ تَظْهَرْ مِنْهُ حَوْبَةٌ فَقَدْ ظَلَمَ! وَإِذَا اسْتَوْلَى الْفَسَادُ عَلَى الزَّمَانِ وَأَهْلِهِ، فَأَحْسَنَ رَجُلٌ الظَّنَّ بِرَجُلٍ فَقَدْ غَرَّرَ!","ob":"Si le bien régnait sur le monde et les hommes, puis si l'un d'eux pensait mal d'un autre qui n'a fait aucun mal, il serait injuste. Si, par contre, c'est le mal qui régnait et si un homme avait une bonne opinion d'un autre, il risquerait d'être en danger.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m115":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقِيلَ لَهُ عليه السلام: كَيْفَ نَجِدُكَ يَا أَمِيرَ الْمُؤْمِنِينَ؟ فَقَالَ عليه السلام: كَيْفَ يَكُونُ حَالُ مَنْ يَفْنَى بِبَقَائِهِ، وَيَسْقَمُ بِصِحَّتِهِ وَيُؤْتَى مِنْ مَأْمَنِهِ!","ob":"(On lui dit: Comment vas-tu, ô Prince des Croyants? Il répondit): Dans quel état se trouve celui qui avance vers l'annihilation tant qu'il est en vie, qui tend vers la maladie de la vieillesse et qui trouvera la mort dans son propre refuge?","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m117":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"هَلَكَ فِيَّ رَجُلَانِ: مُحِبٌّ غَالٍ، وَمُبْغِضٌ قَالٍ.","ob":"Deux types d'hommes périssent à cause de moi: celui qui exagère dans l'amour qu'il me porte et celui qui me hait fortement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m119":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَثَلُ الدُّنْيَا كَمَثَلِ الْحَيَّةِ لَيِّنٌ مَسُّهَا، وَالسَّمُّ النَّاقِعُ فِى جَوْفِهَا، يَهْوِى إِلَيْهَا الْغِرُّ الْجَاهِلُ، وَيَحْذَرُهَا ذُو اللُّبِّ الْعَاقِلُ!","ob":"La vie terrestre ressemble à une couleuvre à la peau très lisse et au venin mortel. Elle attire le jeune ignorant mais est évitée par le sage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m121":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"شَتَّانَ مَا بَيْنَ عَمَلَيْنِ: عَمَلٍ تَذْهَبُ لَذَّتُهُ وَتَبْقَى تَبِعَتُهُ، وَعَمَلٍ تَذْهَبُ مَؤُونَتُهُ وَيَبْقَى أَجْرُهُ.","ob":"O la grande différence entre une action dont le plaisir se dissipe mais la responsabilité reste et une autre dont les provisions s'en aillent mais sa récompense reste.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m122":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَتَبِعَ جِنَازَةً فَسَمِعَ رَجُلًا يَضْحَكُ، فَقَالَ: كَأَنَّ الْمَوْتَ فِيهَا عَلَى غَيْرِنَا كُتِبَ، وَكَأَنَّ الْحَقَّ فِيهَا عَلَى غَيْرِنَا وَجَبَ، وَكَأَنَّ الَّذِى نَرَى مِنَ الْأَمْوَاتِ سَفْرٌ عَمَّا قَلِيلٍ إِلَيْنَا رَاجِعُونَ! نُبَوِّئُهُمْ أَجْدَاثَهُمْ، وَنَأْكُلُ تُرَاثَهُمْ، كَأَنَّا مُخَلَّدُونَ بَعْدَهُمْ! ثُمَّ قَدْ نَسِينَا كُلَّ وَاعِظٍ وَوَاعِظَةٍ، وَرُمِينَا بِكُلِّ فَادِحٍ وَجَائِحَةٍ!!","ob":"(Dans un convoi funèbre, il entend le rire d'un homme; il commente): C'est comme si la mort ne nous atteignait pas, si les obligations ne nous concernent pas et si les morts sont des voyageurs qui bientôt seront parmi nous! Nous les faisons descendre dans leurs tombes, nous profitons de leur héritage comme si nous étions immortels après eux! Puis nous oublierons toute prédication et toute homélie et nous serons touchés par toute affaire accablante et toute épidémie!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m123":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"طُوبَى لِمَنْ ذَلَّ فِى نَفْسِهِ، وَطَابَ كَسْبُهُ، وَصَلَحَتْ سَرِيرَتُهُ، وَحَسُنَتْ خَلِيقَتُهُ، وَأَنْفَقَ الْفَضْلَ مِنْ مَالِهِ، وَأَمْسَكَ الْفَضْلَ مِنْ لِسَانِهِ، وَعَزَلَ عَنِ النَّاسِ شَرَّهُ وَوَسِعَتْهُ السُّنَّةُ، وَلَمْ يُنْسَبْ إلَى الْبِدْعَةِ. قال الرضيّ: أقول: ومن الناس من ينسب هذا الكلام إلى رسول اللّٰه صلى اللّٰه عليه وآله وسلّم، وكذلك الذي قبله.","ob":"Bienheureux celui qui s'humilie, gagne légalement son pain, est intrinsèquement bon, se pare de vertus, dépense son argent pour faire le bien, retient sa langue, ne fait pas de mal aux hommes, suit les recommandations de la Sunna et n'appartient à aucune hérésie. (al-Raḍī attribue ces paroles et celles qui les ont devancées au Messager d'Allah (s)).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m124":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"غَيْرَةُ الْمَرْأَةِ كُفْرٌ، وَغَيْرَةُ الرَّجُلِ إِيمَانٌ.","ob":"La jalousie de la femme amène l'homme à l'athéisme; celle de l'homme relève de la foi[!]","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m125":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"لَأَنْسُبَنَّ الْإِسْلَامَ نِسْبَةً لَمْ يَنْسُبْهَا أَحَدٌ قَبْلِى. الْإِسْلَامُ هُوَ التَّسْلِيمُ، وَالتَّسْلِيمُ هُوَ الْيَقِينُ، وَالْيَقِينُ هُوَ التَّصْدِيقُ، وَالتَّصْدِيقُ هُوَ الْإِقْرَارُ، وَالْإِقْرَارُ هُوَ الْأَدَاءُ، وَالْأَدَاءُ هُوَ الْعَمَلُ.","ob":"Je tiens à délimiter l'islam d'une façon non précédée avant moi: l'Islam est la soumission, la soumission est la connaissance certaine, la certitude est la croyance, la croyance est l'aveu d'une dette, cet aveu implique le payement de cette dette et, finalement, le payement est l'action.","obNotes":[],"an":"Je qualifierai l'Islam comme personne ne l'a fait avant moi. L'Islam est résignation; la résignation est certitude; la certitude est croyance; la croyance est reconnaissance, la reconnaissance est acquittement de ses devoirs; l'acquittement est action.","anIntro":"","anNotes":[],"diff":null}]},"m126":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"عَجِبْتُ لِلْبَخِيلِ يَسْتَعْجِلُ الْفَقْرَ الَّذِى مِنْهُ هَرَبَ، وَيَفُوتُهُ الْغِنَى الَّذِى إِيَّاهُ طَلَبَ، فَيَعِيشُ فِى الدُّنْيَا عَيْشَ الْفُقَرَاءِ، وَيُحَاسَبُ فِى الْآخِرَةِ حِسَابَ الْأَغْنِيَاءِ؛ وَعَجِبْتُ لِلْمُتَكَبِّرِ الَّذِى كَانَ بِالْأَمْسِ نُطْفَةً، وَيَكُونُ غَداً جِيفَةً؛ وَعَجِبْتُ لِمَنْ شَكَّ فِى اللَّهِ، وَهُوَ يَرَى خَلْقَ اللَّهِ؛ وَعَجِبْتُ لِمَنْ نَسِيَ الْمَوْتَ، وَهُوَ يَرَى الْمَوْتَى؛ وَعَجِبْتُ لِعَامِرٍ دَارَ الْفَنَاءِ وَتَارِكٍ دَارَ الْبَقَاءِ.","ob":"Je m'étonne de voir l'avare se hâter vers la pauvreté qu'il avait fuie et voir la richesse s'esquiver devant ses yeux, vivant en ce monde comme les pauvres pour être jugé dans l'autre comme on juge les riches. Je m'étonne du comportement de l'orgueilleux qui, jadis, était une gouttelette et sera demain une charogne. M'étonne aussi celui qui doute en Dieu tout en voyant Ses œuvres créées, celui qui oublie la mort tout en voyant les mourants... et celui qui construit la demeure périssable en délaissant la demeure durable.","obNotes":[],"an":"L'Imām dit: l'avare m'étonne: il se hâte vers la misère qu'il fuit, manque la richesse qu'il convoite, traîne dans ce monde l'existence des pauvres, subit dans l'éternité le châtiment des riches. Je suis étonné par l'orgueilleux qui, hier, était sperme et demain sera cadavre en putréfaction; je suis sidéré par celui qui doute de Dieu alors qu'il voit la création, par celui qui oublie la mort alors qu'il voit les morts, par celui qui renie la deuxième naissance alors qu'il a déjà vu la première, par celui qui édifie dans un monde éphémère et oublie le monde éternel.","anIntro":"","anNotes":[],"diff":null}]},"m127":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ قَصَّرَ فِى الْعَمَلِ ابْتُلِيَ بِالْهَمِّ، وَلَا حَاجَةَ لِلَّهِ فِيمَنْ لَيْسَ لِلَّهِ فِى مَالِهِ وَنَفْسِهِ نَصِيبٌ.","ob":"Celui qui va lentement en besogne sera frappé par un malheur. Dieu n'a que faire de celui qui ne Lui donne une part de ses biens et de son âme.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m128":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"تَوَقَّوُا الْبَرْدَ فِى أَوَّلِهِ، وَتَلَقَّوْهُ فِى آخِرِهِ، فَإِنَّهُ يَفْعَلُ فِى الْأَبْدَانِ كَفِعْلِهِ فِى الْأَشْجَارِ، أَوَّلُهُ يُحْرِقُ وَآخِرُهُ يُورِقُ.","ob":"Ne vous exposez pas au froid dans son début et recevez-le dans sa dernière phase, car il agit sur les corps comme il le fait avec les arbres: au début il les brûle et à la fin il fait pousser leurs feuilles.","obNotes":[],"an":"Tenez-vous en garde contre le froid à son début et accueillez-le vers sa fin car il agit sur les corps comme sur les arbres: en automne il flétrit et au printemps il fait fleurir.","anIntro":"","anNotes":[],"diff":null}]},"m129":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"عِظَمُ الْخَالِقِ عِنْدَكَ يُصَغِّرُ الْمَخْلُوقَ فِى عَيْنِكَ.","ob":"La grandeur du Créateur amoindrit le créé à tes yeux.","obNotes":[],"an":"La magnificence du Créateur rend petite la créature à vos yeux.","anIntro":"","anNotes":[],"diff":null}]},"m130":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ وَقَدْ رَجَعَ مِنْ صِفِّينَ، فَأَشْرَفَ عَلَى الْقُبُورِ بِظَاهِرِ الْكُوفَةِ: يَا أَهْلَ الدِّيَارِ الْمُوحِشَةِ، وَالْمَحَالِّ الْمُقْفِرَةِ، وَالْقُبُورِ الْمُظْلِمَةِ؛ يَا أَهْلَ التُّرْبَةِ، يَا أَهْلَ الْغُرْبَةِ، يَا أَهْلَ الْوَحْدَةِ، يَا أَهْلَ الْوَحْشَةِ، أَنْتُمْ لَنَا فَرَطٌ سَابِقٌ، وَنَحْنُ لَكُمْ تَبَعٌ لَاحِقٌ. أَمَّا الدُّورُ فَقَدْ سُكِنَتْ، وَأَمَّا الْأَزْوَاجُ فَقَدْ نُكِحَتْ، وَأَمَّا الْأَمْوَالُ فَقَدْ قُسِمَتْ. هَذَا خَبَرُ مَا عِنْدَنَا، فَمَا خَبَرُ مَا عِنْدَكُمْ؟ ثُمَّ الْتَفَتَ إِلَى أَصْحَابِهِ فَقَالَ: أَمَا لَوْ أُذِنَ لَهُمْ فِى الْكَلَامِ لَأَخْبَرُوكُمْ أَنَّ «خَيْرَ الزَّادِ التَّقْوَىٰ».","ob":"(De retour de Ṣiffīn, il contemple les tombes aux environs de Kūfa et dit): O habitants des demeures désertes, des lieux non habités et des tombes obscures! O gens de la terre étrangère, qui vivez seuls, vous êtes pour nous des devanciers et nous sommes vos successeurs. Chez nous les maisons sont habitées, les couples se marient et les biens sont divisés. Qu'y a-t-il chez vous... (Puis il regarde ses compagnons et dit): S'ils étaient autorisés à parler ils vous auraient raconté que «la piété est la meilleure provision».","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m131":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام وَقَدْ سَمِعَ رَجُلًا يَذُمُّ الدُّنْيَا: أَيُّهَا الذَّامُّ لِلدُّنْيَا، الْمُغْتَرُّ بِغُرُورِهَا، الْمَخْدُوعُ بِأَبَاطِيلِهَا! أتغْتَرّ بِالدُّنْيَا ثُمَّ تَذُمُّهَا؟ أَنْتَ الْمُتَجَرِّمُ عَلَيْهَا، أَمْ هِيَ الْمُتَجَرِّمَةُ عَلَيْكَ؟ مَتَى اسْتَهْوَتْكَ؟... إِنَّ الدُّنْيَا دَارُ صِدْقٍ لِمَنْ صَدَقَهَا، وَدَارُ عَافِيَةٍ لِمَنْ فَهِمَ عَنْهَا، وَدَارُ غِنًى لِمَنْ تَزَوَّدَ مِنْهَا، وَدَارُ مَوْعِظَةٍ لِمَنِ اتَّعَظَ بِهَا. مَسْجِدُ أَحِبَّاءِ اللَّهِ، وَمُصَلَّى مَلَائِكَةِ اللَّهِ، وَمَهْبِطُ وَحْيِ اللَّهِ، وَمَتْجَرُ أَوْلِيَاءِ اللَّهِ. اكْتَسَبُوا فِيهَا الرَّحْمَةَ، وَرَبِحُوا فِيهَا الْجَنَّةَ. فَمَنْ ذَا يَذُمُّهَا وَقَدْ آذَنَتْ بِبَيْنِهَا، وَنَادَتْ بِفِرَاقِهَا، وَنَعَتْ نَفْسَهَا وَأَهْلَهَا؛ فَمَثَّلَتْ لَهُمْ بِبَلَائِهَا الْبَلَاءَ، وَشَوَّقَتْهُمْ بِسُرُورِهَا إِلَى السُّرُورِ؟","ob":"(En entendant un homme blâmer le monde, il dit) : O toi qui blâmes la vie terrestre, séduit que tu es par ses tromperies et abusé par ses vanités ! Te laisses-tu séduire par elle tout en la vilipendant ? ! Est-ce toi qui commets un crime contre elle ou bien c'est elle ? Quand t'a-t-elle attiré ou séduit ?... Le monde est une demeure de véracité pour celui qui est véridique, une demeure de bien-être pour celui qui le comprend, de richesse pour celui qui s'en approvisionne et de vie pour qui en tire des leçons. Elle est la mosquée des amis de Dieu, l'oratoire de Ses Anges, le lieu où descend Sa Révélation et le commerce de Ses amis qui y gagnent la miséricorde et le Paradis. Qui est donc celui qui vilipende cette vie terrestre qui apprend les gens à se séparer d'elle, qui annonce son anéantissement et la mort de ses enfants les hommes auxquels elle leur représente tout ce qui sert à les éprouver et en même temps tout ce qui leur procure le contentement?","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m132":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ لِلَّهِ مَلَكاً يُنَادِى فِى كُلِّ يَوْمٍ: لِدُوا لِلْمَوْتِ، وَاجْمَعُوا لِلْفَنَاءِ، وَابْنُوا لِلْخَرَابِ.","ob":"Un ange de Dieu déclame chaque jour: Enfantez pour la mort, accumulez pour l'anéantissement et construisez pour la ruine.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m133":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الدُّنْيَا دَارُ مَمَرٍّ لَا دَارُ مَقَرٍّ، وَالنَّاسُ فِيهَا رَجُلَانِ: رَجُلٌ بَاعَ فِيهَا نَفْسَهُ فَأَوْبَقَهَا، وَرَجُلٌ ابْتَاعَ نَفْسَهُ فَأَعْتَقَهَا.","ob":"La vie terrestre est une demeure de passage et non de séjour. Les hommes qui y vivent sont de deux types: celui qui y vend et perd son âme, et celui qui la rachète et la libère.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m134":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَكُونُ الصَّدِيقُ صَدِيقاً حَتَّى يَحْفَظَ أَخَاهُ فِى ثَلَاثٍ: فِى نَكْبَتِهِ، وَغَيْبَتِهِ، وَوَفَاتِهِ.","ob":"L'on ne peut être l'ami véritable d'un tiers que si on le sauvegarde dans l'adversité, l'absence et la mort.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m135":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مَنْ أُعْطِيَ أَرْبَعاً لَمْ يُحْرَمْ أَرْبَعاً: مَنْ أُعْطِيَ الدُّعَاءَ لَمْ يُحْرَمِ الْإِجَابَةَ، وَمَنْ أُعْطِيَ التَّوْبَةَ لَمْ يُحْرَمِ الْقَبُولَ، وَمَنْ أُعْطِيَ الِاسْتِغْفَارَ لَمْ يُحْرَمِ الْمَغْفِرَةَ، وَمَنْ أُعْطِيَ الشُّكْرَ لَمْ يُحْرَمِ الزِّيَادَةَ.","ob":"Celui à qui l'on donne quatre choses n'en sera privé: sera exaucé celui qui invoque Dieu, absous celui qui se repent, pardonné celui qui fait pénitence et comblé celui qui loue Dieu.","obNotes":[],"an":"Quatre choses données en attirent quatre autres: sera comblé celui qui loue Dieu; sera exaucé celui qui invoque, accueilli qui se repent, pardonné qui fait pénitence, comblé qui loue le Seigneur.","anIntro":"","anNotes":[],"diff":null}]},"m136":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الصَّلَاةُ قُرْبَانُ كُلِّ تَقِيٍّ، وَالْحَجُّ جِهَادُ كُلِّ ضَعِيفٍ. وَلِكُلِّ شَيْءٍ زَكَاةٌ، وَزَكَاةُ الْبَدَنِ الصِّيَامُ، وَجِهَادُ الْمَرْأَةِ حُسْنُ التَّبَعُّلِ.","ob":"La prière est l'offrande de tout homme pieux, et le pèlerinage est le <i>jihād</i> de tout homme faible. A toute chose correspond une <i>zakāt</i> [un don fait sur les revenus personnels pour les pauvres, les nécessiteux, le soulagement des débiteurs, la libération des esclaves, le bien-être des voyageurs etc]; celle du corps est le jeûne tandis que le <i>jihād</i> de la femme est l'obéissance du conjoint.","obNotes":[],"an":"L'Imām ajouta: «Pour tout fidèle, la prière est un moyen de se rapprocher de Dieu; le pèlerinage est le <i>jihād</i> du faible et en toute chose, il y a une zakat. Le jeûne est la zakat du corps; le <i>jihād</i> de la femme est dans l'aimable obéissance à son époux.»","anIntro":"","anNotes":[],"diff":null}]},"m137":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اسْتَنْزِلُوا الرِّزْقَ بِالصَّدَقَةِ.","ob":"Faites descendre les biens par l'aumône.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m138":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَيْقَنَ بِالْخَلَفِ جَادَ بِالْعَطِيَّةِ.","ob":"Celui qui croit en l'Au-delà prodigue les dons.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m139":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"تَنْزِلُ الْمَعُونَةُ عَلَى قَدْرِ الْمَئُونَةِ.","ob":"L'assistance est donnée à la mesure des provisions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m140":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا عَالَ مَنِ اقْتَصَدَ.","ob":"Ne s'appauvrit point celui qui économise.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m142":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"التَّوَدُّدُ نِصْفُ الْعَقْل.","ob":"Témoigner à quelqu'un de l'affection est déjà la moitié de l'intelligence.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m143":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْهَمُّ نِصْفُ الْهَرَم.","ob":"Le chagrin est la moitié de la vieillesse.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m144":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَنْزِلُ الصَّبْرُ عَلَى قَدْرِ الْمُصِيبَةِ، وَمَنْ ضَرَبَ يَدَهُ عَلَى فَخِذِهِ عِنْدَ مُصِيبَتِهِ حَبِطَ عمله.","ob":"La patience est donnée à la mesure du malheur. Celui qui dans le malheur tape sa jambe avec sa main n'aura pas de rémunération.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m145":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كَمْ مِنْ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ والظمأ، وَكَمْ مِنْ قَائِمٍ لَيْسَ لَهُ مِنْ قِيَامِهِ إِلَّا السَّهَرُ وَالْعَنَاءُ، حَبَّذَا نَوْمُ الْأَكْيَاسِ وَإِفْطَارُهُمْ.","ob":"Nombreux sont ceux qui jeûnent sans profit, encourant seulement la faim et la soif. Nombreux sont ceux qui prient sans rétribution, s'exposant uniquement à l'insomnie et à la peine. Le sommeil et la rupture du jeûne chez les sages sont bien meilleurs!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m146":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"سُوسُوا إِيمَانَكُمْ بِالصَّدَقَةِ، وَحَصِّنُوا أَمْوَالَكُمْ بِالزَّكَاةِ، وَادْفَعُوا أَمْواجَ الْبَلاَءِ بِالدُّعَاءِ.","ob":"Aménagez votre foi par l'aumône, protégez vos biens par la <i>zakāt</i> et repoussez les vagues des malheurs par la prière.","obNotes":[],"an":"Protégez votre foi par l'aumône, consolidez vos biens par la zakat et repoussez les vagues des malheurs par l'invocation de Dieu.","anIntro":"","anNotes":[],"diff":null}]},"m147":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَمِنْ كَلَامٍ لَهُ عليه السلام لِكُمَيْلِ بْنِ زِيَادٍ النَّخَعِيِّ: قَالَ كُمَيْلُ بْنُ زِيَادٍ: أَخَذَ بِيَدِي أَمِيرُ الْمُؤْمِنِينَ عَلِيُّ بْنُ أَبِي طَالِبٍ عليه السلام، فَأَخْرَجَنِي إِلَى الْجَبَّانِ، فَلَمَّا أَصْحَرَ تَنَفَّسَ الصُّعَدَاءَ، ثُمَّ قَالَ:","ob":"Extrait de ses paroles à Kumayl fils de Ziyād al-Nakha'ī: (Kumayl ibn Ziyād dit: le Prince des Croyants me tint par la main et m'emmena vers le cimetière. Lorsque nous arrivâmes au désert, il respira profondément et me dit):","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"يَا كُمَيْلَ بْنَ زِيَادٍ، إِنَّ هذهِ الْقُلُوبَ أَوْعِيَةٌ، فَخَيْرُهَا أَوْعَاهَا، فَاحْفَظْ مَا أَقُولُ لَكَ:","ob":"O Kumayl fils de Ziyād, ces cœurs sont des récipients dont les meilleurs sont ceux qui retiennent le plus. Retiens ce que je vais te dire:","obNotes":[],"an":"«O Kumayl Ibn Ziyād! Ces cœurs sont des réceptacles, et les meilleurs d'entre eux sont les plus rétenteurs; retiens donc ce que je vais te dire:","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[3],"ar":"النَّاسُ ثَلاَثَةٌ: فَعَالِمٌ رَبَّانِيٌّ، وَمُتَعَلِّمٌ عَلَى سَبِيلِ نَجَاةٍ، وَهَمَجٌ رَعَاعٌ أَتْبَاعُ كُلِّ نَاعِقٍ، يَمِيلُونَ مَعَ كُلِّ رِيحٍ، لَمْ يَسْتَضِيئُوا بِنُورِ الْعِلْمِ، وَلَمْ يَلْجَؤُوا إِلَى رُكْنٍ وَثِيقٍ.","ob":"Il existe trois types d'hommes: un savant qui croit en Dieu, un autre qui vise à être sauvé et une masse d'ignorants qui suivent tout menteur, se plient au gré des vents, ne s'éclairent pas à la lumière de la science et ne se réfugient pas auprès d'un chef qui les appuie sûrement.","obNotes":[],"an":"Les hommes sont de trois genres, un savant inspiré de Dieu, un autre qui apprend pour pouvoir être sauvé et une masse qui ignore et suit quiconque lui souffle dans une trompette; elle plie au gré des vents, elle ne s'éclaire pas à la lumière de la science. Elle ne se réfugie pas auprès de quelque chose de sûr.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[4],"ar":"يَا كُمَيْلُ، الْعِلْمُ خَيْرٌ مِنَ الْمَالِ، الْعِلْمُ يَحْرُسُكَ وَأَنْتَ تَحْرُسُ المَالَ. وَالْمَالُ تَنْقُصُهُ النَّفَقَةُ، وَالْعِلْمُ يَزْكُو عَلَى الْإِنْفَاقِ، وَصَنِيعُ الْمَالِ يَزُولُ بِزَوَالِهِ.","ob":"O Kumayl! La science est meilleure que les biens, car elle est ton gardien et toi à ton tour tu gardes ces biens. Ceux-ci diminuent quand tu les consommes, mais la science augmente quand on s'en sert. De plus, lorsque tes biens s'évanouissent, ceux qui s'en profitaient s'éloignent de toi.","obNotes":[],"an":"O Kumayl!.. La science est préférable à la richesse. La science est ton fidèle gardien; or, la richesse exige que tu sois son gardien. Le savoir augmente quand on s'en sert, alors que l'argent diminue quand on l'utilise. Les bienfaits de la richesse s'évanouissent dès qu'on perd sa fortune.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[5],"ar":"يَا كُمَيْلَ بْنَ زِيَادٍ، مَعْرِفَةُ الْعِلْمِ دِينٌ يُدَانُ بِهِ، بِهِ يَكْسِبُ الْإِنْسَانُ الطَّاعَةَ فِى حَيَاتِهِ، وَجَمِيلَ الْأُحْدُوثَةِ بَعْدَ وَفَاتِهِ، وَالْعِلْمُ حَاكِمٌ، وَالْمَالُ مَحْكُومٌ عَلَيْهِ.","ob":"O Kumayl! La connaissance est une religion à suivre, par laquelle l'homme gagne l'obéissance dans sa vie et laisse un bon souvenir après sa mort. Le savoir dirige tandis que les biens sont régis.","obNotes":[],"an":"O Kumayl! La connaissance est une religion que l'on pratique. Par le savoir, on obtient l'obéissance dans la vie et on laisse un bon souvenir après la mort. La science dirige alors que l'argent est dirigé.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[6,7],"ar":"يَا كُمَيْلُ، هَلَكَ خُزَّانُ الْأَمْوَالِ وَهُمْ أَحْيَاءٌ، وَالْعُلَمَاءُ بَاقُونَ مَا بَقِيَ الدَّهْرُ: أَعْيَانُهُمْ مَفْقُودَةٌ وَأَمْثَالُهُمْ فِى الْقُلُوبِ مَوْجُودَةٌ. هَا إِنَّ هَا هُنَا لَعِلْماً جَمّاً (وَأَشَارَ بِيَدِهِ إِلَى صَدْرِهِ) لَوْ أَصَبْتُ لَهُ حَمَلَةً! بَلَى أَصَبْتُ لَقِناً غَيْرَ مَأْمُونٍ عَلَيْهِ، مُسْتَعْمِلًا آلَةَ الدِّينِ لِلدُّنْيَا، وَمُسْتَظْهِراً بِنِعَمِ اللَّهِ عَلَى عِبَادِهِ، وَبِحُجَجِهِ عَلَى أَوْلِيَائِهِ؛ أَوْ مُنْقَاداً لِحَمَلَةِ الْحَقِّ، لَا بَصِيرَةَ لَهُ فِى أَحْنَائِهِ، يَنْقَدِحُ الشَّكُّ فِى قَلْبِهِ لِأَوَّلِ عَارِضٍ مِنْ شُبْهَةٍ.","ob":"O Kumayl! Les thésauriseurs périssent tout en étant vivants alors que les savants dureront aussi longtemps que durera le monde, sinon par leurs corps du moins par leur exemple qui reste dans les cœurs. Il y a ici (et il désigne du doigt sa poitrine) une science immense que j'aimerais -hélas! - trouver ceux qui la porteront!\nOui, je n'ai trouvé que ceux qui veulent la connaître sans être dignes de la porter. Ceux-ci exploitent la religion pour les affaires du monde, demandant assistance aux grâces de Dieu contre Ses adorateurs, et à Ses preuves contre Ses amis. Je n'ai trouvé aussi que ceux qui se laissent diriger par ceux qui détiennent la vérité, mais qui sont exempts de perspicacité et enclins au scepticisme à la première ambiguïté.","obNotes":[],"an":"O Kumayl! Les thésauriseurs sont des cadavres vivants alors que les savants se maintiennent aussi longtemps que durera le monde. Leurs corps peuvent disparaître mais leurs exemples restent dans les cœurs.\nIl y a là une science immense (et il désigna du doigt sa poitrine). Ah, si j'avais trouvé celui qui la porterait! Oui, je n'ai trouvé que ceux qui veulent la connaître sans être dignes de la porter. Ils utilisent l'outil de la religion pour les affaires de ce monde. Ou d'autres qui exploitent les bienfaits accordés par le Seigneur à ses serviteurs et les preuves qu'Il a données aux fidèles, ou qui suivent ceux qui détiennent la vérité, mais sans aucune perspicacité, le doute s'emparant de leurs cœurs à la première ambiguité.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[8],"ar":"أَلَا لَا ذَا وَلَا ذَاكَ! أَوْ مَنْهُوماً بِاللَّذَّةِ، سَلِسَ الْقِيَادِ لِلشَّهْوَةِ، أَوْ مُغْرَماً بِالْجَمْعِ وَالِادِّخَارِ، لَيْسَا مِنْ رُعَاةِ الدِّينِ فِى شَيْءٍ، أَقْرَبُ شَيْءٍ شَبَهاً بِهِمَا الْأَنْعَامُ السَّائِمَةُ! كَذَلِكَ يَمُوتُ الْعِلْمُ بِمَوْتِ حَامِلِيهِ.","ob":"Les uns et les autres me dégoutent! De même que ceux qui sont assoiffés de plaisirs, qui se laissent conduire par les passions; ou ceux qui ne désirent qu'amasser les biens et les thésauriser; ceux-ci et ceux-là ne sont point les gardiens de la religion. Tout au plus ils sont comparables aux animaux qui broutent l'herbe! C'est ainsi que la science meurt par la mort de celui qui la porte.","obNotes":[],"an":"Fi de celui-ci, et de celui-là! Il y en a même d'autres assoiffés de plaisirs, se laissant aller à la jouissance ou bien ne désirant qu'amasser et conserver les richesses; ces derniers ne sont point les gardiens de la religion. Tout au plus l'on pourrait les comparer aux broutards. Ainsi meurt une science par la mort de celui qui la porte.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[9],"ar":"اللَّهُمَّ بَلَى! لَا تَخْلُو الْأَرْضُ مِنْ قَائِمٍ لله بِحُجَّةٍ، إِمَّا ظَاهِراً مَشْهُوراً، وَإِمَّا خَائِفاً مَغْمُوراً، لِئَلاَّ تَبْطُلَ حُجَجُ اللّٰهِ وَبَيِّنَاتُهُ. وَكَمْ ذَا وَأَيْنَ أُولئِكَ؟ أُولئِكَ -وَاللَّهِ- الْأَقَلُّونَ عَدَداً، وَالْأَعْظَمُونَ عِنْدَ اللَّهِ قَدْراً. يَحْفَظُ اللّٰهُ بِهِمْ حُجَجَهُ وَبَيِّنَاتِهِ، حَتَّى يُودِعُوهَا نُظَرَاءَهُمْ، وَيَزْرَعُوهَا فِي قُلُوبِ أَشْبَاهِهِمْ.","ob":"Cependant -par Dieu! - la terre contient des hommes qui défendent la cause de Dieu, les uns connus publiquement, les autres peureux et inconnus, afin que ne disparaissent pas les preuves et les signes de Dieu. Combien et où sont-ils? Ils sont, par Dieu, les moins nombreux mais les plus en vue chez Dieu qui, grâce à eux, conserve ses arguments pour qu'ils les transmettent à d'autres et les sèment dans le cœur de leurs semblables.","obNotes":[],"an":"Par Dieu Oui! La terre ne sera pas privée d'hommes défendant la cause de Dieu publiquement et solennellement, ou bien fébrilement et secrètement afin que ne disparaissent pas les preuves et manifestations de Dieu! Combien sont-ils ceux-là et où sont-ils ceux-ci? Ils sont, certes, d'un nombre restreint mais grande sera leur valeur auprès de Dieu. Par eux, il manifeste ses preuves et arguments jusqu'à ce qu'ils les confient à leurs égaux et les sèment dans le cœur de leurs semblables.","anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[10],"ar":"هَجَمَ بِهِمُ الْعِلْمُ عَلَى حَقِيقَةِ الْبَصِيرَةِ، وَبَاشَرُوا رُوحَ الْيَقِينِ، وَاسْتَلاَنُوا مَا اسْتَعْوَرَهُ الْمُتْرَفُونَ، وَأَنِسُوا بِمَا اسْتَوْحَشَ مِنْهُ الْجَاهِلُونَ، وَصَحِبُوا الدُّنْيَا بِأَبْدَانٍ أَرْوَاحُهَا مُعَلَّقَةٌ بِالْمَحَلِّ الْأَعْلَى. أُولئِكَ خُلَفَاءُ اللّٰهِ فِي أَرْضِهِ، وَالدُّعَاةُ إِلَى دِينِهِ. آهِ آهِ شَوْقاً إِلَى رُؤْيَتِهِمْ! انْصَرِفْ يَا كُمَيْلُ إِذَا شِئْتَ.","ob":"La science les a poussés à plus de perspicacité, ils ont œuvré dans un esprit de certitude, ont trouvé aisée la voie qui paraissait difficile à ceux qui vivent dans la mollesse, se sont habitués à ce que les ignorants trouvent morose, et ont vécu dans le monde par des corps dont les cœurs sont attachés à la demeure supérieure. Ceux-ci sont les excellents fils de Dieu sur Sa terre et les propagateurs de Sa religion. Ah! Ah! Comme je brûle de les voir! O Kumayl, tu peux disposer si tu veux.","obNotes":[],"an":"La science les a poussés à plus de perspicacité, ils ont acquis la certitude, ont trouvé facile la voie qui paraissait dure aux jouisseurs et se sont agréablement accoutumés à ce que les ignorants jugeaient déplaisant. Ils ont traversé cette vie, leurs cœurs attachés aux sphères divines. Ils sont les vicaires de Dieu sur la terre et les propagateurs de sa religion. Ah! Comme je brûle de les voir! [Puis l'Imām dit:] «Et maintenant, tu peux disposer, Kumayl.»","anIntro":"","anNotes":[],"diff":null}]},"m148":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْمَرْءُ مَخْبُوءٌ تَحْتَ لِسَانِهِ.","ob":"L'homme est caché sous sa langue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m149":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"هَلَكَ امْرُؤٌ لَمْ يَعْرِفْ قَدْرَهُ.","ob":"Périt l'homme qui ne connaît point sa valeur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m150":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَكُنْ مِمَّنْ يَرْجُو الْآخِرَةَ بِغَيْرِ العمل، وَيُرَجِّي التَّوْبَةَ بِطُولِ الْأَمَلِ، يَقُولُ فِي الدُّنْيَا بِقَوْلِ الزَّاهِدِينَ، وَيَعْمَلُ فِيهَا بِعَمَلِ الرَّاغِبِينَ، إِنْ أُعْطِيَ مِنْهَا لَمْ يَشْبَعْ، وَإِنْ مُنِعَ مِنْهَا لَمْ يَقْنَعْ؛ يَعْجِزُ عَنْ شُكْرِ مَا أُوتِيَ، وَيَبْتَغِي الزِّيَادَةَ فِيمَا بَقِيَ.","ob":"(Il dit à un homme qui lui demanda de le conseiller): Ne sois pas comme celui qui espère la vie future sans agir et retarde le repentir dans l'espoir d'une longue vie. Dans le monde il parle le langage des ascètes, mais y travaille comme ceux qui désirent la vie terrestre, ne se rassasient pas de ses biens et, s'ils en sont privés, ne se contentent pas de ce qui leur est donné. Un tel homme est incapable de remercier pour ce qu'il a reçu et désirerait encore jouir davantage de ce qui reste.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"يَنْهَى وَلَا يَنْتَهِي، وَيَأْمُرُ بِمَا لَا يَأْتِي؛ يُحِبُّ الصَّالِحِينَ وَلَا يَعْمَلُ عَمَلَهُمْ، وَيُبْغِضُ الْمُذْنِبِينَ وَهُوَ أَحَدُهُمْ؛ يَكْرَهُ الْمَوْتَ لِكَثْرَةِ ذُنُوبِهِ، وَيُقِيمُ عَلَى مَا يَكْرَهُ الْمَوْتَ مِنْ أَجْلِهِ، إِنْ سَقِمَ ظَلَّ نَادِماً، وَإِنْ صَحَّ أَمِنَ لَاهِياً؛ يُعْجَبُ بِنَفْسِهِ إِذَا عُوفِيَ، وَيَقْنَطُ إِذَا ابْتُلِيَ.","ob":"Il défend de faire ce que lui-même fait et ordonne de faire ce qu'il ne fait point lui-même. Il aime les gens de bien mais ne les imite pas dans leurs actions ; hait les pécheurs alors qu'il en fait partie. Il abhorre la mort à cause de ses péchés nombreux et se complaît dans ce qui lui fait haïr la mort. S'il tombe malade, il regrette de ne pas avoir ménagé sa santé, mais s'il se porte bien il se sent bien en sûreté. S'il guérit il devient infatué de lui-même, mais s'il est éprouvé il désespère.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[3],"ar":"إِنْ أَصَابَهُ بَلَاءٌ دَعَا مُضْطَرّاً، وَإِنْ نَالَهُ رَخَاءٌ أَعْرَضَ مُغْتَرّاً، تَغْلِبُهُ نَفْسُهُ عَلَى مَا يَظُنُّ، وَلَا يَغْلِبُهَا عَلَى مَا يَسْتَيْقِنُ.","ob":"Quand il est frappé par un malheur il invoque Dieu bon gré mal gré, mais quand il se trouve dans un état de bien-être il devient inattentif envers Dieu. Il est certain que le bonheur réside dans l'ascèse et la vertu, mais il ne s'efforce pas de les pratiquer.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[4],"ar":"يَخَافُ عَلَى غَيْرِهِ بِأَدْنَى مِنْ ذَنْبِهِ، وَيَرْجُو لِنَفْسِهِ بِأَكْثَرَ مِنْ عَمَلِهِ؛ إِنِ اسْتَغْنَى بَطِرَ وَفُتِنَ، وَإِنِ افْتَقَرَ قَنِطَ وَوَهَنَ؛ يُقَصِّرُ إِذَا عَمِلَ، وَيُبَالِغُ إِذَا سَأَلَ؛ إِنْ عَرَضَتْ لَهُ شَهْوَةٌ أَسْلَفَ الْمَعْصِيَةَ، وَسَوَّفَ التَّوْبَةَ، وَإِنْ عَرَتْهُ مِحْنَةٌ انْفَرَجَ عَنْ شَرَائِطِ الْمِلَّةِ.","ob":"Il se plaint chez les autres des fautes moindres que les siennes, et espère une situation supérieure à celle que méritent ses actions. S'il s'enrichit il devient pétulant et séduit, et s'il s'appauvrit il désespère et s'affaiblit. Son travail laisse à désirer. Lorsqu'il sollicite, il exagère. Il succombe devant les passions et renvoie le repentir du jour au lendemain. Il renonce à la patience et à la persévérance s'il lui arrive un malheur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[5],"ar":"يَصِفُ الْعِبْرَةَ وَلَا يَعْتَبِرُ، وَيُبَالِغُ فِى الْمَوْعِظَةِ وَلَا يَتَّعِظُ؛ فَهُوَ بِالْقَوْلِ مُدِلٌّ، وَمِنَ الْعَمَلِ مُقِلٌّ، يُنَافِسُ فِيمَا يَفْنَى، وَيُسَامِحُ فِيمَا يَبْقَى. يَرَى الْغُنْمَ مَغْرَماً وَالْغُرْمَ مَغْنَماً؛ يَخْشَى الْمَوْتَ، وَلَا يُبَادِرُ الْفَوْتَ.","ob":"Il décrit les événements qui servent d'avertissement mais n'en prend pas leçon, exagère en sermonnant mais n'en a cure. Il s'élève très haut en paroles mais il est parcimonieux en actions. Il rivalise avec ses semblables pour ce qui est éphémère mais les traite avec indulgence en ce qui concerne les valeurs éternelles... Il a peur de la mort et ne profite pas de l'occasion pour s'y préparer.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[6],"ar":"يَسْتَعْظِمُ مِنْ مَعْصِيَةِ غَيْرِهِ مَا يَسْتَقِلُّ أَكْثَرَ مِنْهُ مِنْ نَفْسِهِ، وَيَسْتَكْثِرُ مِنْ طَاعَتِهِ مَا يَحْقِرُهُ مِنْ طَاعَةِ غَيْرِهِ، فَهُوَ عَلَى النَّاسِ طَاعِنٌ، وَلِنَفْسِهِ مُدَاهِنٌ؛ اللَّهْوُ مَعَ الْأَغْنِيَاءِ أَحَبُّ إِلَيْهِ مِنَ الذِّكْرِ مَعَ الْفُقَرَاءِ، يَحْكُمُ عَلَى غَيْرِهِ لِنَفْسِهِ، وَلَا يَحْكُمُ عَلَيْهَا لِغَيْرِهِ.","ob":"Il s'étonne de la grandeur des péchés d'autrui, mais minimise ses défauts plus grands encore. Il considère que son obéissance est beaucoup plus grande que celle méprisable des autres. Il diffame les autres et dissimule ses propres actions. Les amusements avec les riches prévalent chez lui plus que le rappel de Dieu avec les pauvres. Il juge mal les autres et tourne ce qui le concerne à son propre avantage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[7],"ar":"يُرْشِدُ غَيْرَهُ وَيُغْوِى نَفْسَهُ، فَهُوَ يُطَاعُ وَيَعْصِى، وَيَسْتَوْفِى وَلَا يُوفِى، وَيَخْشَى الْخَلْقَ فِى غَيْرِ رَبِّهِ وَلَا يَخْشَى رَبَّهُ فِى خَلْقِهِ.","ob":"Il dirige les autres et se trompe lui-même. Il est obéi mais il est désobéissant à Dieu; il prend ses droits mais ne donne point aux autres leur dû. Il craint les créatures pour des raisons qui n'ont rien à voir avec Dieu, mais il ne craint pas Dieu dans son comportement envers les créatures.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m151":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِكُلِّ امْرِئٍ عَاقِبَةٌ حُلْوَةٌ أَوْ مُرَّةٌ.","ob":"A chaque âme une fin heureuse ou malheureuse.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m152":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِكُلِّ مُقْبِلٍ إِدْبَارٌ، وَمَا أَدْبَرَ كَأَنْ لَمْ يَكُنْ.","ob":"A toute prospérité un revirement, comme si elle n'avait pas existé.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m153":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَعْدَمُ الصَّبُورُ الظَّفَرَ وَإِنْ أطال بِهِ الزَّمَانُ.","ob":"Celui qui patiente vaincra tôt ou tard.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m154":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الرَّاضِي بِفِعْلِ قَوْمٍ كَالدَّاخِلِ فِيهِ مَعَهُمْ. وَعَلَى كُلِّ دَاخِلٍ فِي بَاطِلٍ إِثْمَانِ: إِثْمُ الْعَمَلِ بِهِ، وَإِثْمُ الرِّضَى بِهِ.","ob":"Quiconque accepte les actions des gens devient leur collaborateur. Et quiconque participe à une mauvaise action commet deux péchés: celui de l'action et celui du consentement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m155":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اعْتَصِمُوا بِالذِّمَمِ فِي أَوْتَادِهَا.","ob":"Retranchez-vous derrière les pactes conclus avec les hommes magnanimes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m157":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قَدْ بُصّرْتُمْ إِنْ أَبْصَرْتُمْ، وَقَدْ هُدِيتُمْ إِنِ اهْتَدَيْتُمْ، وأُسْمِعْتُمْ إِنِ اسْتَمَعْتُمْ.","ob":"Qu'ils voient ceux qui ont la vue, qu'ils se dirigent bien par le Coran et qu'ils entendent ses paroles.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m158":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"عَاتِبْ أَخَاكَ بِالْإِحْسَانِ إِلَيْهِ، وَارْدُدْ شَرَّهُ بِالْإِنْعَامِ عَلَيْهِ.","ob":"Fais des reproches à ton frère en lui faisant du bien, et garde-toi de sa méchanceté en lui accordant une faveur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m159":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ وَضَعَ نَفْسَهُ مَوَاضِعَ التُّهَمَةِ فَلاَ يَلُومَنَّ مَنْ أَسَاءَ بِهِ الظَّنَّ.","ob":"Celui qui se met dans un état blâmable ne doit pas s'en vouloir à qui en pense mal.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m160":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ مَلَكَ اسْتَأْثَرَ.","ob":"Quiconque règne revendique le plein pouvoir.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m161":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنِ اسْتَبَدَّ بِرَأْيِهِ هَلَكَ، وَمَنْ شَاوَرَ الرِّجَالَ شَارَكَهَا فِي عُقُولِهَا.","ob":"Celui qui suit obstinément son opinion périt et celui qui demande conseil aux hommes copartage leurs idées.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m162":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ كَتَمَ سِرَّهُ كَانَتِ الْخِيرَةُ بِيَدِهِ.","ob":"Quiconque cache son secret tient le choix entre ses mains.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m163":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْفَقْرُ الْمَوْتُ الْأَكْبَرُ.","ob":"La pauvreté est la mort la plus grande.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m164":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ قَضَى حَقَّ مَنْ لَا يَقْضِي حَقَّهُ فَقَدْ عَبَدَهُ.","ob":"Celui qui donne son dû à quelqu'un qui ne le lui rend pas au retour devient son serviteur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m165":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"«لَا طَاعَةَ لِمخْلُوقٍ فِي مَعْصِيَةِ الْخَالِقِ».","ob":"«On ne doit pas obéir à une créature tout en désobéissant au Créateur».","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m166":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يُعَابُ الْمَرْءُ بِتَأْخِيرِ حَقِّهِ، إِنَّمَا يُعَابُ مَنْ أَخَذَ مَا لَيْسَ لَهُ.","ob":"On ne peut pas accuser quelqu'un d'avoir tardé à récupérer son droit, mais on accuse celui qui détient ce qui ne lui appartient pas.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m167":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْإِعْجَابُ يَمْنَعُ الِازْدِيَادَ.","ob":"La fatuité empêche l'autoperfectionnement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m169":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قَدْ أَضَاءَ الصُّبْحُ لِذِي عَيْنَيْنِ.","ob":"L'aube éclaire celui qui a des yeux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m170":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"تَرْكُ الذَّنْبِ أَهْوَنُ مِنْ طَلَبِ المعونة.","ob":"Se repentir d'une faute est plus facile que demander de l'aide.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m172":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"النَّاسُ أَعْدَاءُ مَا جَهِلُوا.","ob":"Les gens sont les ennemis de ce qu'ils ignorent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m173":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنِ اسْتَقْبَلَ وُجُوهَ الْآرَاءِ عَرَفَ مَوَاقِعَ الْخَطَاَ.","ob":"Celui qui étudie les opinions des autres connaît les tenants et aboutissants d'une affaire.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m174":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَن أَحَدَّ سِنَانَ الْغَضَبِ للّه قَوِيَ عَلَى قَتْلِ أَشِدَّاءِ الْبَاطِلِ.","ob":"Celui qui aiguise la lame de la lance de Dieu devient capable de tuer les ennemis de l'injustice.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m175":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا هِبْتَ أَمْرأً فَقَعْ فِيهِ، فَإِنَّ شِدَّةَ تَوَقِّيهِ أَعْظَمُ مِمَّا تَخَافُ مِنْهُ.","ob":"Si une affaire te paraît redoutable mets-la en œuvre, car s'en prémunir fortement est beaucoup plus difficile.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m177":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"ازْجُرِ الْمُسِيءَ بِثَوَابِ الْمُحْسِنِ.","ob":"Réprimandez celui qui fait mal en récompensant celui qui fait le bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m178":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"احْصُدِ الشَّرَّ مِنْ صَدْرِ غَيْرِكَ بِقَلْعِهِ مِنْ صَدْرِكَ.","ob":"Coupe le mal de la poitrine d'autrui en l'extirpant de la tienne.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m179":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اللَّجَاجَةُ تَسُلُّ الرَّأْيَ.","ob":"L'insistance déforme le discernement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m180":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الطَّمَعُ رِقٌّ مُؤَبَّدٌ.","ob":"L'avidité est un esclavage à perpétuité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m181":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"ثَمَرَةُ التَّفْرِيطِ النَّدَامَةُ، وَثَمَرَةُ الْحَزْمِ السَّلاَمَةُ.","ob":"Le regret est le fruit de la prodigalité, et la sécurité est le fruit de la fermeté.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m182":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا خَيْرَ فِي الصَّمْتِ عَنِ الْحُكْمِ، كَمَا أَنَّهُ لَا خَيْرَ فِي الْقوْلِ بِالْجَهْلِ.","ob":"Il n'est pas bien que tu te taises lorsqu'il faut que tu émettes un jugement, et que tu parles lorsque tu ignores ce dont il s'agit.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m183":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا اخْتَلَفَتْ دَعْوَتَانِ إِلَّا كَانَتْ إِحْدَاهُمَا ضَلاَلَةً.","ob":"Deux prédications contradictoires impliquent l'erreur de l'une d'elles.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m184":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا شَكَكْتُ فِي الْحَقِّ مُذْ أُرِيتُهُ.","ob":"Je n'ai jamais douté de la justice dès qu'elle m'est apparue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m185":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا كَذَبْتُ وَلَا كُذِّبْتُ، وَلَا ضَلَلْتُ وَلَا ضُلَّ بِي.","ob":"Je n'ai ni menti, ni suis démenti; je n'ai ni erré, ni été induit en erreur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m186":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِلظَّالِمِ الْبَادِي غَداً بِكَفِّهِ عَضَّةٌ.","ob":"L'injuste mord sa main de regret le Jour du Jugement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m187":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الرَّحيل وشيك.","ob":"Le départ pour l'autre monde est très proche.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m188":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَبْدى صَفْحَتَهُ لِلْحَقِّ هَلَكَ.","ob":"Périt celui qui combat publiquement la justice.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m189":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ لَمْ يُنْجِهِ الصَّبْرُ أَهْلَكَهُ الْجَزَعُ.","ob":"Celui qui n'est pas sauvé par la patience périra par l'émotion violente d'impatience.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m190":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَاعَجَبَاهُ! أَتَكُونُ الْخِلاَفَةُ بِالصَّحَابَةِ وَالْقَرَابَةِ؟","ob":"O mon grand étonnement! Le califat est-il l'apanage strict des compagnons et des parents [du Prophète]?","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m191":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّمَا الْمَرْءُ فِى الدُّنْيَا غَرَضٌ تَنْتَضِلُ فِيهِ الْمَنَايَا، وَنَهْبٌ تُبَادِرُهُ الْمَصَائِبُ؛ وَمَعَ كُلِّ جُرْعَةٍ شَرَقٌ. وَفِى كُلِّ أَكْلَةٍ غَصَصٌ. وَلَا يَنَالُ الْعَبْدُ نِعْمَةً إِلَّا بِفِرَاقِ أُخْرَى، وَلَا يَسْتَقْبِلُ يَوْماً مِنْ عُمُرِهِ إِلَّا بِفِرَاقِ آخَرَ مِنْ أَجَلِهِ. فَنَحْنُ أَعْوَانُ الْمَنُونِ، وَأَنْفُسُنَا نَصْبُ الْحُتُوفِ؛ فَمِنْ أَيْنَ نَرْجُو الْبَقَاءَ وَهَذَا اللَّيْلُ وَالنَّهَارُ لَمْ يَرْفَعَا مِنْ شيء شَرَفاً، إِلَّا أَسْرَعَا الْكَرَّةَ فِى هَدْمِ مَا بَنَيَا، وتفريق مَا جَمَعَا؟!","ob":"L'homme est une cible visée par la mort et une proie rapinée par les malheurs. A chacun de ses plaisirs s'associe une douleur et à chaque gorgée correspond une suffocation. Le serviteur ne reçoit un bien qu'en se séparant d'un autre. Il ne vit un jour de son âge qu'en éliminant un jour de son espérance de vie. Nous sommes les collaborateurs de la mort. Nos âmes envisagent la perdition. D'où espérons-nous une longue vie si le jour et la nuit ne laissent ériger un monument que pour le détruire aussitôt?!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m192":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"يابْن آدَمَ مَا كَسَبْتَ فَوْقَ قُوتِكَ، فَأَنْتَ فِيهِ خَازِنٌ لِغَيْرِكَ.","ob":"O fils d'Adam! Ce que tu gagnes au-dessus de ta nourriture tu l'emmagasines pour d'autres.","obNotes":[],"an":"O Descendants d'Adam! Tout ce que vous amassez au-delà de vos besoins, vous le thésaurisez pour les autres. Les cœurs ont leurs moments de désir, d'affabilité et d'hostilité. Abordez-les lorsqu'ils sont en état de désir et d'affabilité, car un cœur en proie à la haine est incapable de discernement.","anIntro":"","anNotes":[],"diff":null}]},"m194":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَتَى أَشْفِي غَيْظِي إِذَا غَضِبْتُ؟ أَحِينَ أَعْجِزُ عَنِ الِانْتِقَامِ فَيُقَالُ لِي: لَوْ صَبَرْتَ؟ أَمْ حِينَ أَقْدِرُ عَلَيْهِ فَيُقَالُ لي: لَوْ عَفَوْتَ؟","ob":"Quand apaiserai-je mon accès de colère? Lorsque je suis incapable de me venger et qu'on me dit: si tu avais patienté? Ou bien lorsque je suis capable et qu'on me dit: Ah! Si tu avais pardonné?","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m196":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَمْ يَذْهَبْ مِنْ مَالِكَ مَا وَعَظَكَ.","ob":"Ton argent qui t'a exhorté à faire le bien n'est point perdu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m197":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِنَّ هذِهِ الْقُلُوبَ تَمَلُّ كَمَا تَمَلُّ الْأَبْدَانُ، فَابْتَغُوا لَهَا طَرَائِفَ الْحِكْمَةِ.","ob":"Ces cœurs s'ennuient certes tout comme les corps, demandez-leur donc des nouveautés sapientielles.","obNotes":[],"an":"Les cœurs sont aussi sujets à l'ennui que les corps, divertissez-les avec les belles pensées.","anIntro":"","anNotes":[],"diff":null}]},"m198":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لَمَّا سَمِعَ قَوْلَ الْخَوَارِجِ: «لَا حُكْمَ إِلَّا لِلهِ»: كَلِمَةُ حَقٍّ يُرَادُ بِهَا بَاطِلٌ.","ob":"(Lorsqu'il entendit ce que les Khawārij ont dit: «Il n'y a de gouvernement que celui de Dieu», il rétorque): C'est une parole de vérité, qui sous-tend du mensonge.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m201":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ مَعَ كُلِّ إِنْسَانٍ مَلَكَيْنِ يَحْفَظَانِهِ، فَإِذَا جَاءَ الْقَدَرُ خَلَّيَا بَيْنَهُ وَبَيْنَهُ، وَإِنَّ الْأَجَلَ جُنَّةٌ حَصِينَةٌ.","ob":"Chaque homme a deux anges qui le gardent. Lorsque vint le terme de la vie ils le quittent. L'homme est bien protégé durant son âge prédéterminé par Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m202":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام، وَقَدْ قَالَ لَهُ طَلْحَةُ وَالزُّبَيْرُ: نُبَايِعُكَ عَلَى أَنَّا شُرَكَاؤُكَ فِي هَذَا الْأَمْرِ: لَا، وَلكِنَّكُمَا شَرِيكَانِ فِي الْقُوَّةِ وَالِاسْتِعَانَةِ، وَعَوْنَانِ عَلَى الْعَجْزِ وَالْأَوَدِ.","ob":"(En réponse à Ṭalḥa et al-Zubayr qui lui dirent: nous reconnaîtrons ton califat à condition d'y être associés, il dit): Non, mais vous êtes des associés dans la force et l'imploration du secours, et des assistants lorsque je deviens impuissant avec l'âge.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m203":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَيُّهَا النَّاسُ، اتّقُوا اللّٰهَ الَّذِي إِنْ قُلْتُمْ سَمِعَ، وَإِنْ أَضْمَرْتُمْ عَلِمَ، وَبَادِرُوا الْمَوْتَ الَّذِي إِنْ هَرَبْتُمْ مِنْهُ أَدْرَكَكُمْ، وَإِنْ أَقَمْتُمْ أَخَذَكُمْ، وَإِنْ نَسِيتُمُوهُ ذَكَرَكُمْ.","ob":"O gens, craignez Dieu qui entend vos paroles et connaît vos intentions. Accourez vers la mort qui vous suit si vous le fuyez, vous prend si vous vous arrêtez et se rappelle de vous si vous l'oubliez.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m204":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يُزَهِّدَنَّكَ فِي الْمَعْرُوفِ مَنْ لَا يَشْكُرُهُ لَكَ، فَقَدْ يَشْكُرُكَ عَلَيْهِ مَنْ لَا يَسْتَمْتِعُ بِشَيْءٍ مِنْهُ، وَقَدْ تُدْرِكُ مِنْ شُكْرِ الشَّاكِرِ أَكْثَرَ مِمَّا أَضَاعَ الْكَافِرُ، «وَاللهُ يُحِبُّ الْمُحْسِنِينَ».","ob":"Celui qui ne te remercie pas pour le convenable que tu fais ne le laisse pas t'amener à y renoncer. Il se peut que celui qui n'aime pas ce qui est convenable te remercie pour l'avoir fait. Il se peut aussi que tu tires de ce remerciement un profit bien meilleur que l'attitude négative du premier, «Dieu aime ceux qui font le bien».","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m205":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُلُّ وِعَاءٍ يَضِيقُ بِمَا جُعِلَ فِيهِ إِلَّا وِعَاءَ الْعِلْمِ، فَإِنَّهُ يَتَّسِعُ بِهِ.","ob":"Tout réceptacle a une capacité spécifique, sauf la science qui peut englober toute chose.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m206":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَوَّلُ عِوَضِ الْحَلِيمِ مِنْ حِلْمِهِ أَنَّ النَّاسَ أَنْصَارُهُ عَلَى الْجَاهِلِ.","ob":"Le premier profit de l'homme clément est que les hommes l'aident contre l'ignorant.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m207":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنْ لَمْ تَكُنْ حَلِيماً فَتَحَلَّمْ، فَإِنَّهُ قَلَّ مَنْ تَشَبَّهَ بِقَوْمٍ إِلَّا أَوْشَكَ أَنْ يَكُونَ مِنْهُمْ.","ob":"Sois clément si tu ne l'es pas, car celui qui ressemble aux gens de clémence faillit être l'un d'eux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m208":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ حَاسَبَ نَفْسَهُ رَبِحَ، وَمَنْ غَفَلَ عَنْهَا خَسِرَ، وَمَنْ خَافَ أَمِنَ، وَمَنِ اعْتَبَرَ أَبْصَرَ، وَمَنْ أَبْصَرَ فَهِمَ، وَمَنْ فَهِمَ عَلِمَ.","ob":"Celui qui demande compte à lui-même gagne; celui qui a peur est en sécurité; celui qui tire des leçons voit, celui qui voit comprend et celui qui comprend connaît.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m209":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَتَعْطِفَنَّ الدُّنْيَا عَلَيْنَا بَعْدَ شِمَاسِهَا عَطْفَ الضَّرُوسِ عَلَى وَلَدِهَا، وَتَلَا عَقِيبَ ذَلِكَ: «وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ».","ob":"Que le monde, après son courroux, ait pitié de nous à la manière de la chamelle qui ne se laisse pas traire mais a de la sympathie pour ses rejetons. (Après cela, il cite le verset): «Nous voulions favoriser ceux qui avaient été faibles sur terre et en faire des dirigeants et en faire les héritiers» (28,5).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m210":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اتَّقُوا اللَّهَ تَقِيَّةَ مَنْ شَمَّرَ تَجْرِيداً، وَجَدَّ تَشْمِيراً، وَكَمَّشَ فِى مَهَلٍ، وَبَادَرَ عَنْ وَجَلٍ، وَنَظَرَ فِى كَرَّةِ الْمَوْئِلِ وَعَاقِبَةِ الْمَصْدَرِ، وَمَغَبَّةِ الْمَرْجِعِ.","ob":"Craignez Dieu comme celui qui retrousse ses habits en dénudant ses membres, se presse doucement, accourt avec peur, réfléchit sur sa destinée: être sauvée dans la vie future.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m211":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْجُودُ حَارِسُ الْأَعْرَاضِ، وَالْحِلْمُ فِدَامُ السَّفِيهِ، وَالْعَفْوُ زَكَاةُ الظَّفَرِ، وَالسُّلُوُّ عِوَضُكَ مِمَّنْ غَدَرَ، وَالِاسْتِشَارَةُ عَيْنُ الْهِدَايَةِ. وَقَدْ خَاطَرَ مَنِ اسْتَغْنَى بِرَأْيِهِ. وَالصَّبْرُ يُنَاضِلُ الْحِدْثَانَ، وَالْجَزَعُ مِنْ أَعْوَانِ الزَّمَانِ. وَأَشْرَفُ الْغِنَى تَرْكُ الْمُنَى. وَكَمْ مِنْ عَقْلٍ أَسِيرٍ تَحْتَ هَوَى أَمِيرٍ! وَمِنَ التَّوْفِيقِ حِفْظُ التَّجْرِبَةِ...","ob":"La générosité est le gardien de l'honneur et de la bonne réputation. La clémence rend le débauché bègue. Le pardon est l'aumône de la victoire. L'oubli est ta compensation lorsqu'on te trahit. Demander conseil est l'essence même de la guidance, car celui qui se passe des opinions des autres encourt un risque. La patience lutte contre les rigueurs du temps dont l'un des adjuvants est l'émotion violente d'impatience. La meilleure richesse est le délaissement des choses désirées. Que d'intelligences sont des esclaves des passions chez les gouverneurs! Retenir les leçons d'une expérience est un signe de réussite...","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m212":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"عُجْبُ الْمَرْءِ بِنَفْسِهِ أَحَدُ حُسَّادِ عَقْلِهِ.","ob":"Tu seras jaloux de ta raison si tu te sens infatué de toi-même.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m213":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَغْضِ عَلَى الْقَذَى وَالْأَلَمِ تَرْضَ أَبَداً.","ob":"Supporte l'injure et la douleur et tu seras toujours satisfait.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m215":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْخِلاَفُ يَهْدِمُ الرَّأْيَ.","ob":"La discorde détruit le discernement des opinions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m216":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ نَالَ اسْتَطَالَ.","ob":"Celui qui donne rehausse ses mérites.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m217":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فِي تَقَلُّبِ الْأَحْوَالِ عِلْمُ جَوَاهِرِ الرِّجَالِ.","ob":"On connaît l'essence des hommes d'après les vicissitudes temporelles qu'ils encourent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m218":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"حَسَدُ الصَّدِيقِ مِنْ سُقْمِ الْمَوَدَّةِ.","ob":"Envier un ami dénote une faible amitié.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m219":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَكْثَرُ مَصَارِعِ الْعُقُولِ تَحْتَ بُرُوقِ الْمَطَامِعِ.","ob":"Les arènes où l'on renverse violemment les intelligences se trouvent principalement sous les éclairs des ambitions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m220":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَيْسَ مِنَ الْعَدْلِ الْقَضَاءُ عَلَى الثِّقَةِ بِالظَّنِّ.","ob":"Il est injuste de tuer la confiance par la présomption.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m221":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"بِئْسَ الزَّادُ إِلَى الْمَعَادِ الْعُدْوَانُ عَلَى الْعِبَادِ.","ob":"L'agression contre les serviteurs de Dieu est une malheureuse provision pour le Jour du Jugement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m222":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مِنْ أَشْرَفِ أعمال الْكَرِيمِ غَفْلَتُهُ عَمَّا يَعْلَمُ.","ob":"L'une des plus honnêtes actions de l'homme généreux est de ne pas faire attention à ce qu'il sait.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m223":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ كَسَاهُ الْحَيَاءُ ثَوْبَهُ، لَمْ يَرَ النَّاسُ عَيْبَهُ.","ob":"Les hommes ne voient pas les défauts de celui qui est revêtu par la pudeur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m224":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"بِكَثْرَةِ الصَّمْتِ تَكُونُ الْهَيْبَةُ، وَبِالنَّصَفَةِ يَكْثُرُ الْمُوَاصِلُونَ، وَبِالْإِفْضَالِ تَعْظُمُ الْأَقْدَارُ، وَبِالتَّوَاضُعِ تَتِمُّ النِّعْمَةُ... وَبِالسِّيرَةِ الْعَادِلَةِ يُقْهَرُ الْمُنَاوِئُ...","ob":"Celui qui garde longtemps le silence reçoit une vénération mêlée de crainte. L'équité attire beaucoup de sympathisants. La valeur d'un homme est fonction de ses mérites. La grâce s'octroie par l'humilité... L'adversaire sera vaincu par une bonne conduite...","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m227":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْإِيمَانُ مَعْرِفَةٌ بِالْقَلْبِ، وَإِقْرَارٌ بِاللِّسَانِ، وَعَمَلٌ بِالْأَرْكَانِ.","ob":"La foi est une connaissance par le cœur, un témoignage par la langue et une application des piliers [de l'Islam].","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m228":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَصْبَحَ عَلَى الدُّنْيَا حَزِيناً فَقَدْ أَصْبَحَ لِقَضَاءِ اللّٰهِ سَاخِطاً، وَمَنْ أَصْبَحَ يَشْكُو مُصِيبَةً نَزَلَتْ بِهِ فَقَدْ أَصْبَحَ يَشْكُو رَبَّهُ، وَمَنْ أَتى غَنِيَّاً فَتَوَاضَعَ له لِغِنَاهُ ذَهَبَ ثُلُثَا دِينِهِ، وَمَنْ قَرَأَ الْقُرْآنَ فَمَاتَ فَدَخَلَ النَّارَ فَهُوَ كَانَ يَتَّخِذُ آيَاتِ اللّٰهِ هُزُواً، وَمَنْ لَهِجَ قَلْبُهُ بِحُبِّ الدُّنْيَا الْتَاطَ قَلْبُهُ مِنْهَا بِثَلاَثٍ: هَمٍّ لَا يُغِبُّهُ، وَحِرْصٍ لَا يَتْرُكُهُ، وَأَمَلٍ لَا يُدْرِكُهُ.","ob":"Celui qui se lève triste le matin met en colère Dieu dans son arrêt immuable. S'il se plaint le matin d'un malheur c'est comme s'il se plaignait de Dieu. Celui qui se présente et s'humilie devant un riche perd les deux tiers de sa religion. Celui qui lit le Coran puis meurt et entre au Feu avait tourné ses versets en dérision. Celui dont le cœur s'adonne à l'amour de la vie terrestre voit son cœur adhéré à trois choses: un souci qui ne le quitte pas, une avidité qui ne le lâche pas et un espoir qu'il ne peut point réaliser.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m229":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كَفَى بِالْقَنَاعَةِ مُلْكاً، وَبِحُسْنِ الْخُلُقِ نَعِيماً... وَسُئِلَ عليه السلام عَنْ قَوْلِهِ تَعَالَى: «فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً»، فَقَالَ: هِيَ الْقَنَاعَةُ.","ob":"La tempérance est le bien le plus suffisant. La bonne conduite est la meilleure vie de bien-être. ...(On lui demande de qui s'agit-il dans l'expression «Nous lui ferons vivre une bonne vie» (16,97), il répond): C'est celui qui a de la tempérance.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m230":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"شَارِكُوا الَّذِي قَدْ أَقْبَلَ عَلَيْهِ الرِّزْقُ، فَإِنَّهُ أَخْلَقُ لِلْغِنَى، وَأَجْدَرُ بِإِقْبَالِ الْحَظِّ عَلَيْهِ.","ob":"Associez-vous à celui que la prospérité enrichit, car il est le plus digne d'être riche et d'être servi par la bonne chance.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m231":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي قَوْلِهِ تَعَالَى: «إِنَّ اللّٰهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ»، الْعَدْلُ: الْإِنْصَافُ، وَالْإِحْسَانُ: التَّفَضُّلُ.","ob":"(Il commente l'expression coranique «Certes, Allah commande l'équité et la bienfaisance» (16,90) en disant): L'équité c'est être juste et rendre justice; La bienfaisance c'est accorder une faveur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m232":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ يُعْطِ بِالْيَدِ الْقَصِيرَةِ يُعْطَ بِالْيَدِ الطَّوِيلَةِ.","ob":"Celui qui donne par la main courte [celle des hommes] recevra de la main longue [celle de Dieu].","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m233":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِابْنِهِ الْحَسَنِ عليهما السلام: لَا تَدْعُوَنَّ إِلَى مُبَارَزَةٍ، وَإِنْ دُعِيتَ إِلَيْهَا فَأَجِبْ، فَإِنَّ الدَّاعِيَ إِلَيْهَا بَاغٍ، وَالْبَاغِيَ مَصْرُوعٌ.","ob":"(Il dit à son fils al-Ḥasan): N'invite personne à un duel. Si tu y es invité réponds, car celui qui demande le duel est injuste, et l'injuste sera vaincu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m234":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"خِيَارُ خِصَالِ النِّسَاءِ شِرَارُ خِصَالِ الرِّجَالِ: الزَّهْوُ، وَالْجُبْنُ، وَالْبُخْلُ؛ فَإِذَا كَانَتِ الْمَرْأَةُ مَزْهُوَّةً لَمْ تُمَكِّنْ مِنْ نَفْسِهَا، وَإِذَا كَانَتْ بِخِيلَةً حَفِظَتْ مَالَهَا وَمَالَ بَعْلِهَا، وَإِذَا كَانَتْ جَبَانَةً فَرِقَتْ مِنْ كُلِّ شَيْءٍ يَعْرِضُ لَهَا.","ob":"Les meilleures propriétés des femmes sont les pires propriétés des hommes: la vanité, la couardise et l'avarice; si la femme est vaniteuse elle ne se livre pas; si elle est avare, elle garde ses biens et ceux de son époux: et si elle est couarde, elle a peur de tout ce qui lui advient.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m235":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقِيلَ لَهُ: صِفْ لَنَا الْعَاقِلَ، فَقَالَ: هُوَ الَّذِي يَضَعُ الشَّيْءَ مَوَاضِعَهُ، فَقِيلَ: فَصِفْ لَنَا الْجَاهِلَ، فَقَالَ: قَدْ فَعَلْتُ.","ob":"(On lui demande de décrire l'homme sensé; il dit): C'est celui qui met chaque chose à sa place. (On lui demande de décrire l'ignorant; il dit): Je l'ai déjà fait [c.à-d. c'est le contraire du sensé].","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m236":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَاللهِ لَدُنْيَاكُمْ هذِهِ أَهْوَنُ فِي عَيْنِي مِنْ عِرَاقِ خِنْزِيرٍ فِي يَدِ مَجْذُومٍ.","ob":"Par Dieu, votre monde-ci est plus bas à mes yeux que l'estomac d'un porc entre les mains d'un lépreux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m237":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ قَوْماً عَبَدُوا اللّٰهَ رَغْبَةً فَتِلْكَ عِبَادَةُ التُّجَّارِ، وَإِنَّ قَوْماً عَبَدُوا اللّٰهَ رَهْبَةً فَتِلْكَ عِبَادَةُ الْعَبِيدِ، وَإِنَّ قَوْماً عَبَدُوا اللّٰهَ شُكْراً فَتِلْكَ عِبَادَةُ الْأَحْرَارِ.","ob":"Ceux qui adorent Dieu par empressement sont des commerçants, par peur sont des esclaves et par action sont des gens libres.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m238":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْمَرْأَةُ شَرٌّ كُلُّهَا، وَشَرُّ مَا فِيهَا أَنَّهُ لَا بُدَّ مِنْهَا!","ob":"La femme tout entière est mauvaise, mais le pire est qu'elle est indispensable!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m239":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَطَاعَ التَّوَانِيَ ضَيَّعَ الْحُقُوقَ، وَمَنْ أَطَاعَ الْوَاشِيَ ضَيَّعَ الصَّدِيقَ.","ob":"Celui qui lambine perd les droits et celui qui obéit au dénonciateur perd l'ami.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m241":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَوْمُ الْمَظْلُومِ عَلَى الظَّالِمِ أَشدُّ مِنْ يَوْمِ الظَّالِمِ عَلَى الْمَظْلُومِ.","ob":"Le jour de la revanche de l'opprimé contre l'oppresseur est plus pénible que celui de l'oppresseur injuste envers l'opprimé.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m242":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اتَّقِ اللّٰهَ بَعْضَ التُّقَى وَإِنْ قَلَّ، وَاجْعَلْ بَيْنَكَ وَبَيْنَ اللّٰهِ سِتْراً وَإِنْ رَقَّ.","ob":"Crains Dieu même si ta piété est minime, et pose entre Lui et toi un voile même très mince.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m243":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا ازْدَحَمَ الْجَوَابُ، خَفِيَ الصَّوَابُ.","ob":"Le sens exact d'une notion se perd par l'enjambement des champs sémantiques de la parole.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m244":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ لله فِي كُلِّ نِعْمَةٍ حَقّاً، فَمَنْ أَدَّاهُ زَادَهُ مِنْهَا، وَمَنْ قَصَّرَ فيه خَاطَرَ بِزَوَالِ نِعْمَتِهِ.","ob":"Dieu doit être loué pour toute grâce qu'Il donne. Celui qui Le loue verra Sa grâce augmentée et vice versa.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m245":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا كَثُرَتِ الْمَقْدِرَةُ قَلَّتِ الشَّهْوَةُ.","ob":"Lorsque la puissance augmente, la passion diminue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m246":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"احْذَرُوا نِفَارَ النِّعَمِ فَمَا كُلُّ شَارِدٍ بِمَرْدُودٍ.","ob":"Ayez garde que les grâces de Dieu ne se dispersent loin de vous, car elles ne vous reviennent pas.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m247":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْكَرَمُ أَعْطَفُ مِنَ الرَّحِمِ.","ob":"La générosité est plus miséricordieuse que l'utérus.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m248":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ ظَنَّ بِكَ خَيْراً فَصَدِّقْ ظَنَّهُ.","ob":"Crois celui qui se forme une bonne opinion en ta faveur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m249":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَفْضَلُ الْأَعْمَالِ مَا أَكْرَهْتَ نَفْسَكَ عَلَيْهِ.","ob":"La meilleure action est celle que tu as faite bon gré mal gré.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m251":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَرَارَةُ الدُّنْيَا حَلاَوَةُ الْآخِرَةِ، وَحَلاَوَةُ الدُّنْيَا مَرَارَةُ الْآخِرَةِ.","ob":"L'amertume de la vie terrestre constitue la douceur de l'Au-delà et vice versa.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m252":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"فَرَضَ اللَّهُ الْإِيمَانَ تَطْهِيراً مِنَ الشِّرْكِ، وَالصَّلَاةَ تَنْزِيهاً عَنِ الْكِبْرِ، وَالزَّكَاةَ تَسْبِيباً لِلرِّزْقِ، وَالصِّيَامَ ابْتِلَاءً لِإِخْلَاصِ الْخَلْقِ، وَالْحَجَّ تَقْرِبَةً لِلدِّينِ، وَالْجِهَادَ عِزّاً لِلْإِسْلَامِ، وَالْأَمْرَ بِالْمَعْرُوفِ مَصْلَحَةً لِلْعَوَامِّ، وَالنَّهْيَ عَنِ الْمُنْكَرِ رَدْعاً لِلسُّفَهَاءِ، وَصِلَةَ الرَّحِمِ مَنْمَاةً لِلْعَدَدِ، وَالْقِصَاصَ حَقْناً لِلدِّمَاءِ، وَإِقَامَةَ الْحُدُودِ إِعْظَاماً لِلْمَحَارِمِ، وَتَرْكَ شُرْبِ الْخَمْرِ تَحْصِيناً لِلْعَقْلِ، وَمُجَانَبَةَ السَّرِقَةِ إِيجَاباً لِلْعِفَّةِ، وَتَرْكَ الزِّنَى تَحْصِيناً لِلنَّسَبِ، وَتَرْكَ اللِّوَاطِ تَكْثِيراً لِلنَّسْلِ، وَالشَّهَادَاتِ اسْتِظْهَاراً عَلَى الْمُجَاحَدَاتِ، وَتَرْكَ الْكَذِبِ تَشْرِيفاً لِلصِّدْقِ، وَالسَّلَامَ أَمَاناً مِنَ الْمَخَاوِفِ، وَالْأَمَانَةَ نِظَاماً لِلْأُمَّةِ، وَالطَّاعَةَ تَعْظِيماً لِلْإِمَامَةِ.","ob":"Dieu a imposé la foi comme une épuration de l'association, la prière comme un éloignement du mal de l'orgueil, la <i>zakāt</i> comme une cause de la subsistance, le jeûne comme une épreuve de la sincérité de la création, le pèlerinage comme une occasion de faire rapprocher les croyants les uns des autres, le <i>jihād</i> comme une puissance honorable de l'Islam, le commandement du convenable comme un intérêt pour le public, l'interdiction du blâmable comme une admonition pour les insolents, les liens de consanguinité comme un accroissement du nombre des croyants, la punition comme un arrêt de l'écoulement du sang, l'application concrète des lois comme un châtiment des actes nuisibles [vol, adultère, etc], l'interdiction des boissons alcooliques comme une fortification de l'intellect, la défense de voler comme une affirmation de la sobriété, la prohibition de l'adultère comme une protection du lignage, la proscription de l'homosexualité comme une augmentation de la population, les témoignages juridiques comme un empêchement des démentis, le rejet du mensonge comme une façon d'honorer la véracité, la paix comme une sécurité contre les agents de la peur, la loyauté comme le régime de la nation, et l'obéissance comme la magnificence de l'imamat.","obNotes":[],"an":"Selon l'Imām, Dieu a prescrit la foi pour purifier l'homme du polythéisme, la prière pour l'éloigner de l'orgueil, la zakat pour une meilleure répartition des richesses, le jeûne pour éprouver la sincérité des croyants, le pèlerinage pour rapprocher les fidèles dans la religion, la guerre sainte pour rehausser la gloire de l'Islam.\nIl a ordonné qu'on prêche le bien pour l'intérêt public et qu'on interdise le mal pour dissuader les pervers; qu'on renforce les liens de consanguinité pour assurer une meilleure prolifération. Il a établi la rançon comme moyen d'éviter l'effusion du sang, la flagellation pour insister sur le caractère d'inviolabilité des interdits, l'abstention de la consommation de l'alcool pour protéger la lucidité de l'esprit il a interdit le vol pour assurer le règne de la probité, l'adultère pour éviter toute confusion dans les liens de parenté, la pratique de l'homosexualité pour l'augmentation de la natalité. Il a recommandé les témoignages pour démasquer ceux qui veulent passer sous silence les droits des individus, l'abstention du mensonge pour l'instauration de la vérité, la paix afin d'éloigner la peur, la confiance comme règle pour la communauté et l'obéissance par respect de l'imamat.","anIntro":"","anNotes":[],"diff":null}]},"m254":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يابْن آدَمَ، كُنْ وَصِيَّ نَفْسِكَ فِى مَالِكَ، وَاعْمَلْ فِيهِ مَا تُؤْثِرُ أَنْ يُعْمَلَ فِيهِ مِنْ بَعْدِكَ.","ob":"O fils d'Adam, sois le propre tuteur de tes biens, et gère-les comme tu voudras qu'ils soient gérés après toi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m255":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْحِدَّةُ ضَرْبٌ مِنَ الْجُنُونِ، لِأنَّ صَاحِبَهَا يَنْدَمُ، فَإِنْ لَمْ يَنْدَمْ فَجُنُونُهُ مُسْتَحْكِمٌ.","ob":"La colère est une sorte de folie, car le coléreux la regrette. Mais s'il ne se repent pas, c'est signe que sa folie est bien ancrée.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m256":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"صِحَّةُ الْجَسَدِ مِنْ قِلَّةِ الْحَسَدِ.","ob":"La santé du corps provient du peu de jalousie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m257":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِكُمَيْلِ بْنِ زِيَادٍ النَّخَعِيِّ: يَا كُمَيْلُ، مُرْ أَهْلَكَ أَنْ يَرُوحُوا فِي كَسْبِ الْمَكَارِمِ، وَيُدْلِجُوا فِي حَاجَةِ مَنْ هُوَ نائِمٌ. فَوَالَّذِي وَسِعَ سَمْعُهُ الْأَصْوَاتَ، مَا مِنْ أَحَدٍ أَوْدَعَ قَلْباً سُرُوراً إِلَّا وَخَلَقَ اللّٰهُ لَهُ مِنْ ذلِكَ السُّرُورِ لُطْفاً.","ob":"(Il dit à Kumayl ibn Ziyād al-Nakha'ī): O Kumayl, ordonne aux tiens de vaguer l'après-midi au gain des actions nobles et généreuses et de marcher au début de la nuit pour combler les besoins des dormants. Par Celui dont l'ouïe entend toutes les voix, Celui qui remplit le cœur d'un autre de plaisirs Dieu lui est fort sympathique.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m258":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا أَمْلَقْتُمْ فَتَاجِرُوا اللّٰهَ بِالصَّدَقَةِ.","ob":"Si vous tombez en faillite commercez avec Dieu via l'aumône.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m259":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْوَفَاءُ لِأَهْلِ الْغَدْرِ غَدْرٌ عِنْدَ اللهِ، وَالْغَدْرُ بِأَهْلِ الْغَدْرِ وَفَاءٌ عِنْدَ اللهِ.","ob":"La fidélité envers les trompeurs est une trahison envers Dieu, et la trahison des trompeurs est une fidélité envers Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m261":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وقال عليه السلام: لَمَّا بَلَغَهُ إِغَارَةُ أَصْحَابِ مُعَاوِيَةَ عَلَى الْأَنْبَارِ، فَخَرَجَ بِنَفْسِهِ مَاشِياً حَتَّى أَتَى النُّخَيْلَةَ فأدركه النَّاسُ، وَقَالُوا: يَا أَمِيرَ الْمُؤْمِنِينَ نَحْنُ نكفيكم، فَقَالَ: مَا تَكْفُونَنِي أَنْفُسَكُمْ، فَكَيْفَ تَكْفُونَنِي غَيْرَكُمْ؟ إِنْ كَانَتِ الرَّعَايَا قَبْلِي لَتشكو حَيْفَ رُعَاتِهَا، وَإِنَّنِي الْيَوْمَ لَأَشْكُو حَيْفَ رَعِيَّتِي، كَأَنَّنِيَ الْمَقُودُ وَهُمُ الْقَادَةُ، أَوِ الْمَوْزُوعُ وَهُمُ الْوَزَعَةُ!","ob":"Lorsqu'il sut que les gens de Mu'āwiya eurent attaqué al-Anbār, il se mit à marcher jusqu'à atteindre al-Nukhayla [en Irak]. Ses partisans le suivirent et dirent: ô Prince des Croyants, nous nous occuperons d'eux, et de répondre: Comment allez-vous vous occuper d'eux si vous êtes nonchalants envers moi? Avant moi, les sujets se plaignaient de l'injustice de leurs dirigeants; aujourd'hui je me plains de l'injustice de mes sujets, comme si j'étais un subalterne gouverné tandis qu'ils sont les chefs qui gouvernent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m263":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"صَاحِبُ السُّلْطَانِ كَرَاكِبِ الْأَسَدِ: يُغْبَطُ بِمَوْقِعِهِ، وَهُوَ أَعْلَمُ بِمَوْضِعِهِ.","ob":"Celui qui détient le pouvoir est comme celui qui monte un lion: les autres souhaitent avoir sa position sans être conscients des dangers auxquels il s'expose.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m264":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَحْسِنُوا فِي عَقِبِ غَيْرِكُمْ تُحْفَظُوا فِي عَقِبِكُمْ.","ob":"Soyez miséricordieux envers les enfants des autres pour que ceux-ci soient miséricordieux envers les vôtres.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m265":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ كَلاَمَ الْحُكَمَاءِ إِذَا كَانَ صَوَاباً كَانَ دَوَاءً، وَإِذَا كَانَ خَطَأً كَانَ دَاءً.","ob":"Si les paroles des sages étaient véridiques, elles seraient un remède. Mais si elles étaient erronées, elles seraient une maladie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m267":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَابْنَ آدَمَ، لَا تَحْمِلْ هَمَّ يَوْمِكَ الَّذِي لَمْ يَأْتِكَ عَلَى يَوْمِكَ الَّذِي قَدْ أَتَاكَ، فَإِنَّهُ إِنْ يَكُ مِنْ عُمُرِكَ يَأْتِ اللّٰهُ فِيهِ بِرِزْقِكَ.","ob":"O fils d'Adam, n'ajoute pas le souci des jours futurs à ceux d'aujourd'hui. Si ces jours font partie de votre âge, Dieu y pourvoira à tes besoins.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m268":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"أَحْبِبْ حَبِيبَكَ هَوْناً مَا، عَسَى أَنْ يَكُونَ بَغِيضَكَ يَوْماً مَا، وَأَبْغِضْ بَغِيضَكَ هَوْناً مَا، عَسَى أَنْ يَكُونَ حَبِيبَكَ يَوْماً مَا.","ob":"Aime ton bien-aimé et hais ton ennemi sans exagération, car il se peut que le premier devienne ton ennemi et le second ton bien-aimé.","obNotes":[],"an":"Aime modérément ton ami et hais de même ton ennemi, le premier pouvant devenir un ennemi et le dernier se transformer en ami.","anIntro":"","anNotes":[],"diff":null}]},"m269":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"النَّاسُ فِي الدُّنْيَا عَامِلاَنِ: عَامِلٌ عَمِلَ فِي الدُّنْيَا لِلدُّنْيَا، قَدْ شَغَلَتْهُ دُنْيَاهُ عَنْ آخِرَتِهِ، يَخْشَى عَلَى مَنْ يَخْلُفُهُ الْفَقْرَ، وَيَأْمَنُهُ عَلَى نَفْسِهِ، فَيُفْنِي عُمُرَهُ فِي مَنْفَعَةِ غَيْرِهِ؛ وَعَامِلٌ عَمِلَ فِي الدُّنْيَا لِمَا بَعْدَهَا، فَجَاءَهُ الَّذِي لَهُ مِنَ الدُّنْيَا بِغَيْرِ عَمَلٍ، فَأَحْرَزَ الْحَظَّيْنِ مَعاً، وَمَلَكَ الدَّارَيْنِ جَمِيعاً، فَأَصْبَحَ وَجِيهاً عِنْدَ اللَّهِ، لَا يَسْأَلُ اللّٰهَ حَاجَةً فَيَمْنَعَهُ.","ob":"Les gens de ce monde se divisent en deux types: Celui qui agit pour l'amour du monde qui le dissipe de la vie future; il craint la pauvreté pour ses descendants, il se garantit contre elle durant sa vie et passe ses jours à faire bénéficier les autres de son travail. Mais il y a aussi celui qui travaille dans ce monde pour la vie future, tout en ayant sa part gratuite des bienfaits de ce monde; alors il acquiert les deux demeures; il devient distingué aux yeux de Dieu qui ne lui refuse rien de ce qui lui est nécessaire durant sa vie terrestre.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m270":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَرُوِيَ أَنَّهُ ذُكِرَ عِنْدَ عُمَرَ بْنِ الْخَطَّابِ فِي أَيَّامِهِ حَلْيُ الْكَعْبَةِ وَكَثْرَتُهُ، فَقَالَ قَوْمٌ: لَوْ أَخَذْتَهُ فَجَهَّزْتَ بِهِ جُيُوشَ الْمُسْلِمِينَ كَانَ أَعْظَمَ لِلْأَجْرِ، وَمَا تَصْنَعُ الْكَعْبَةُ بِالْحَلْيِ؟ فَهَمَّ عُمَرُ بِذَلِكَ، وَسَأَلَ عَنْهُ أَمِيرَ الْمُؤْمِنِينَ عليه السلام، فقال عليه السلام: إِنَّ هذا القُرْآنَ أُنْزِلَ عَلَى النَّبِيِّ صلى اللّٰه عليه وآله وسلَّم، وَالْأَمْوَالُ أَرْبَعَةٌ: أَمْوَالُ الْمُسْلِمِينَ فَقَسَّمَهَا بَيْنَ الْوَرَثَةِ فِي الْفَرَائِضِ؛ وَالْفَيْءُ فَقَسَّمَهُ عَلَى مُسْتَحِقِّيهِ؛ وَالْخُمُسُ فَوَضَعَهُ اللّٰهُ حَيْثُ وَضَعَهُ؛ وَالصَّدَقَاتُ فَجَعَلَهَا اللّٰهُ حَيْثُ جَعَلَهَا، وَكَانَ حَلْيُ الْكَعْبَةِ فِيهَا يَوْمَئِذٍ، فَتَرَكَهُ اللّٰهُ عَلَى حَالِهِ، وَلَمْ يَتْرُكْهُ نِسْيَاناً، وَلَمْ يَخْفَ عَلَيْهِ مَكَاناً، فَأَقِرَّهُ حَيْثُ أَقَرَّهُ اللّٰهُ وَرَسُولُهُ. فقال له عمر: لولاك لافتضحنا. وترك الحَلْي بحاله.","ob":"On raconte que lorsque 'Umar ibn al-Khaṭṭāb s'occupait à maintes reprises de la parure de la Ka'ba, on lui dit qu'il vaudrait mieux que l'argent soit dépensé pour équiper l'armée musulmane, car qu'a la Ka'ba à faire avec la parure. 'Umar demanda son opinion à 'Alī qui répond: D'après le Coran, il existe quatre types d'argent: l'argent des musulmans, qui doit légalement être distribué aux successeurs; l'argent du butin qui doit être distribué à ceux qui le méritent; le cinquième [la dîme]; et les aumônes dont faisait part, jadis, la parure de la Ka'ba. Or Dieu ordonne qu'on laisse les arrangements tels qu'ils étaient au temps du prophète. 'Umar lui dit: sans ton avis, ce serait le scandale. Et il n'a pas touché à la parure.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m271":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"ورُوي أَنَّهُ عليه السلام رُفِعَ إِلَيْهِ رَجُلَانِ سَرَقَا مِنْ مَالِ اللَّهِ، أَحَدُهُمَا عَبْدٌ مِنْ مَالِ اللَّهِ، وَالْآخَرُ مِنْ عُرُوضِ النَّاسِ. أَمَّا هذَا فَهُوَ مِنْ مَالِ اللّٰهِ وَلَا حَدَّ عَلَيْهِ... وَأَمَّا الْآخَرُ فَعَلَيْهِ الْحَدُّ الشَّدِيدُ. فَقَطَعَ يَدَهُ.","ob":"On raconte qu'on lui présenta deux hommes dont le premier est un esclave qui avait volé de l'argent de Dieu et le second qui était un voleur des maisons. Il dit: le premier a pris de l'argent de Dieu et n'encourt aucun châtiment, tandis que le second mérite le châtiment sévère: sa main fut coupée.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m273":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اعْلَمُوا عِلْماً يَقِيناً أَنَّ اللَّهَ لَمْ يَجْعَلْ لِلْعَبْدِ -وَإِنْ عَظُمَتْ حِيلَتُهُ، وَاشْتَدَّتْ طَلِبَتُهُ، وقَوِيّت مَكِيدَتُهُ- أَكْثَرَ مِمَّا سُمِّيَ لَهُ فِى الذِّكْرِ الْحَكِيمِ، وَلَمْ يَحُلْ بَيْنَ الْعَبْدِ فِى ضَعْفِهِ وَقِلَّةِ حِيلَتِهِ، وَبَيْنَ أَنْ يَبْلُغَ مَا سُمِّيَ لَهُ فِى الذِّكْرِ الْحَكِيمِ. وَالْعَارِفُ لِهَذَا، الْعَامِلُ بِهِ، أَعْظَمُ النَّاسِ رَاحَةً فِى مَنْفَعَةٍ، وَالتَّارِكُ لَهُ الشَّاكُّ فِيهِ أَعْظَمُ النَّاسِ شُغُلًا فِى مَضَرَّةٍ. وَرُبَّ مُنْعَمٍ عَلَيْهِ مُسْتَدْرَجٌ بِالنُّعْمَى، وَرُبَّ مُبْتَلًى مَصْنُوعٌ لَهُ بِالْبَلْوَى! فَزِدْ أَيُّهَا الْمُسْتَنْفِعُ فِى شُكْرِكَ، وَقَصِّرْ مِنْ عَجَلَتِكَ، وَقِفْ عِنْدَ مُنْتَهَى رِزْقِكَ.","ob":"Sachez certainement que Dieu ne donne pas au serviteur - même s'il était très astucieux, s'il use d'un grand artifice et insiste énormément- plus que ne lui donne le Coran. Dieu n'empêche non plus le serviteur, malgré sa faiblesse et le peu d'astuce qu'il a, d'atteindre ce qui lui est dû d'après le Coran. Celui qui connaît cette vérité et agit selon elle connait le plus grand bien-être, mais celui qui en doute et la délaisse rencontre la besogne la plus rude et la plus nuisible. Il arrive souvent que Dieu amène l'homme heureux par degrés à une plus grande prospérité et augmente le malheur de celui qu'Il éprouve! O toi qui cherches ton propre avantage augmente tes remerciements, ne te hâte pas dans l'acquisition de tes biens qui doivent avoir une limite.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m274":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَجْعَلُوا عِلْمَكُمْ جَهْلًا، وَيَقِينَكُمْ شَكّاً. إِذَا عَلِمْتُمْ فَاعْمَلُوا، وَإِذَا تَيَقَّنْتُمْ فَأَقْدِمُوا.","ob":"Ne transformez pas votre science en ignorance et votre certitude en doute. Si vous connaissez agissez, et si vous êtes certains soyez hardis.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m275":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ الطَّمَعَ مُورِدٌ غَيْرُ مُصْدِرٍ، وَضَامِنٌ غَيْرُ وَفِيٍّ. وَرُبَّمَا شَرِقَ شَارِبُ الْمَاءِ قَبْلَ رِيِّهِ؛ وَكُلَّمَا عَظُمَ قَدْرُ الشيء الْمُتَنَافَسِ فِيهِ عَظُمَتِ الرَّزِيَّةُ لِفَقْدِهِ. وَالْأَمَانِيُّ تُعْمِى أَعْيُنَ الْبَصَائِرِ، وَالْحَظُّ يَأْتِى مَنْ لَا يَأْتِيهِ.","ob":"L'avidité ne produit que la perte; elle ne donne qu'une assurance aléatoire. Il se peut que celui qui veut boire soit suffoqué par l'eau avant d'étancher sa soif. Toutes les fois que la valeur d'une chose disputée augmente, sa perte entraîne un malheur de plus en plus grand. Les aspirations font aveugler les cœurs et la chance touche celui qui ne s'y attend pas.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m276":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنْ أَنْ تُحَسِّنَ فِى لَامِعَةِ الْعُيُونِ عَلَانِيَتِي، وَتُقَبِّحَ فِيمَا أُبْطِنُ لَكَ سَرِيرَتِى، مُحَافِظاً عَلَى رِثَاءِ النَّاسِ مِنْ نَفْسِى بِجَمِيعِ مَا أَنْتَ مُطَّلِعٌ عَلَيْهِ مِنِّى، فَأُبْدِيَ لِلنَّاسِ حُسْنَ ظَاهِرِى، وَأُفْضِيَ إِلَيْكَ بِسُوءِ عَمَلِى تَقَرُّباً إِلَى عِبَادِكَ، وَتَبَاعُداً مِنْ مَرْضَاتِكَ.","ob":"Dieu me garde d'améliorer aux yeux des hommes mon aspect extérieur afin qu'ils déplorent mon état que Dieu connaît, tout comme Il connaît mes mauvaises actions. Non, mon Dieu, c'est Ton contentement que je veux, et non celui des hommes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m278":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"قَلِيلٌ تَدُومُ عَلَيْهِ أَرْجَى مِنْ كَثِيرٍ مَمْلُولٍ مِنْهُ.","ob":"Le peu que tu continues de faire vaut mieux qu'une grande action que tu laisses par ennui.","obNotes":[],"an":"Un bien médiocre qui dure est préférable à un bien abondant qui crée l'ennui.","anIntro":"","anNotes":[],"diff":null}]},"m279":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا أَضَرَّتِ النَّوَافِلُ بِالْفَرَائِضِ فَارْفُضُوهَا.","ob":"Si les surérogations [ce qu'on fait au-delà de ce qui est dû ou imposé] nuisent aux ordres obligatoires, refusez-les.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m280":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ تَذَكَّرَ بُعْدَ السَّفَرِ اسْتَعَدَّ.","ob":"Quiconque se souvient de l'éloignement du voyage se prépare.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m281":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَيْسَتِ الرَّوِيَّةُ كَالْمُعَايَنَةِ مَعَ الْإِبْصَارِ، فَقَدْ تَكْذِبُ الْعُيُونُ أَهْلَهَا، وَلَا يَغُشُّ الْعَقْلُ مَنِ اسْتَنْصَحَهُ.","ob":"L'examen attentif d'une chose vaut mieux que l'observation visuelle; les yeux peuvent induire en erreur, mais la raison ne trompe pas celui qui lui demande conseil.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m282":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"بَيْنَكُمْ وَبَيْنَ الْمَوْعِظَةِ حِجَابٌ مِنَ الْغِرَّةِ.","ob":"L'inattention vous voile toute prédication.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m283":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"جَاهِلُكُمْ مُزْدَادٌ، وَعَالِمُكُمْ مُسَوِّفٌ.","ob":"L'ignorant parmi vous agit avec excès et sans circonspection, et le savant renvoie les choses du jour au lendemain.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m284":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قَطَعَ الْعِلْمُ عُذْرَ الْمُتَعَلِّلِينَ.","ob":"La science coupe court à l'allégation des excuses.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m285":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُلُّ مُعَاجَلٍ يَسْأَلُ الْإِنْظَارَ، وَكُلُّ مُؤَجَّلٍ يَتَعَلَّلُ بالتَّسْويفِ.","ob":"Celui à qui on demande de s'empresser demande qu'on lui donne un délai et celui auquel un terme a été donné trouve des prétextes pour renvoyer le solliciteur du jour au lendemain.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m286":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا قَالَ النَّاسُ لِشَيْءٍ «طُوبَى لَهُ» إِلَّا وَقَدْ خَبَأَ لَهُ الدَّهْرُ يَوْمَ سَوْءٍ.","ob":"Les gens ne disent de quelqu'un «qu'il soit heureux» sans qu'ils se rendent compte que la Fortune lui a caché de mauvais jours.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m287":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَسُئِلَ عَنِ الْقَدَرِ، فقال: طَرِيقٌ مُظْلِمٌ فَلاَ تَسْلُكُوهُ، وَبَحْرٌ عَمِيقٌ فَلاَ تَلِجُوهُ، وَسِرُّ اللّٰهِ فَلاَ تَتَكَلَّفُوهُ.","ob":"On lui demande de décrire le destin; il dit: une voie obscure que vous ne suivriez pas, une mer profonde que vous n'y pénétriez pas, le secret de Dieu que vous deviez respecter.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m288":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا أَرْذَلَ اللّٰهُ عَبْداً حَظَرَ عَلَيْهِ الْعِلْمَ.","ob":"Si Dieu voulait avilir un serviteur, Il l'empêcherait d'acquérir la science.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m289":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كَانَ لِى فِيمَا مَضَى أَخٌ فِى اللَّهِ، وَكَانَ يُعْظِمُهُ فِى عَيْنِى صِغَرُ الدُّنْيَا فِى عَيْنِهِ. وَكَانَ خَارِجاً مِنْ سُلْطَانِ بَطْنِهِ، فَلَا يَشْتَهِى مَا لَا يَجِدُ، وَلَا يُكْثِرُ إِذَا وَجَدَ. وَكَانَ أَكْثَرَ دَهْرِهِ صَامِتاً، فَإِنْ قَالَ بَذَّ الْقَائِلِينَ، وَنَقَعَ غَلِيلَ السَّائِلِينَ. وَكَانَ ضَعِيفاً مُسْتَضْعَفاً!","ob":"J'avais dans le temps un frère en Dieu. Il était très grand à mes yeux parce que le monde était très petit à ses yeux. Il était libéré de l'empire de son estomac, ne convoitait pas ce qu'il n'a pas et, s'il l'a, il n'en abuse pas. La plupart du temps il était silencieux, mais lorsqu'il parlait il faisait taire ceux qui parlent et abreuvait ceux qui demandent des explications. Il était faible et tenu pour tel!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"فَإِنْ جَاءَ الْجِدُّ فَهُوَ لَيْثُ غَابٍ، وَصِلُّ وَادٍ، لَا يُدْلِى بِحُجَّةٍ حَتَّى يَأْتِيَ قَاضِياً. وَكَانَ لَا يَلُومُ أَحَداً عَلَى مَا يَجِدُ الْعُذْرَ فِى مِثْلِهِ، حَتَّى يَسْمَعَ اعْتِذَارَهُ؛ وَكَانَ لَا يَشْكُو وَجَعاً إِلَّا عِنْدَ بُرْئِهِ.","ob":"Cependant, face aux affaires sérieuses il était comme le lion de la savane et le serpent de la vallée. Il ne citait un argument que pour trancher une affaire. Il ne blâmait personne, qui pourrait être excusable, avant d'entendre son excuse. Il ne se plaignait d'une maladie qu'après qu'il en fût guéri.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[3],"ar":"وَكَانَ يَقُولُ مَا يَفْعَلُ وَلَا يَقُولُ مَا لَا يَفْعَلُ؛ وَكَانَ إِذَا غُلِبَ عَلَى الْكَلَامِ لَمْ يُغْلَبْ عَلَى السُّكُوتِ، وَكَانَ عَلَى مَا يَسْمَعُ أَحْرَصَ مِنْهُ عَلَى أَنْ يَتَكَلَّمَ؛ وَكَانَ إِذَا بَدَهَهُ أَمْرَانِ يَنْظُرُ أَيُّهُمَا أَقْرَبُ إِلَى الْهَوَى فَيُخَالِفُهُ. فَعَلَيْكُمْ بِهَذِهِ الْخَلَائِقِ فَالْزَمُوهَا وَتَنَافَسُوا فِيهَا، فَإِنْ لَمْ تَسْتَطِيعُوهَا فَاعْلَمُوا أَنَّ أَخْذَ الْقَلِيلِ خَيْرٌ مِنْ تَرْكِ الْكَثِيرِ.","ob":"Il ne relatait que ce qu'il avait fait ; si on l'oblige quelquefois à parler, on ne l'a jamais obligé à se taire. Il préférait écouter que parler. Si deux options lui sont proposées à l'improviste, il rejette celle qui prête le plus à la passion. Qu'il soit pour vous un exemple à imiter. Si vous n'y arrivez pas, sachez que peu mieux vaut que rien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m290":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَوْ لَمْ يَتَوَعَّدِ اللّٰهُ عَلَى معصِيَته لَكَانَ يَجِبُ ألاّ يُعْصَى شُكْراً لِنِعَمِهِ.","ob":"Si Dieu n'avait pas promis le châtiment pour celui qui Lui désobéit, il aurait fallu qu'Il ne soit pas désobéi pour Le remercier de Ses grâces.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m291":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قال معزّياً الْأَشْعَثَ بْنَ قَيْسٍ عَنِ ابْنٍ لَهُ: يَا أَشْعَثُ، إِنْ تَحْزَنْ عَلَى ابْنِكَ فَقَدِ اسْتَحَقَّتْ مِنْكَ ذَلِكَ الرَّحِمُ، وَإِنْ تَصْبِرْ فَفِي اللّٰهِ مِنْ كُلِّ مُصِيبَةٍ خَلَفٌ. يَا أَشْعَثُ، إِنْ صَبَرْتَ جَرَى عَلَيْكَ الْقَدَرُ وَأَنْتَ مَأْجُورٌ، وَإِنْ جَزِعْتَ جَرَى عَلَيْكَ الْقَدَرُ وَأَنْتَ مَأْزُورٌ. يَا أَشْعَثُ، ابْنُكَ سَرَّكَ وَهُوَ بَلاَءٌ وَفِتْنَةٌ، وَحَزَنَكَ وَهُوَ ثَوَابٌ وَرَحْمَةٌ.","ob":"(Il présente ses condoléances à al-Ash'ath pour la mort de son fils): ô al-Ash'ath, si tu es triste pour la mort de ton fils c'est à cause des liens utérins, mais si tu patientes Dieu donne après chaque malheur un successeur. O al-Ash'ath, la patience te fait supporter le destin en te rétribuant, mais l'affliction te met devant le destin en état de péché. O al-Ash'ath, ton fils t'a réjoui tout en étant une calamité et une sédition, et l'a attristé tout en étant une rétribution et une miséricorde.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m292":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قال عَلَى قَبْرِ رَسُولِ اللَّهِ صلى اللّٰه عليه وآله وسلّم سَاعَةَ دَفْنِهِ: إِنَّ الصَّبْرَ لَجَمِيلٌ إِلَّا عَنْكَ، وَإِنَّ الْجَزَعَ لَقَبِيحٌ إِلَّا عَلَيْكَ، وَإِنَّ الْمُصَابَ بِكَ لَجَلِيلٌ، وَإِنَّهُ قَبْلَكَ وَبَعْدَكَ لَجَلَلٌ.","ob":"(Phrase prononcée sur la tombe du Prophète lors de son enterrement): La patience est une belle manière d'agir et l'affliction est une mauvaise manière d'agir, sauf en ce qui te concerne. Notre malheur en te perdant est énorme, mais il est bénin avant et après toi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m293":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَصْحَبِ الْمَائِقَ فَإِنَّهُ يُزَيِّنُ لَكَ فِعْلَهُ، وَيَوَدُّ أَنْ تَكُونَ مِثْلَهُ.","ob":"Ne fréquente pas le sot: il te rend la sottise agréable pour que tu l'imites.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m294":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَدْ سُئِلَ عَنْ مَسَافَةِ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، فَقَالَ: مَسِيرَةُ يَوْمٍ لِلشَّمْسِ.","ob":"(On lui demande quelle est la distance entre le lever et le coucher du soleil, il répond): une traversée du soleil pendant un jour.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m295":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَصْدِقَاؤُكَ ثَلاَثَةٌ، وَأَعْدَاؤُكَ ثَلاَثَةٌ؛ فَأَصْدِقَاؤُكَ: صَدِيقُكَ، وَصَدِيقُ صَدِيقِكَ، وَعَدُوُّ عَدُوِّكَ. وَأَعْدَاؤكَ: عَدُوُّكَ، وَعَدُوُّ صَدِيقِكَ، وَصَدِيقُ عَدُوِّكَ","ob":"Tu as trois amis et trois ennemis. Tes amis sont: ton ami, l'ami de ton ami et l'ennemi de ton ennemi. Tes ennemis sont: ton ennemi, l'ennemi de ton ami et l'ami de ton ennemi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m296":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِرَجُلٍ رَآهُ يَسْعَى عَلَى عَدُوٍّ لَهُ، بِمَا فِيهِ إِضْرَارٌ بِنَفْسِهِ: إنَّمَا أَنْتَ كَالطَّاعِنِ نَفْسَهُ لِيَقْتُلَ رِدْفَهُ.","ob":"(Il dit à un homme qu'il vit acharné contre un ennemi, ce qui lui fut nuisible): Tu ressembles à quelqu'un qui se frappe avec une lance pour tuer celui qu'il prend en croupe.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m297":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَكْثَرَ الْعِبَرَ وأَقَلَّ الِاعْتِبَارَ!","ob":"Qu'elles sont nombreuses les leçons à tirer, et pourtant peu de gens en profitent!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m298":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَن بَالَغَ فِي الْخُصُومَةِ أَثِمَ، وَمَنْ قَصَّرَ فِيهَا ظُلِمَ، وَلَا يَسْتَطِيعُ أَنْ يَتَّقِيَ اللّٰهَ مَنْ خَاصَمَ.","ob":"Celui qui exagère dans l'inimitié pèche, celui qui la prend à la légère commet l'injustice et celui qui se querelle ne peut pas craindre Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m299":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَهَمَّنِي ذَنْبٌ أُمْهِلْتُ بَعْدَهُ حَتَّى أُصَلِّيَ رَكْعَتَيْنِ وَأسْأَلَ اللّٰهَ الْعَافِيَة.","ob":"Je ne me soucie pas d'un péché après lequel un délai me sera donné pour prier deux génuflexions et demander à Dieu le pardon.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m300":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَسُئِلَ عليه السلام: كَيْفَ يُحَاسِبُ اللَّهُ الْخَلْقَ عَلَى كَثْرَتِهِمْ؟ فَقَالَ: كَمَا يَرْزُقُهُمْ عَلَى كَثْرَتِهِمْ. فَقِيلَ: كَيْفَ يُحَاسِبُهُمْ وَلَا يَرَوْنَهُ؟ فَقَالَ عليه السلام: كَمَا يَرْزُقُهُمْ وَلَا يَرَوْنَهُ.","ob":"(On lui demande comment Dieu demande des comptes aux gens qui sont si nombreux; il répond): De la même manière par laquelle Il leur assure la nourriture. On lui demande alors comment Il les rétribue sans qu'ils Le voient. Il répond: De la même manière par laquelle Il leur pourvoit la nourriture sans qu'ils Le voient.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m301":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رَسُولُكَ تَرْجُمَانُ عَقْلِكَ، وَكِتَابُكَ أَبْلَغُ مَا يَنْطِقُ عَنْكَ!","ob":"Ton Messager est le traducteur de ta raison, et ton Livre est le plus éloquent parleur à ta place.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m303":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"النَّاسُ أَبْنَاءُ الدُّنْيَا، وَلاَ يُلاَمُ الرَّجُلُ عَلَى حُبِّ أُمِّهِ.","ob":"Les hommes sont les fils de la vie terrestre, et l'on ne peut pas blâmer un homme s'il aime sa mère.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m304":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ الْمِسْكِينَ رَسُولُ اللهِ، فَمَنْ مَنَعَهُ فَقَدْ مَنَعَ اللهَ، وَمَنْ أَعْطَاهُ فَقَدْ أَعْطَى الله.","ob":"Le pauvre est un messager de Dieu. Celui qui lui donne ou refuse de lui donner c'est à Dieu qu'il le fait.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m305":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا زَنَى غَيُورٌ قَطُّ.","ob":"Celui qui sert la cause de Dieu avec zèle ne fornique point.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m307":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَنَامُ الرَّجُلُ عَلَى الثُّكْلِ، وَلَا يَنَامُ عَلَى الْحَرَبِ.","ob":"L'homme se retient si l'on tue ses enfants, mais réagit violemment contre celui qui le prive de ses biens.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m308":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَوَدَّةُ الْآبَاءِ قَرَابَةٌ بَيْنَ الْأَبْنَاءِ، وَالْقَرَابَةُ إِلَى الْمَوَدَّةِ أَحْوَجُ مِنَ الْمَوَدَّةِ إِلَى الْقَرَابَةِ.","ob":"L'amour des parents se traduit par les liens de parenté entre les enfants. La consanguinité a besoin d'amour plus que celui-ci en a besoin.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m309":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اتَّقُوا ظُنُونَ الْمُؤْمِنِينَ، فَإِنَّ اللّٰهَ تَعَالَى جَعَلَ الْحَقَّ عَلَى أَلْسِنَتِهِمْ.","ob":"Evitez les soupçons des croyants, car Dieu déclare la vérité par leurs bouches.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m310":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا يَصْدُقُ إِيمَانُ عَبْدٍ حَتّى يَكُونَ بِمَا فِي يَدِ اللّٰهِ أَوْثَقَ بِمَا فِي يَدِهِ.","ob":"La foi d'un serviteur n'est véridique que s'il se remet entre les mains de Dieu plus qu'il ne se remet à lui-même.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m312":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ لِلْقُلُوبِ إِقْبَالًا وَإِدْبَاراً، فَإِذَا أَقْبَلَتْ فَاحْمِلُوهَا عَلَى النَّوَافِلِ، وَإذَا أَدْبَرَتْ فَاقْتَصِرُوا بِهَا عَلَى الْفَرَائِضِ.","ob":"Les cœurs passent par des moments de va et vient. Dans le premier cas, faites-les respecter les lois; dans le second, qu'ils se limitent à observer les surérogations.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m313":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"«وَفِي الْقرْآنِ نَبَأُ مَا قَبْلَكُمْ، وَخَبَرُ مَا بَعْدَكُمْ، وَحُكْمُ مَا بَيْنَكُمْ».","ob":"«On trouve dans le Coran les nouvelles de ceux qui vous ont devancés et de ceux qui viendront après vous, et on trouve aussi la façon d'après laquelle vous devez vous comporter».","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m314":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رُدُّوا الْحَجَرَ مِنْ حَيْثُ جَاءَ، فَإِنَّ الشَّرَّ لَا يَدْفَعُهُ إِلَّا الشَّرُّ.","ob":"La pierre lancée sur vous faites-la retourner à celui qui l'a lancée, car le mal ne peut être confronté que par le mal.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m315":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِكَاتِبِهِ عُبَيْدِ اللَّهِ بْنِ أَبِى رَافِعٍ: أَلِقْ دَوَاتَكَ، وَأَطِلْ جِلْفَةَ قَلَمِكَ، وَفَرِّجْ بَيْنَ السُّطُورِ، وَقَرْمِطْ بَيْنَ الْحُرُوفِ: فَإِنَّ ذَلِكَ أَجْدَرُ بِصَبَاحَةِ الْخَطِّ.","ob":"(Il dit à son scribe 'Ubaydallāh ibn Abī Rāfi'): Garnis ton encrier de coton, allonge l'entaille de ta plume, laisse une espace entre les lignes et fais rapprocher tes lettres: tout ceci rend la calligraphie plus belle.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m316":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَنا يَعْسُوبُ الْمُؤْمِنِينَ، وَالْمَالُ يَعْسُوبُ الْفُجَّارِ.","ob":"Les croyants me suivent comme les abeilles suivent leurs reines. Mais les libertins suivent de la même manière l'argent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m317":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لَهُ بَعْضُ الْيَهُودِ: مَا دَفَنْتُمْ نَبِيَّكُمْ حَتَّى اخْتَلَفْتُمْ فِيهِ! فَقَالَ: إِنَّمَا اخْتَلَفْنَا عَنْهُ لَا فِيهِ، وَلَكِنَّكُمْ مَا جَفَّتْ أَرْجُلُكُمْ مِنَ الْبَحْرِ حَتَّى قُلْتُمْ لِنَبِيِّكُمْ: «اجْعَل لَّنَا إِلَٰهًا كَمَا لَهُمْ آلِهَةٌ، قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ».","ob":"(Des juifs lui dirent: Vous venez justement d'enterrer votre Prophète et vous voilà en dispute les uns avec les autres! Il leur répondit): Nous nous sommes disputés pour des raisons qui nous concernent et qui n'ont aucun rapport avec lui. Mais vous, dès que vos pieds furent desséchés [après avoir traversé la mer] vous dîtes à votre prophète: «O Moïse, désigne-nous une divinité semblable à leurs dieux». il dit: «Vous êtes certes des gens ignorants» (Al-A'raf, 138).","obNotes":[],"an":"Des Juifs lui ont dit: «A peine avez-vous enterré votre Prophète, que la dissension s'est installée au milieu de vous». L'Imām leur dit: Nous disputons de son représentant et non de son Message. Alors que vous autres, à peine les pieds séchés de la traversée de la mer vous avez dit à votre Prophète en voyant un peuple attaché à ses idoles: «O Moïse! Fais-nous un Dieu semblable à leurs dieux». Il ajouta: «Vous êtes un peuple ignorant».","anIntro":"","anNotes":[],"diff":null}]},"m318":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقِيلَ لَهُ: بِأَيِّ شيءٍ غَلَبْتَ الْأَقْرَانَ؟ فَقَالَ: مَا لَقِيتُ رَجُلًا إِلَّا أَعَانَنِى عَلَى نَفْسِهِ.","ob":"(On lui dit: qu'est-ce qui t'a fait dominer sur tes pairs? Il répond): Je n'ai jamais rencontré une personne sans qu'il m'ait aidé à avoir le dessus sur lui.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m319":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِابْنِهِ مُحَمَّدِ بن الْحَنَفِيَّةِ: يَا بُنَيَّ، إِنِّى أَخَافُ عَلَيْكَ الْفَقْرَ، فَاسْتَعِذْ بِاللَّهِ مِنْهُ، فَإِنَّ الْفَقْرَ مَنْقَصَةٌ لِلدِّينِ، مَدْهَشَةٌ لِلْعَقْلِ، دَاعِيَةٌ لِلْمَقْتِ.","ob":"(Il dit à son fils Muḥammad ibn al-Ḥanafiyya): Mon fils! Je crains que vous seriez pauvre. Demande à Dieu qu'Il éloigne de toi la pauvreté qui entache la religion, étonne l'intelligence et conduit à la rancœur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m320":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِسَائِلٍ سَأَلَهُ عَنْ مُعْضِلَةٍ: سَلْ تَفَقُّهاً، وَلَا تَسْأَلْ تَعَنُّتاً، فَإِنَّ الْجَاهِلَ الْمُتَعَلِّمَ شَبِيهٌ بِالْعَالِمِ، وَإِنَّ الْعَالِمَ الْمُتَعَسِّفَ شَبِيهٌ بِالْجَاهِلِ الْمُتَعَنِّتِ.","ob":"(Il dit à un homme qui lui demande de trouver une solution à un paradoxe): Pose des questions pour apprendre et non des questions embarrassantes. Car l'ignorant qui apprend est semblable au savant, tandis que le savant qui parle sans discernement est semblable à l'ignorant qui pose des questions embarrassantes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m321":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِعَبْدِ اللَّهِ بْنِ الْعَبَّاسِ، وَقَدْ أَشَارَ عَلَيْهِ فِي شيء لَمْ يُوَافِقْ رَأْيَهُ: لَكَ أَنْ تُشِيرَ عَلَيَّ وأَرَى، فَإِنْ عَصَيْتُكَ فَأَطِعْنِي.","ob":"(Il dit à 'Abdallāh ibn al-'Abbās qui lui fit une observation impertinente): Il est de ton droit de me faire une observation que j'étudie, mais si je vous suis désobéissant obéis-moi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m323":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ وَقَدْ مَرَّ بِقَتْلَى الْخَوَارِجِ يَوْمَ النَّهْرَوَانِ: بُؤْساً لَكُمْ، لَقَدْ ضَرَّكُمْ مَنْ غَرَّكُمْ، فَقِيلَ لَهُ: مَنْ غَرَّهُمْ يَا أَمِيرَ الْمُؤْمِنِينَ؟ فَقَالَ: الشَّيْطَانُ الْمُضِلُّ، وَالْأَنْفُسُ الْأَمَّارَةُ بِالسُّوءِ، غَرَّتْهُمْ بِالْأَمَانِيِّ، وَفَسَحَتْ لَهُمْ بالمعاصي، وَوَعَدَتْهُمُ الْإِظْهَارَ، فَاقْتَحَمَتْ بِهِمُ النَّارَ.","ob":"(Il dit en passant au milieu des cadavres des Khawārij au combat de Nahrawān): Malheur à vous. Celui qui vous a séduit vous a nui. On lui dit: c'est qui, et de répondre: c'est Satan le séducteur et leurs âmes inclinées au mal. Celles-ci les a leurrés par de fausses espérances, leur a permis de commettre des désobéissances pour être bien vus et les a fourrés dans le feu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m324":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اتَّقُوا مَعَاصِيَ اللّٰهِ فِي الْخَلَوَاتِ، فَإِنَّ الشَّاهِدَ هُوَ الْحَاكِمُ.","ob":"Craignez de désobéir à Dieu dans les lieux retirés, car le témoin est Celui qui gouverne le monde.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m325":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لَمَّا بَلَغَهُ قَتْلُ مُحَمَّدِ بْنِ أَبِي بَكْرٍ: إِنَّ حُزْنَنَا عَلَيْهِ عَلَى قَدْرِ سُرُورِهِمْ بِهِ، إِلَّا أَنَّهُمْ نَقَصُوا بَغِيضاً، وَنَقَصْنَا حَبِيباً.","ob":"(Il dit lorsqu'on lui rapporte le meurtre de Muḥammad ibn Abī Bakr): Notre chagrin équivaut à leur joie, à la seule différence qu'ils eurent un ennemi haï de moins et nous eûmes un bien-aimé de moins.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m327":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا ظَفِرَ مَنْ ظَفِرَ الْإِثْمُ بِهِ، وَالْغَالِبُ بِالشَّرِّ مَغْلُوبٌ.","ob":"Celui qui est vaincu par l'iniquité ne triomphe point. Et celui qui vainc par le mal est vaincu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m328":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِنَّ اللّٰهَ سُبْحَانَهُ فَرَضَ فِي أَمْوَالِ الْأَغْنِيَاءِ أَقْوَاتَ الْفُقَرَاءِ: فَمَا جَاعَ فَقِيرٌ إِلَّا بِمَا مُتِّع بِهِ غَنِي، وَاللّٰهُ تَعَالَى سَائِلُهُمْ عَنْ ذلِكَ.","ob":"Dieu a imposé aux biens des riches le devoir de nourrir les pauvres: le pauvre ne souffre de la faim que parce que le riche jouit d'un bien qui lui est dû. Et Dieu en demandera des comptes.","obNotes":[],"an":"L'Imām dit aussi: Dieu a imposé la part du pauvre dans les biens du riche. Le pauvre ne connaît la faim que par suite du gaspillage des riches. Dieu demandera compte à ces derniers.","anIntro":"","anNotes":[],"diff":null}]},"m330":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَقَلُّ مَا يَلْزَمُكُمْ لله أَلَّا تَسْتَعِينُوا بِنِعَمِهِ عَلَى مَعَاصِيهِ.","ob":"La moindre des choses que vous devez à Dieu est de ne pas vous aider de ses grâces pour Lui désobéir.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m331":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ اللّٰهَ سُبْحَانَهُ جَعَلَ الطَّاعَةَ غَنِيمَةَ الْأَكْيَاسِ عِنْدَ تَفْرِيطِ الْعَجَزَةِ.","ob":"Dieu a fait de l'obéissance la bonne aubaine des sages face à la dissipation de ceux dont les passions dérèglent l'intelligence.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m332":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"السُّلْطَانُ وَزَعَةُ اللّٰهِ فِي أَرْضِهِ.","ob":"Le dirigeant est le gouverneur de Dieu, qui empêche les gens d'outrepasser la loi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m333":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْمُؤْمِنُ بِشْرُهُ فِى وَجْهِهِ، وَحُزْنُهُ فِى قَلْبِهِ، أَوْسَعُ شيءٍ صَدْراً، وَأَذَلُّ شيءٍ نَفْساً. يَكْرَهُ الرِّفْعَةَ، وَيَشْنَأُ السُّمْعَةَ. طَوِيلٌ غَمُّهُ، بَعِيدٌ هَمُّهُ، كَثِيرٌ صَمْتُهُ، مَشْغُولٌ وَقْتُهُ. شَكُورٌ صَبُورٌ، مَغْمُورٌ بِفِكْرَتِهِ، ضَنِينٌ بِخَلَّتِهِ، سَهْلُ الْخَلِيقَةِ، لَيِّنُ الْعَرِيكَةِ! نَفْسُهُ أَصْلَبُ مِنَ الصَّلْدِ، وَهُوَ أَذَلُّ مِنَ الْعَبْدِ.","ob":"Le visage du croyant réfléchit l'affabilité. Sa tristesse est bien gardée dans sa poitrine. Il est le plus accueillant et le plus humble. Il hait l'orgueil et déteste la réputation. Triste en permanence, toujours préoccupé, il garde longtemps le silence car il est toujours occupé. Il remercie, patiente et médite. Il est avare quand il s'agit d'assouvir ses propres besoins. D'un naturel simple, il est bienveillant et accueillant. Son âme a une trempe de fer et pourtant il est plus humble que l'esclave.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m334":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَوْ رَأَى الْعَبْدُ الْأَجَلَ ومصيره، لَأَبْغَضَ الْأَمَلَ وَغُرُورَهُ.","ob":"Si le serviteur voyait le trépas et le destin, il haïrait l'espoir et ses tromperies.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m335":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِكُلِّ امْرِئٍ فِى مَالِهِ شَرِيكَانِ: الْوَارِثُ وَالْحَوَادِثُ.","ob":"A chacun deux associés dans ses biens: l'héritier et les revirements du sort.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m336":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْمَسْؤُولُ حُرٌّ حَتَّى يَعِدَ.","ob":"Le responsable est libre jusqu'à ce qu'il promette.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m337":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الدَّاعِي بِلاَ عَمَلٍ كَالرَّامِي بِلاَ وَتَرٍ.","ob":"Celui qui crie vers Dieu sans actions est semblable à un archer démuni de corde.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m338":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعِلْمُ عِلْمَانِ: مَطْبُوعٌ وَمَسْمُوعٌ، وَلَا يَنْفَعُ الْمَسْمُوعُ إِذَا لَمْ يَكُنِ الْمَطْبُوعُ.","ob":"La science a deux formes: celle qui est ferme dans l'esprit et se manifeste dans les œuvres, et celle qui est transmise et retenue. La seconde forme n'est pas utile en l'absence de la première.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m339":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"صَوَابُ الرَّأْيِ بِالدُّوَلِ: يُقْبِلُ بِإِقْبَالِهَا، وَيَذْهَبُ بِذَهَابِهَا.","ob":"La justesse de l'opinion est fonction des Etats: elle prospère quand ceux-ci prospèrent et s'anéantit lorsqu'ils cessent d'exister.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m340":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعَفَافُ زِينَةُ الْفَقْرِ، والشُّكْرُ زِينَةُ الغِنَى.","ob":"La chasteté est la parure de la pauvreté, et le remerciement est la parure de la richesse.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m341":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَوْمُ الْعَدْلِ عَلَى الظَّالِمِ أَشَدُّ مِنْ يَومِ الْجَوْرِ عَلَى الْمَظْلُومِ.","ob":"Le jour de la justice a un impact sur l'oppresseur beaucoup plus dur que celui de l'injustice sur l'opprimé.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m342":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْغِنَى الْأَكْبَرُ الْيَأْسُ عَمَّا فِي أَيْدِى النَّاسِ.","ob":"La plus grande richesse est de couper tout espoir d'acquérir ce que les gens possèdent.","obNotes":[],"an":"La grande richesse consiste à se détourner totalement des biens des autres.","anIntro":"","anNotes":[],"diff":null}]},"m343":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْأَقَاوِيلُ مَحْفُوظَةٌ، وَالسَّرَائِرُ مَبْلُوَّةٌ، وَ﴿كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ»، وَالنَّاسُ مَنْقُوصُونَ مَدْخُولُونَ إِلَّا مَنْ عَصَمَ اللَّهُ: سَائِلُهُمْ مُتَعَنِّتٌ، وَمُجِيبُهُمْ مُتَكَلِّفٌ، يَكَادُ أَفْضَلُهُمْ رَأْياً يَرُدُّهُ عَنْ فَضْلِ رَأْيِهِ الرِّضَى وَالسُّخْطُ، وَيَكَادُ أَصْلَبُهُمْ عُوداً تَنْكَؤُهُ اللَّحْظَةُ، وَتَسْتَحِيلُهُ الْكَلِمَةُ الْوَاحِدَةُ.","ob":"Les paroles sont conservées, les intentions éprouvées et «toute âme est l'otage de ce qu'elle a acquis» (74,38). Les hommes sont déraisonnables et psychopathes, sauf ceux que Dieu a gardés sains. Celui qui demande suscite l'embarras et celui qui répond dissimule la vérité. Celui qui a la meilleure opinion est presque enclin à la perdre à cause du bon plaisir et de l'emportement. Et celui qui s'attache le plus à sa religion peu lui faut pour être blessé par le regard appétissant et transformé par la seule parole.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m344":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَعَاشِرَ النَّاسِ، اتَّقُوا اللَّهَ، فَكَمْ مِنْ مُؤَمِّلٍ مَا لَا يَبْلُغُهُ، وَبَانٍ مَا لَا يَسْكُنُهُ، وَجَامِعٍ مَا سَوْفَ يَتْرُكُهُ، وَلَعَلَّهُ مِنْ بَاطِلٍ جَمَعَهُ، وَمِنْ حَقٍّ مَنَعَهُ، أَصَابَهُ حَرَاماً، وَاحْتَمَلَ بِهِ آثَاماً، فَبَاءَ بِوِزْرِهِ، وَقَدِمَ عَلَى رَبِّهِ، آسِفاً لَاهِفاً، قَدْ «خَسِرَ الدُّنْيَا وَالْآخِرَةَ، ذَٰلِكَ هُوَ الْخُسْرَانُ الْمُبِينُ».","ob":"O vous les gens, craignez Dieu! Nombreux sont ceux qui n'atteignent pas ce qu'ils espèrent avoir, qui n'habitent pas ce qu'ils ont bâti et qui délaissent ce qu'ils ont empilé. Leurs acquisitions sont peut-être le fruit de l'injustice ou proviennent d'un droit lésé par eux injustement. Ce faisant, ils commettent des péchés, mais reconnaissent leurs fautes et reviennent à leur seigneur avec regret, «perdant ainsi (le bien) de l'ici-bas et de l'au-delà. Telle est la perte évidente!» (22,11).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m345":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مِنَ الْعِصْمَةِ تَعَذُّرُ الْمَعَاصِي.","ob":"L'infaillibilité exclut la désobéissance à Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m346":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَاءُ وَجْهِكَ جَامِدٌ يُقْطِرُهُ السُّؤَالُ، فَانْظُرْ عِنْدَ مَنْ تُقْطِرُهُ.","ob":"L'eau de ton visage est de la glace que la requête fait fondre. Il s'agit de savoir à qui s'adresse cette requête.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m347":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الثَّنَاءُ بِأَكْثَرَ مِنَ الِاسْتِحْقَاقِ مَلَقٌ، وَالتَّقْصِيرُ عَنِ الِاسْتِحْقَاقِ عِيٌّ أَوْ حَسَدٌ.","ob":"La louange au-delà du mérite est une adulation, et l'abstention de louer celui qui le mérite dénote une impuissance de parole ou une jalousie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m348":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَشدُّ الذُّنُوبِ مَا اسْتَهَانَ بِهِ صَاحِبُهُ.","ob":"La plus grande des fautes est celle qui est dédaignée par le fautif.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m349":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ نَظَرَ فِي عَيْبِ نَفْسِهِ اشْتَغَلَ عَنْ عَيْبِ غَيْرهِ، وَمَنْ رَضِيَ برِزْقِ اللّٰهِ لَمْ يَحْزَنْ عَلَى مَا فَاتَهُ، وَمَنْ سَلَّ سَيْفَ الْبَغْيِ قُتِلَ بِهِ، وَمَنْ كَابَدَ الْأُمُورَ عَطِبَ، وَمَنِ اقْتَحَمَ اللُّجَجَ غَرِقَ، وَمَنْ دَخَلَ مَدَاخِلَ السُّوءِ اتُّهِمَ.","ob":"Celui qui s'occupe de ses propres défauts ne regarde pas les défauts d'autrui. Celui qui se contente des biens lui fournis par Dieu ne s'attriste pas à cause des occasions qui lui ont échappé. Celui qui tire l'épée de l'injustice par elle sera tué. Celui qui endure des difficultés s'épuise, qui s'engage dans les flots se noie et qui rôde autour des portes du mal est accusé.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"وَمَنْ كَثُرَ كَلاَمُهُ كَثُرَ خَطَؤُهُ، وَمَنْ كَثُرَ خَطَؤُهُ قَلَّ حَيَاؤُهُ، وَمَنْ قَلَّ حَيَاؤُهُ قَلَّ وَرَعُهُ، وَمَنْ قَلَّ وَرَعُهُ مَاتَ قَلْبُهُ، وَمَنْ مَاتَ قَلْبُهُ دَخَلَ النَّارَ. وَمَنْ نَظَرَ فِي عُيُوبِ النَّاسِ، فَأَنْكَرَهَا ثُمَّ رَضِيَهَا لِنَفْسِهِ، فذلك الْأَحْمَقُ بِعَيْنِهِ. وَالْقَنَاعَةُ مَالٌ لَا يَنْفَدُ. وَمَنْ أَكْثَرَ مِنْ ذِكْرِ الْمَوْتِ رَضِيَ مِنَ الدُّنْيَا بِالْيَسِيرِ....","ob":"Qui parle trop se trompe beaucoup, perd sa pudeur et sa piété; alors son cœur devient mort et, par conséquent, entre au Feu. Celui qui critique les défauts des autres tout en les acceptant pour lui-même est un sot sans doute. La tempérance est un trésor inépuisable. Celui qui se rappelle beaucoup la mort accepte le peu que lui donne la vie...","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m350":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِلظَّالِمِ مِنَ الرِّجَالِ ثَلاَثُ عَلاَمَاتٍ: يَظْلِمُ مَنْ فَوْقَهُ بِالْمَعْصِيَةِ، وَمَنْ دُونَهُ بِالْغَلَبَةِ، وَيُظَاهِرُ الْقَوْمَ الظَّلَمَةَ.","ob":"Trois signes caractérisent le despote: il commet l'injustice envers ses supérieurs par la désobéissance, envers ses subordonnés par le mauvais traitement et la contrainte, et envers les despotes du même acabit par l'hypocrisie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m351":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"عِنْدَ تَنَاهِي الشِّدَّةِ تَكُونُ الْفَرْجَةُ، وَعِنْدَ تَضَايُقِ حَلَقِ الْبَلاَءِ يَكُونُ الرَّخَاءُ.","ob":"Au comble du malheur succède le soulagement, et au maximum de l'épreuve succède le bien-être.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m352":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِبَعْضِ أَصْحَابِهِ: لَا تَجْعَلَنَّ أَكْثَرَ شُغُلِكَ بِأَهْلِكَ وَوَلَدِكَ: فَإِنْ يَكُنْ أَهْلُكَ وَوَلَدُكَ أَوْلِيَاءَ اللهِ، فَإِنَّ اللّٰهَ لَا يُضِيعُ أَوْلِيَاءَهُ، وَإِنْ يَكُونُوا أَعْدَاءَ اللهِ، فَمَا هَمُّكَ وَشُغُلُكَ بأَعْدَاءِ اللّٰهِ؟!","ob":"(Il dit à quelques compagnons): Ne concentrez pas la plupart de vos œuvres sur vos parents et enfants: si ceux-ci sont des amis de Dieu, Dieu ne laissera pas ses amis; et s'ils sont des ennemis de Dieu, qu'avez-vous à vous préoccuper des ennemis de Dieu?","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m353":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَكْبَرُ الْعَيْبِ أَنْ تَعِيبَ مَا فِيكَ مِثْلُهُ.","ob":"Le plus grand défaut est de dénigrer ceux qui ont le même défaut que toi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m354":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَهَنَّأَ بِحَضْرَتِهِ رَجُلًا بِغُلَامٍ وُلِدَ لَهُ فَقَالَ لَهُ لِيَهْنِئْكَ الْفَارسُ؛ فقال: لَا تَقُلْ ذلِكَ، وَلكِنْ قُلْ: شَكَرْتَ الْوَاهِبَ، وَبُورِكَ لَكَ فِي الْمَوْهُوبِ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ.","ob":"(Un homme félicite un autre en sa présence: Grand bien vous fasse à cause du fils que tu viens d'avoir. Alors 'Alī dit): Ne dis pas cela, mais dis: tu as remercié le Donneur, béni soit l'enfant donné par Dieu, qu'il devienne adulte et juste pour ton grand bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m356":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقِيلَ لَهُ: لَوْ سُدَّ عَلَى رَجُلٍ بَابُ بَيْتِهِ، وَتُرِكَ فِيهِ، مِنْ أَيْنَ كَانَ يَأْتِيهِ رِزْقُهُ؟ فَقَالَ: مِنْ حَيْثُ يَأْتِيهِ أَجَلُهُ.","ob":"(On lui dit: si l'on enferme un homme à l'intérieur de sa maison, d'où lui vient sa nourriture? Il répond): Elle lui vient d'où lui vient sa mort.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m357":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَعَزَّى قَوْماً عَنْ مَيِّتٍ مَاتَ لَهُمْ فَقَالَ: هذَا الْأَمْرَ لَيْسَ لَكُمْ بَدَأَ، وَلَا إِلَيْكُمُ انْتَهَى، وَقَدْ كَانَ صَاحِبُكُمْ هذَا يُسَافِرُ، فَعُدُّوهُ فِي بَعْضِ أَسْفَارِهِ، فَإِنْ قَدِمَ عَلَيْكُمْ وَإِلَّا قَدِمْتُمْ عَلَيْهِ.","ob":"(Il présenta les condoléances à des gens dont l'un des leurs est décédé, en disant): Ce n'est pas avec vous que cette affaire a commencé et elle ne finira pas avec vous. Votre défunt faisait des voyages. Considérez qu'il effectue maintenant un de ces voyages. S'il ne retourne pas chez vous vous retournerez chez lui.","obNotes":[],"an":"Faisant ses condoléances aux parents d'un décédé l'Imām dit: Ce fait n'a commencé ni ne s'achèvera avec vous. Votre ami ne voyageait-il pas? Considérez-le comme tel, s'il ne vous revient pas vous irez à lui.","anIntro":"","anNotes":[],"diff":null}]},"m358":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَيُّهَا النَّاسُ، لِيَرَكُمُ اللَّهُ مِنَ النِّعْمَةِ وَجِلِينَ، كَمَا يَرَاكُمْ مِنَ النِّقْمَةِ فَرِقِينَ! إِنَّهُ مَنْ وُسِّعَ عَلَيْهِ فِى ذَاتِ يَدِهِ فَلَمْ يَرَ ذَلِكَ اسْتِدْرَاجاً فَقَدْ أَمِنَ مَخُوفاً، وَمَنْ ضُيِّقَ عَلَيْهِ فِى ذَاتِ يَدِهِ فَلَمْ يَرَ ذَلِكَ اخْتِبَاراً فَقَدْ ضَيَّعَ مَأْمُولًا.","ob":"O gens, que Dieu vous voie effrayés et devant les faveurs et devant les disgrâces! Celui à qui ont été donnés en abondance des faveurs non par tromperie est assuré contre la peur, et celui qui ne considère pas que la perte de ses biens est une épreuve de Dieu perd le salut espéré.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m359":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَا أَسْرَى الرَّغْبَةِ أَقْصِرُوا، فَإِنَّ الْمُعَرِّجَ عَلَى الدُّنْيَا لَا يَرُوعُهُ مِنْهَا إِلَّا صَرِيفُ أَنْيَابِ الْحِدْثَانِ. أَيُّهَا النَّاسُ، تَوَلَّوْا مِنْ أَنْفُسِكُمْ تَأْدِيبَهَا، وَاعْدِلُوا بِهَا عَنْ ضَرَاوَةِ عَادَاتِهَا.","ob":"O prisonnier de l'avidité, cessez de l'être, car celui qui compte sur la vie terrestre n'a peur que de ses vicissitudes qui le déchirent par leurs dents. O gens, ayez vous-mêmes le soin de former vos âmes et de les détourner de leurs habitudes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m360":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَظُنَّنَّ بِكَلِمَةٍ خَرَجَتْ مِنْ أَحَدٍ سُوءاً، وَأَنْتَ تَجِدُ لَهَا فِي الْخَيْرِ مُحْتَمَلاً.","ob":"Ne pensez pas mal d'une parole proférée par quelqu'un tant que tu trouves qu'elle renferme probablement du bien.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m361":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِذَا كَانَتْ لَكَ إِلَى اللّٰهِ سُبْحَانَهُ حَاجَةٌ فَابْدَأْ بِمَسْأَلَةِ الصَّلاَةِ عَلَى رَسُولِهِ، صلى اللّٰه عليه وآله وسلّم، ثُمَّ سَلْ حَاجَتَكَ؛ فَإِنَّ اللّٰهَ أَكْرَمُ مِنْ أَنْ يُسْأَلَ حَاجَتَيْنِ، فَيَقْضِيَ إِحْدَاهُمَا وَيَمْنَعَ الْأُخْرَى.","ob":"Si tu as un besoin quelconque ne l'expose pas à Dieu avant de prier sur son Prophète, car Dieu est plus généreux que de satisfaire une demande et de laisser l'autre.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m362":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ ضَنَّ بِعِرْضِهِ فَلْيَدَعِ الْمِرَاءَ.","ob":"Celui qui tient à son honneur doit éviter la discussion non basée sur la vérité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m363":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مِنَ الْخُرْقِ الْمُعَاجَلَةُ قَبْلَ الْإِمْكَانِ، وَالْأَنَاةُ بَعْدَ الْفُرْصَةِ.","ob":"C'est une sottise que de se hâter avant qu'une action soit possible et de s'attarder après le moment propice.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m364":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَسْأَلْ عَمَّا لَا يَكُونُ، فَفِي الَّذِي قَدْ كَانَ لَكَ شُغُلٌ.","ob":"Ne t'occupe pas de ce qui n'est pas actuel, car tes occupations actuelles te suffisent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m365":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْفِكْرُ مرْآةٌ صَافِيَةٌ، وَالِاعْتِبَارُ مُنْذِرٌ نَاصِحٌ. وَكَفَى أَدَباً لِنَفْسِكَ تَجَنُّبُكَ مَا كَرِهْتَهُ لِغَيْرِكَ.","ob":"La pensée est un miroir clair. Ecouter les avis et en profiter est un avertissement qui donne conseil. Tu seras assez poli si tu évites ce que tu ne veux pas pour autrui.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m366":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْعِلْمُ مَقْرُونٌ بِالْعَمَلِ: فَمَنْ عَلِمَ عَمِلَ؛ وَالْعِلْمُ يَهْتِفُ بِالْعَمَلِ، فَإِنْ أَجَابَهُ وَإِلَّاَ ارْتَحَلَ عَنْهُ.","ob":"Savoir et faire sont en connexion: Celui qui sait agit. De plus, la science appelle l'action; si celle-ci ne réplique pas, la science s'en va.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m367":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَا أيُّها النَّاسُ، مَتَاعُ الدُّنْيَا حُطَامٌ مُوبِئٌ فَتَجَنَّبُوا مَرْعَاهُ! قُلْعَتُهَا أَحْظَى مِنْ طُمَأْنِينَتِهَا، وَبُلْغَتُهَا أَزْكَى مِنْ ثَرْوَتِهَا. حُكِمَ عَلَى مُكْثِرٍ مِنْهَا بِالْفَاقَةِ، وَأُعِينَ مَنْ غَنِيَ عَنْهَا بِالرَّاحَة.","ob":"O gens, les biens de ce monde ne sont que des broussailles ravagées par l'épidémie; évitez de les paître! Les délaisser vaut mieux que s'y adonner. Ce qui te suffit pour vivre l'emporte sur les richesses. Celui qui exagère dans l'utilisation des biens de ce monde sera condamné au dénuement; et celui qui s'en passe sera aidé par la tranquillité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"مَنْ رَاقَهُ زِبْرِجُهَا أَعْقَبَتْ نَاظِرَيْهِ كَمَهاً، وَمَنِ اسْتَشْعَرَ الشَّغَفَ بِهَا مَلَأَتْ ضَمِيرَهُ أَشْجاناً، لَهُنَّ رَقْصٌ عَلى سُوَيْدَاءِ قَلْبِهِ: هَمٌّ يَشْغَلُهُ، وَغَمٌّ يَحْزُنُهُ. وَإِنَّمَا يَنْظُرُ الْمُؤْمِنُ إِلَى الدُّنْيَا بِعَيْنِ الِاعْتِبَارِ، وَيَقْتاتُ مِنْهَا بِبَطْنِ الِاضْطِرَارِ.","ob":"Celui qui se plaît à leurs parures aura la cécité dans les yeux, et celui qui s'en est épris d'un amour passionné aura la conscience pleine de tristesse et le cœur plein de chagrin... En outre, le croyant tire des leçons des vicissitudes de la vie de laquelle il ne profite que dans la limite du nécessaire.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m368":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ اللّٰهَ سُبْحَانَهُ وَضَعَ الثَّوَابَ عَلَى طَاعَتِهِ، وَالْعِقَابَ عَلَى مَعْصِيَتِهِ، ذِيَادَةً لِعِبَادِهِ عَنْ نِقْمَتِهِ، وَحِيَاشَةً لَهُمْ إلَى جَنَّتِهِ.","ob":"Dieu associe la récompense à Son obéissance et le châtiment à Sa désobéissance, et ce pour protéger ses serviteurs de Sa colère et les conduire vers Son paradis.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m369":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَأْتِي عَلَى النَّاسِ زَمَانٌ لَا يَبْقى فِيهِمْ مِن الْقُرآنِ إِلَّا رَسْمُهُ، وَمِنَ الْإِسْلَامِ إِلَّا اسْمُهُ، وَمَسَاجِدُهُمْ يَوْمَئِذٍ عَامِرَةٌ مِنَ الْبِنَاءِ، خَرَابٌ مِنَ الْهُدَى، سُكَّانُهَا وَعُمَّارُهَا شَرُّ أَهْلِ الْأَرْضِ، مِنْهُمْ تَخْرُجُ الْفِتْنَةُ، وَإِلَيْهِمْ تَأوِي الْخَطِيئَةُ؛ يَرُدُّونَ مَنْ شَذَّ عَنْهَا فِيهَا، وَيَسُوقوُنَ مَن تأَخَّرَ عَنْهَا إِلَيْهَا. يَقُولُ اللّٰهُ سُبْحَانَهُ: فَبِي حَلَفْتُ لَأَبْعَثَنَّ عَلَى أُولئِكَ فِتْنَةً تتْرُك الْحَلِيمَ فِيهَا حَيْرَانَ، وَقَدْ فَعَلَ، وَنَحْنُ نَسْتَقِيلُ اللّٰهَ عَثْرَةَ الْغَفْلَةِ.","ob":"Les gens vivront en un temps où il ne reste du Coran que son image et de l'Islam que son nom. Leurs mosquées seront alors bien construites mais vides de guidance. Les habitants qui les ont construites sont les plus mauvais de la terre. D'eux sort la sédition et chez eux le péché trouve son abri. Ils font revenir à la vie de péché celui qui, par exception, s'en écarte et conduisent vers le mal celui qui s'attarde à le faire. Dieu dit: J'ai juré par mon nom de leur envoyer une sédition qui laisserait le doux parmi eux perplexe. Et Il l'a fait. Nous implorons Dieu de ne pas nous soumettre à la mort subite.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m370":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَرُوِيَ أَنَّهُ عليه السلام قَلَّمَا اعْتَدَلَ بِهِ الْمِنْبَرُ إِلَّا قَالَ أَمَامَ الْخُطْبَةِ: أَيُّهَا النَّاسُ اتَّقُوا اللهَ، فَمَا خُلِقَ امْرُؤٌ عَبَثاً فَيَلْهُوَ، وَلَا تُرِكَ سُدىً فَيَلْغُوَ! وَمَا دُنْيَاهُ الَّتي تَحَسَّنَتْ لَهُ بِخَلَفٍ مِنَ الْآخِرَةِ الَّتي قَبَّحَها سُوءُ النَّظَرِ عِنْدَهُ، وَمَا الْمَغْرُورُ الَّذِي ظَفِرَ مِنَ الدُّنْيَا بأَعْلَى هِمَّتِهِ كَالْآخَرِ الَّذِي ظَفِرَ مِنَ الْآخِرَةِ بِأَدْنَى سُهْمَتِهِ.","ob":"(On raconte que la plupart des fois qu'il montait sur la chaire il disait devant le public): O gens, craignez Dieu, l'homme n'a pas été créé en vain pour s'amuser, ni laissé sans obligation à observer pour faire des choses inutiles! Sa vie terrestre s'est améliorée à cause du retard de l'autre vie que sa courte vision des choses a rendue laide. L'égaré qui vit dans l'illusion et qui eut la chance de profiter au maximum de sa vie n'égalise pas celui dont le minimum de sort lui fait gagner l'autre monde.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m371":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"لَا شَرَفَ أَعْلَى مِنَ الْإِسْلَامِ، وَلَا عِزَّ أَعَزُّ مِنَ التَّقْوَى، وَلَا مَعْقِلَ أَحْسَنُ مِنَ الْوَرَعِ، وَلَا شَفِيعَ أَنْجَحُ مِنَ التّوْبَةِ، وَلَا كَنْزَ أَغْنَى مِنَ الْقَنَاعَةِ، وَلَا مَالَ أَذْهَبُ لِلْفَاقَةِ مَنَ الرِّضَى بِالْقُوتِ. وَمَنِ اقْتَصَرَ عَلَى بُلْغَةِ الْكَفَافِ فَقَدِ انْتَظَمَ الرَّاحَةَ، وَتَبَوَّأَ خَفْضَ الدَّعَةِ. وَالرَّغْبَةُ مِفْتَاحُ النَّصَبِ، وَمَطِيَّةُ التَّعَبِ، وَالْحِرْصُ وَالْكِبْرُ وَالْحَسَدُ دَوَاعٍ إِلَى التَّقَحُّمِ فِي الذُّنُوبِ، وَالشَّرُّ جَامِعُ مَسَاوِئِ الْعُيُوبِ.","ob":"Il n'y a pas d'honneur plus élevé que celui de l'Islam par la piété. Aucun refuge n'est meilleur que la crainte de Dieu. Aucun intercesseur n'est plus efficace que le repentir. Aucun trésor n'est plus riche que la tempérance. Aucun argent n'est plus capable de chasser la misère que la frugalité. Celui qui se contente de son pain quotidien connaît la tranquillité et vit dans la demeure de l'opulence. La cupidité est la clef de la peine et la monture de la fatigue. L'avarice, l'orgueil et la jalousie fournissent les occasions de commettre les péchés. Le mal est le lieu commun des méfaits des vices.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m372":{"title":"","an":true,"items":[{"t":"c","nums":[1,2],"ar":"وَقَالَ عليه السلام لِجَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ: يَا جَابِرُ، قِوَامُ الدِّينِ وَالدُّنْيَا بِأَرْبَعَةٍ: عَالِمٍ مُسْتَعْمِلٍ عِلْمَهُ، وَجَاهِلٍ لَا يَسْتَنْكِفُ أَنْ يَتَعَلَّمَ، وَجَوَادٍ لَا يَبْخَلُ بِمَعْرُوفِهِ، وَفَقِيرٍ لَا يَبِيعُ آخِرَتَهُ بِدُنْيَاهُ؛ فَإِذَا ضَيَّعَ الْعَالِمُ عِلْمَهُ اسْتَنْكَفَ الْجَاهِلُ أَنْ يَتَعَلَّمَ، وَإِذَا بَخِلَ الْغَنِيُّ بِمَعْرُوفِهِ بَاعَ الْفَقِيرُ آخِرَتَهُ بِدُنْيَاهُ. يَا جَابِرُ، مَنْ كَثُرَتْ نِعَمُ اَللَّهِ عَلَيْهِ كَثُرَتْ حَوَائِجُ اَلنَّاسِ إِلَيْهِ، فَمَنْ قَامَ لِلَّهِ فِيهَا بِمَا يَجِبُ فِيهَا عَرَّضَهَا لِلدَّوَامِ وَالْبَقَاءِ، وَمَنْ لَمْ يَقُمْ فِيهَا بِمَا يَجِبُ عَرَّضَهَا لِلزَّوَالِ وَالْفَنَاءِ.","ob":"(Il dit à Jābir al-Anṣārī): O Jābir, la constitution de la religion et du monde repose sur quatre: un savant qui utilise sa science, un ignorant qui ne dédaigne pas d'apprendre, un généreux qui dépense largement pour ce qui est convenable et un pauvre qui ne vend pas l'autre monde pour celui-ci. Si le savant perdait sa science, l'ignorant dédaignerait d'apprendre; et si le généreux devenait avare, le pauvre vendrait l'autre monde pour la vie terrestre.\nO Jābir, celui qui est comblé des grâces de Dieu attire nombreux les hommes qui ont besoin de lui. S'il gère ses biens d'après la volonté de Dieu, il les pérennise, sinon il les expose à l'anéantissement.","obNotes":[],"an":"A Jābir ibn 'Abdallāh al-Anṣārī l'Imām dit: O Jābir! Quatre hommes font prospérer la religion et la vie en ce monde: un savant se servant de sa science, un ignorant qui ne dédaigne pas d'apprendre, un généreux qui ne refuse pas de donner et un pauvre qui ne troque pas l'éternité contre ce monde. Si le savant perd sa science, l'ignorant renoncera à apprendre, si le riche retient ses dons, le pauvre troquera l'éternité contre ce monde. O Jābir! Celui à qui Dieu accorde ses faveurs avec abondance sera trop sollicité par les gens. Or celui qui s'acquitte de ses devoirs grâce à ces faveurs les prépare à durer et à se perpétuer alors que celui qui les néglige s'expose à les perdre définitivement.","anIntro":"","anNotes":[],"diff":null}]},"m373":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَيُّهَا الْمُؤْمِنُونَ، إِنَّهُ مَنْ رَأَى عُدْوَاناً يُعْمَلُ بِهِ وَمُنْكَراً يُدْعَى إِلَيْهِ، فَأَنْكَرَهُ بِقَلْبِهِ فَقَدْ سَلِمَ وَبَرِئَ؛ وَمَنْ أَنْكَرَهُ بِلِسَانِهِ فَقَدْ أُجِرَ، وَهُوَ أَفْضَلُ مِنْ صَاحِبِهِ؛ وَمَنْ أَنْكَرَهُ بِالسَّيْفِ لِتَكُونَ كَلِمَةُ اللّٰهِ هِيَ الْعُلْيَا وَكَلِمَةُ الظَّالِمِينَ هِيَ السُّفْلَى، فَذلِكَ الَّذِي أَصَابَ سَبيلَ الْهُدَى، وَقَامَ عَلَى الطَّريق، وَنَوَّرَ فِي قَلْبِهِ الْيَقِينُ.","ob":"O croyants, celui qui voit une injustice en train d'être commise ou un acte répréhensible auquel il est invité, s'il les interdit en son cœur il sera exempt de l'iniquité; s'il les interdit par sa langue il sera récompensé et considéré meilleur que son devancier: s'il les interdit par l'épée pour que la parole de Dieu soit la plus élevée et celle des injustes la plus basse, il sera celui qui a trouvé le vrai chemin de la guidance et l'a suivi, et sera celui dont le cœur est illuminé par la vraie foi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m374":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فَمِنْهُمُ الْمُنْكِرُ للْمُنْكَرِ بيَدِهِ وَلِسَانِهِ وَقَلْبِهِ، فَذَلِكَ الْمُسْتَكْمِلُ لِخِصَالِ الْخَيْرِ؛ وَمِنْهُمُ الْمُنْكِرُ بِلِسَانِهِ وَقَلْبهِ وَالتَّارِكُ بِيَدِهِ، فَذلِكَ مُتَمَسِّكٌ بِخَصْلَتَيْنِ مِنْ خِصَالِ الْخَيْرِ وَمُضَيِّعٌ خَصْلَةً؛ وَمِنْهُمُ الْمُنْكِرُ بِقَلْبِهِ، وَالتَّارِكُ بيَدِهِ وَلِسَانِهِ، فَذلِكَ الَّذِي ضَيَّعَ أَشْرَفَ الْخَصْلَتَيْنِ مِنَ الثَّلاَثِ، وَتَمَسَّكَ بوَاحِدَةٍ.","ob":"Parmi les croyants on trouve ceux qui interdisent le blâmable par leurs mains, leurs langues et leurs cœurs; ceux-ci accomplissent toutes les propriétés du bien. Ceux qui interdisent le blâmable par leurs langues et leurs cœurs –sans leurs mains– s'attachent à deux propriétés du bien et laissent tomber une propriété. Ceux qui l'interdisent par leurs cœurs seulement laissent se perdre les deux propriétés les plus nobles.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"وَمِنْهُمْ تَارِكٌ لِإِنْكَارِ الْمُنْكَرِ بِلِسَانِهِ وَقَلْبِهِ وَيَدِهِ، فَذلِكَ مَيِّتُ الْأَحْيَاءِ. وَمَا أَعْمَالُ الْبِرِّ كُلُّهَا وَالْجِهَادُ فِي سَبِيلِ اللهِ، عِنْدَ الْأَمْرِ بالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، إِلَّا كَنَفْثَةٍ فِي بَحْرٍ لُجِّيٍّ. وَأَفضَلُ مِنْ ذلِكَ كُلِّهِ كَلِمَةُ عَدْلٍ عِنْدَ إِمَامٍ جَائِرٍ.","ob":"Ceux qui n'utilisent ni leurs langues, ni leurs cœurs, ni leurs mains pour interdire ce qui est blâmable sont les morts parmi les vivants. Car toutes les actions de justice, y compris le <i>jihād</i>, ne sont qu'un crachat dans une mer immense par rapport au commandement du convenable et l'interdiction du blâmable. Ce qui est meilleur que tout cela, c'est de prononcer un mot de justice devant un imam injuste.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m375":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَعَنْ أَبِي جُحَيْفَةَ قَالَ: سَمِعْتُ أَمِيرَ الْمُؤْمِنِينَ عليه السلام يَقُولُ: أَوَّلُ مَا تُغْلَبُونَ عَلَيْهِ مِنَ الْجِهَادِ بِأَيْدِيكُمْ، ثُمَّ بِأَلْسِنَتِكُمْ، ثُمَّ بِقُلُوبِكُمْ؛ فَمَنْ لَمْ يَعْرِفْ بِقَلْبِهِ مَعْرُوفاً، وَلَمْ يُنْكِرْ مُنْكَراً، قُلِبَ فَجُعِلَ أَعْلاَهُ أَسْفَلَهُ، وَأَسْفَلُهُ أَعْلاَهُ.","ob":"(Abū Juḥayfa rapporte qu'il avait entendu le Prince des Croyants dire): Le <i>jihād</i> qui a le plus grand impact sur vous est celui que vous faites par vos mains, puis par vos langues et finalement par vos cœurs. Celui qui n'a connu dans son cœur un acte convenable, ni interdit un acte blâmable, ressemble à celui qui est mis à l'envers, sa tête en bas, et ses pieds en haut.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m376":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ الْحَقَّ ثَقِيلٌ مَرِيءٌ، وَإِنَّ الْبَاطِلَ خَفِيفٌ وَبِيءٌ.","ob":"La vérité est difficile à dire mais elle a une heureuse issue. Le mensonge est facile à dire mais il a une mauvaise issue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m377":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَأْمَنَنَّ عَلَى خَيْرِ هذِهِ الْأُمَّةِ عَذَابَ اللهِ، لِقَوْلِهِ تَعَالى: «فَلَا يَأْمَنُ مَكْرَ اللّٰهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ» وَلَا تَيْأَسَنَّ لِشَرِّ هَذِهِ الْأُمَّةِ مِنْ رَوْحِ اَللَّهِ لِقَوْلِهِ تَعَالَى: «إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللّٰهِ إِلَّا الْقَوْمُ الْكَافِرُونَ».","ob":"Les meilleurs de cette nation ne sont pas à l'abri du châtiment de Dieu qui dit: «Seuls les gens perdus se sentent à l'abri du stratagème d'Allah» (7,99). Les plus mauvais de cette nation ne désespèrent pas de la miséricorde de Dieu qui dit: «Ce sont seulement les gens mécréants qui désespèrent de la Miséricorde d'Allah» (12,87).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m378":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْبُخْلُ جَامِعٌ لِمَسَاوِئِ الْعُيُوبِ، وَهُوَ زِمَامٌ يُقَادُ بِهِ إِلَى كُلِّ سُوءٍ.","ob":"L'avarice renferme tous les torts des actions mauvaises, elle est la rêne qui se fait diriger vers tous les maux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m379":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يابْن آدَمَ، الرِّزْقُ رِزْقَانِ: رِزْقٌ تَطْلُبُهُ، وَرِزْقٌ يَطْلُبُكَ، فَإِنْ لَمْ تَأْتِهِ أَتَاكَ. فَلاَ تَحْمِلْ هَمَّ سَنَتِكَ عَلَى هَمِّ يَوْمِكَ! كَفَاكَ كُلُّ يَوْمٍ عَلَى مَا فيِهِ؛ فَإِنْ تَكُنِ السَّنَةُ مِنْ عُمُرِكَ فَإنَّ اللّٰهَ تَعَالَى سَيُؤْتِيكَ فِي كُلِّ غَدِ جَدِيدٍ مَا قَسَمَ لَكَ؛ وَإِنْ لَمْ تَكُنِ السَّنَةُ مِنْ عُمُرِكَ فَمَا تَصْنَعُ بِالْهَمِّ فيما لَيْسَ لَكَ؛ وَلَنْ يَسْبِقَكَ إِلَى رِزْقِكَ طَالِبٌ، وَلَنْ يَغْلِبَكَ عَلَيْهِ غَالِبٌ، وَلَنْ يُبْطِئَ عَنْكَ مَا قَدْ قُدِّرَ لَكَ.","ob":"O fils d'Adam, les moyens de vivre sont de deux sortes: ceux que tu demandes et ceux qui te demandent. Si tu n'arrives pas à avoir la première sorte, tu finiras par acquérir la deuxième. N'accumule pas les soucis de subvenir aux besoins d'une année sur ceux de ton jour! Les vivres de chaque jour te sont suffisants. Si Dieu voulait que tu vives une année, Il pourvoirait chaque lendemain à tes besoins. Dans le cas contraire, tu n'as pas à te soucier de ce qui ne t'appartient pas. Nul ne te devancera pour t'arracher ton pain quotidien. Ton destin ne tardera pas à s'accomplir.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m380":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رُبَّ مُسْتَقْبِلٍ يَوْماً لَيْسَ بِمُسْتَدْبِرِهِ، وَمَغْبُوطٍ فِي أَوَّلِ لَيْلِهِ، قَامَتْ بَوَاكِيهِ فِي آخِرِهِ.","ob":"Il arrive qu'un homme attende un lendemain, mais meurt à la veille, qu'il vive dans l'opulence au début de la soirée et voici que les pleureuses se lamentent sur lui à minuit.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m381":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْكَلاَمُ فِي وَثَاقِكَ مَا لَمْ تَتَكَلَّمْ بِهِ؛ فَإذَا تَكَلَّمْتَ بِهِ صِرْتَ فِي وَثَاقِهِ، فَاخْزُنْ لِسَانَكَ كَمَا تَخْزُنُ ذَهَبَكَ وَوَرِقَكَ، فَرُبَّ كَلِمَةٍ سَلَبَتْ نِعْمَةً وَجَلَبَتْ نِقْمَةً.","ob":"Tu es maître de tes paroles avant que tu les débites, mais une fois proférées elles te lient. Economise ta langue comme tu le fais avec ton or et ton argent, car il arrive qu'un mot arrache une grâce et apporte un malheur.","obNotes":[],"an":"Vous êtes maître de vos paroles tant que vous les retenez; mais une fois que vous les proférez vous en devenez l'esclave. Gardez votre langue comme vous tenez cachés votre or et votre argent. Il arrive qu'une parole prive d'une faveur et attire une disgrâce.","anIntro":"","anNotes":[],"diff":null}]},"m382":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَقُلْ مَا لَا تَعْلَمُ، بَلْ لَا تَقُلْ كُلَّ مَا تَعْلَمُ، فَإِنَّ اللّٰهَ فَرَضَ عَلَى جَوَارِحِكَ كُلِّهَا فَرَائِضَ يَحْتَجُّ بِهَا عَلَيْكَ يَوْمَ الْقِيَامَةِ.","ob":"Ne dis pas ce que tu ne connais pas, plutôt ne dis pas tout ce que tu connais, car Dieu a imposé à tous tes organes des devoirs dont tu rendras compte le jour du Jugement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m383":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"احْذَرْ أَنْ يَرَاكَ اللّٰهُ عِنْدَ مَعْصِيَتِهِ، وَيَفْقِدَكَ عِنْدَ طَاعَتِهِ، فَتَكُونَ مِنَ الْخَاسِرِينَ، وَإِذَا قَوِيتَ فَاقْوَ عَلَى طَاعَةِ اللهِ، وَإِذَا ضَعُفْتَ فاضْعُفْ عَنْ مَعْصِيَةِ اللهِ.","ob":"Prends garde que Dieu ne te voie dans ta désobéissance et se cache à toi dans ton obéissance, car tu seras parmi les perdants! Si tu deviens fort, fortifie-toi par l'obéissance de Dieu, et si tu deviens faible, sois-le dans ta désobéissance.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m384":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الرُّكُونُ إِلَى الدُّنْيَا مَعَ مَا تُعَايِنُ مِنْهَا جَهْلٌ، وَالتَّقْصِيرُ فِي حُسْنِ الْعَمَلِ إذَا وَثِقْتَ بِالثَّوَابِ عَلَيْهِ غَبْنٌ، وَالطُّمَأْنِينَةُ إِلَى كُلِّ أَحَدٍ قَبْلَ الِاخْتِبَارِ لَهُ عَجْزٌ.","ob":"Ta confiance en ce monde dont tu vois les revirements relève de l'ignorance. Ton retard à faire les bonnes actions dont tu es sûr qu'elles seront récompensées est une grande perte. Se fier à n'importe qui avant de l'éprouver dénote l'impuissance.","obNotes":[],"an":"Compter sur le monde malgré ce que vous en constatez est ignorance; agir médiocrement au service du bien, alors que la récompense est certaine, est une grave perte; faire confiance à quiconque avant de l'éprouver est faiblesse.","anIntro":"","anNotes":[],"diff":null}]},"m385":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مِنْ هَوَانِ الدُّنْيَا عَلَى اللّٰهِ أَنَّهُ لَا يُعْصَى إِلَّا فِيهَا، وَلَا يُنَالُ مَا عِنْدَهُ إِلَّا بِتَرْكِهَا.","ob":"La vilainie de ce monde terrestre se manifeste par le fait que Dieu y est désobéi et qu'on n'obtient Ses dons qu'en la laissant.","obNotes":[],"an":"Le monde est tellement insignifiant aux yeux de Dieu que c'est le seul endroit où il est désobéi. La grandeur de cet endroit réside en ce qu'on ne peut gagner les faveurs de Dieu qu'en renonçant aux biens terrestres.","anIntro":"","anNotes":[],"diff":null}]},"m386":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ طَلَبَ شَيْئاً نَالَهُ أَوْ بَعْضَهُ.","ob":"Celui qui réclame une chose l'obtient totalement ou partiellement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m387":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا خَيْرٌ بِخَيْرٍ بَعْدَهُ النَّارُ، وَمَا شَرٌّ بِشَرٍّ بَعْدَهُ الْجَنَّةُ، وَكُلُّ نَعِيمٍ دُونَ الْجَنَّةِ فَهُوَ مَحْقُورٌ، وَكُلُّ بَلاَءٍ دُونَ النَّارِ عَافِيَةٌ.","ob":"Un bien qui entraîne le Feu n'est pas un bien. Un mal suivi du Paradis n'est pas un mal. Tout bonheur en dehors du Paradis est méprisable et tout malheur en dehors du Feu est un bien-être.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m388":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَلَا وإِنَّ مِنَ الْبَلاَءِ الْفَاقَةَ، وَأَشَدُّ مِنَ الْفَاقَةِ مَرَضُ الْبَدَنِ، وَأشدُّ مِنْ مَرَضِ الْبَدَنِ مَرَضُ الْقَلْبِ. أَلَا وإِنَّ مِنَ صِحَّةِ الْبَدَنِ تَقْوَى الْقَلْبِ.","ob":"L'un des malheurs de la vie est la pauvreté. Pire que celle-ci est la maladie du corps qui est dépassé de loin par celle du cœur. D'ailleurs, la piété du cœur provient de la santé du corps.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m389":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"«مَنْ أَبْطَأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ». وَفِي رِوَايَةٍ أُخْرَى: مَنْ فَاتَهُ حَسَبُ نَفْسِهِ لَمْ يَنْفَعْهُ حَسَبُ آبَائِهِ.","ob":"«Celui qui traîne socialement à cause de son travail ne sera pas relevé par son origine sociale». (Autre version): Celui qui n'est pas honoré par sa situation personnelle, ne le sera pas par celui de son lignage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m390":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لِلْمُؤْمِنِ ثَلاَثُ سَاعَات: فَسَاعَةٌ يُنَاجِي فِيهَا رَبَّهُ، وَسَاعَةٌ يَرُمُّ مَعَاشَهُ، وَسَاعَةٌ يُخَلِّي بَيْنَ نَفْسِهِ وَبَيْنَ لَذَّتِهَا فِيمَا يَحِلُّ وَيَجْمُلُ. وَلَيْسَ لِلْعَاقِلِ أَنْ يَكُونَ شَاخِصاً إِلَّا فِي ثَلاَثٍ: مَرَمَّةٍ لِمَعَاشٍ، أَوْ خُطْوَةٍ فِي مَعَادٍ، أَوْ لَذَّةٍ فِي غَيْرِ مُحَرَّمٍ.","ob":"Trois heures sont offertes au croyant: une heure durant laquelle il se communique avec son Seigneur, une autre pour assurer ses moyens de subsistance, et une troisième où il cherche les plaisirs de l'âme, licites et belles. Le sage ne doit tendre qu'à trois choses: l'amélioration de la subsistance, un pas vers la Résurrection ou un plaisir qui ne soit pas illicite.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m391":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"ازْهَدْ فِي الدُّنْيَا يُبَصّرْكَ اللّٰهُ عَوْرَاتِهَا، وَلَا تَغْفُلْ فَلَسْتَ بِمَغْفُولٍ عَنْكَ!","ob":"Renonce au monde et alors Dieu te fait voir ses illusions. Ne sois pas nonchalant car tu n'es pas délaissé à toi-même!","obNotes":[],"an":"Renonce à ce monde et Dieu t'en fera voir les défauts; mais ne te laisse pas égarer car tu es surveillé.","anIntro":"","anNotes":[],"diff":null}]},"m392":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"تَكَلَّمُوا تُعْرَفُوا، فَإِنَّ الْمَرْءَ مَخْبُوءٌ تَحْتَ لِسَانِهِ.","ob":"Parlez et vous serez connus, car l'homme se cache sous sa langue.","obNotes":[],"an":"Parlez et on vous connaîtra car votre personnalité est révélée par vos discours.","anIntro":"","anNotes":[],"diff":null}]},"m393":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"خُذْ مِنَ الدُّنيْا مَا أَتَاكَ، وَتَوَلَّ عَمَّا تَوَلَّى عَنْكَ؛ فَإِنْ أَنْتَ لَمْ تَفْعَلْ فَأَجْمِلْ فِي الطَّلَبِ.","ob":"Prends de la vie ce qui t'est donné et détourne-toi de ce qui s'éloigne de toi; si tu ne le fais pas, que ta requête se limite à ce qui est beau et licite.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m394":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رُبَّ قَوْلٍ أَنْفَذُ مِنْ صَوْلٍ.","ob":"Il arrive souvent qu'une parole soit plus efficace qu'un assaut.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m395":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"كُلُّ مُقْتَصَرٍ عَلَيْهِ كَافٍ.","ob":"Est suffisant tout ce qui contente tes besoins.","obNotes":[],"an":"Tout ce dont vous vous contentez, vous suffira.","anIntro":"","anNotes":[],"diff":null}]},"m396":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْمَنِيَّةُ وَلَا الدَّنِيَّةُ! وَالتّقَلُّلُ وَلَا التَّوَسُّلُ. وَمَنْ لَمْ يُعْطَ قَاعِداً لَمْ يُعْطَ قَائِماً، وَالدَّهْرُ يَوْمَانِ، يَوْمٌ لَكَ، وَيَوْمٌ عَلَيْكَ؛ فَإذَا كَانَ لَكَ فَلاَ تَبْطَرْ، وَإِذَا كَانَ عَلَيْكَ فَاصْبِرْ!","ob":"La mort plutôt que la vilainie! Se contenter de peu plutôt que tendre la main. Celui dont la requête est refusée en douceur ne l'atteindra pas par la force. La vie terrestre se résume en deux jours: l'un t'est convenable et l'autre pas. Dans le premier cas ne sois pas pétulant et dans le second patiente!","obNotes":[],"an":"Le sort est inconstant: un jour il te sourit et un autre il te boude, ne te grise pas dans les jours fastes, ne perds pas patience dans les jours sombres.","anIntro":"","anNotes":[],"diff":null}]},"m397":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"نِعْمَ الطِّيِّبُ الْمِسْكُ، خَفِيفٌ مَحْمِلُهُ، عَطِرٌ رِيحُهُ.","ob":"Le musc est un odorant excellent: facile à porter et exhalant de bonnes odeurs.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m398":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"ضَعْ فَخْرَكَ، وَاحْطُطْ كِبْرَكَ، وَاذْكُرْ قَبْرَكَ.","ob":"Humilie ta fierté, abaisse ton orgueil et rappelle-toi ta tombe.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m399":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِنَّ لِلْوَلَدِ عَلَى الْوَالِدِ حَقّاً، وَإِنَّ لِلْوَالِدِ عَلَى الْوَلَدِ حَقّاً. فَحَقُّ الْوَالِدِ عَلَى الْوَلَدِ أَنْ يُطِيعَهُ فِي كُلِّ شَيْءٍ، إِلَّا فِي مَعْصِيَةِ اللّٰهِ سُبْحَانَهُ؛ وَحَقُّ الْوَلَدِ عَلَى الْوَالِدِ أَنْ يُحَسِّنَ اسْمَهُ، وَيُحَسِّنَ أَدَبَهُ، وَيُعَلِّمَهُ الْقُرْآنَ.","ob":"Que ce soient l'enfant ou son père, ils ont des droits réciproques l'un vis à vis l'autre. L'enfant doit à son père une obéissance en toute chose, sauf la désobéissance à Dieu. Le père doit améliorer sa propre réputation, bien élever son enfant et lui apprendre le Coran.","obNotes":[],"an":"Le père et l'enfant ont des droits l'un sur l'autre: le droit du père sur l'enfant est celui de la pleine obéissance, sauf dans l'impiété, l'enfant a droit à un beau nom, une bonne éducation et à l'étude du Coran.","anIntro":"","anNotes":[],"diff":null}]},"m401":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مُقَارَبَةُ النَّاسِ فِي أَخْلاَقِهِمْ أَمْنٌ مِنْ غَوَائِلِهِمْ.","ob":"S'accommoder avec les caractères des gens fait éviter leur inimitié.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m404":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام، وَقَدْ سُئِلَ عَنْ مَعْنَى قَوْلِهِمْ: «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا باللهِ»: إِنَّا لَا نَمْلِكُ مَعَ اللّٰهِ شَيْئاً، وَلَا نَمْلِكُ إِلَّا مَا مَلَّكَنَا؛ فَمَتَى مَلَّكَنَا مَا هُوَ أَمْلَكُ بِهِ مِنَّا كَلَّفَنَا، وَمَتى أَخَذَهُ مِنَّا وَضَعَ تَكْلِيفَهُ عَنَّا.","ob":"(On lui demande le sens de la phrase: \"Il n'y a de puissance et de force qu'en Dieu\", il dit): Nous ne possédons rien avec Dieu, à part ce qu'Il nous donne. Dans ce cas, Il nous impose des obligations, mais lorsqu'Il retire ce qu'Il nous a donné, Il enlève les obligations imposées.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m405":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِعَمَّارِ بْنِ يَاسِرٍ؛ وَقَدْ سَمِعَهُ يُرَاجِعُ الْمُغِيرَةَ بْنَ شُعْبَةَ كَلَاماً: دَعْهُ يَا عَمَّارُ، فَإِنَّهُ لَمْ يَأْخُذْ مِنَ الدِّينِ إِلَّا مَا قَارَبَهُ من الدُّنْيَا، وَعَلَى عَمْدٍ لَبَّسَ عَلَى نَفْسِهِ، لِيَجْعَلَ الشُّبُهَاتِ عَاذِراً لِسَقَطَاتِهِ.","ob":"(Il dit à 'Ammār ibn Yāsir après avoir entendu ses paroles adressées à al-Mughīra ibn Shu'ba): Laisse-le, 'Ammār! Il n'a pris de la religion que ce qui le fait rapprocher du monde. Il se plaît de propos délibéré dans l'équivoque en vue de le prendre comme excuse pour ses chutes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m406":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَحْسَنَ تَوَاضُعَ الْأَغْنِيَاءِ لِلْفُقَرَاءِ طَلَباً لِمَا عِنْدَ اللّٰهِ! وأَحْسَنُ مِنْهُ تِيهُ الْفُقَرَاءِ عَلَى الْأَغْنِيَاءِ اتِّكَالًا عَلَى اللّٰه.","ob":"Qu'elle est belle l'humilité des riches face aux pauvres pour demander ce qui est à Dieu! Plus belle encore la fierté des pauvres face aux riches d'être confiants en Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m407":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا اسْتَوْدَعَ اللّٰهُ امْرَأً عَقْلاً إِلَّا اسْتَنْقَذَهُ بِهِ يَوْماً مَا!","ob":"Dieu ne donne l'intelligence à l'homme que pour le sauver un jour du malheur.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m408":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ صَارَعَ الْحَقَّ صَرَعَهُ.","ob":"Quiconque lutte contre la vérité sera renversé par elle.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m409":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْقَلْبُ مُصْحَفُ الْبَصَرِ.","ob":"Le cœur est le registre de la vue.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m410":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"التُّقَى رَئِيسُ الْأَخْلَاقِ.","ob":"La piété est le chef des mœurs.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m411":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا تَجْعَلَنَّ ذَرَبَ لِسَانِكَ عَلَى مَنْ أَنْطَقَكَ، وَبَلاَغَةَ قَوْلِكَ عَلَى مَنْ سَدَّدَكَ.","ob":"N'aiguise pas ta langue contre celui qui t'a appris à parler, et n'utilise pas ton éloquence contre celui qui a entrepris ta formation.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m412":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كَفَاكَ أَدَباً لِنَفْسِكَ اجْتِنَابُ مَا تَكْرَهُهُ مِنْ غَيْرِكَ.","ob":"Il te suffit d'être poli en évitant ce que tu hais chez les autres.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m413":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ صَبَرَ صَبْرَ الْأَحْرَارِ، وَإِلَّا سَلاَ سُلُوَّ الْأَغْمَارِ.","ob":"Celui qui ne patiente pas comme les gens libres oubliera comme les ignorants.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m414":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَفِي خَبَرٍ آخَرَ أَنَّهُ عليه السلام قَالَ لِلْأَشْعَثِ بْنِ قَيْسٍ مُعَزِّياً عَنِ ابْنٍ لَهُ: إِنْ صَبَرْتَ صَبْرَ الْأَكَارِمِ، وَإِلَّا سَلَوْتَ سُلُوَّ الْبَهَائِمِ.","ob":"(Dans une variante, on rapporte qu'il dit à al-Ash'ath ibn Qays en lui présentant ses condoléances pour la mort d'un de ses fils): Si tu patientes, imite les nobles; sinon tu oublieras comme les bêtes de somme.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m415":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي صِفَةِ الدُّنْيَا: تَغُرُّ وَتَضُرُّ وَتَمُرُّ، وإنَّ اللّٰهَ تَعَالَى لَمْ يَرْضَهَا ثَوَاباً لِأَوْلِيَائِهِ، وَلَا عِقَاباً لِأَعْدَائِهِ، وَإِنَّ أَهْلَ الدُّنْيَا كَرَكْبٍ بَيْنَا هُمْ حَلُّوا إِذْ صَاحَ بِهِمْ سَائِقُهُمْ فَارْتَحَلُوا.","ob":"(Il dit au sujet de la vie terrestre): Elle séduit, nuit et est éphémère. Dieu ne l'a acceptée ni comme récompense pour ses amis, ni comme un châtiment pour ses ennemis. Les gens du monde sont semblables à une troupe de cavaliers qui, dès qu'ils arrivent à destination, entendent le cri de leur conducteur de continuer leur voyage.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m416":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ لِابْنِهِ الْحَسَنِ عليهما السلام: لَا تُخَلِّفَنَّ وَرَاءَكَ شَيْئاً مِنَ الدُّنْيَا، فَإِنَّكَ تُخَلِّفُهُ لِأَحَدِ رَجُلَيْنِ: إِمَّا رَجُلٍ عَمِلَ فِيهِ بِطَاعَةِ اللّٰهِ فَسَعِدَ بِمَا شَقِيتَ بِهِ، وَإِمَّا رَجُلٍ عَمِلَ فِيهِ بِمَعْصِيَةِ اللّٰهِ فَشَقِيَ بِمَا جَمَعْتَ لَهُ؛ فَكُنْتَ عَوْناً لَهُ عَلى مَعْصِيَتِهِ، وَلَيْسَ أَحَدُ هذَيْنِ حَقِيقاً أَنْ تُؤْثِرَهُ عَلَى نَفْسِكَ.","ob":"(Il dit à son fils al-Ḥasan): Ne laisse derrière toi un bien quelconque de ce monde. Car tu le laisses ou bien pour un homme qui s'en sert dans l'obéissance de Dieu et alors il sera heureux d'avoir ce dont tu as souffert pour le lui laisser, ou bien pour un homme qui s'en sert en désobéissant à Dieu et alors il sera châtié par ce que tu lui as légué et tu l'auras aidé dans sa désobéissance. Dans les deux cas, ces deux hommes ne méritent pas que tu les préfères à toi-même.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"قال الرضيّ: وَيُرْوَى هَذَا الْكَلَامُ عَلَى وَجْهٍ آخَرَ وَهُوَ: أَمَّا بَعْدُ، فَإِنَّ الَّذِي فِي يَدِكَ مِنَ الدُّنْيَا قَدْ كَانَ لَهُ أَهْلٌ قَبْلَكَ، وَهُوَ صَائِرٌ إِلَى أَهْلٍ بَعْدَكَ، وَإِنَّمَا أَنْتَ جَامعٌ لِأَحَدِ رَجُلَيْنِ: رَجُلٍ عَمِلَ فِيمَا جَمَعْتَهُ بِطَاعَةِ اللّٰهِ فَسَعِدَ بِمَا شَقِيتَ بِهِ؛ أَوْ رَجُلٍ عَمِلَ فِيهِ بِمَعْصِيَةِ اللّٰهِ، فشَقيت بِمَا جَمَعْتَ لَهُ. وَلَيْسَ أَحَدُ هذَيْنِ أَهْلاً أَنْ تُؤْثِرَهُ عَلَى نَفْسِكَ، وَلَا أَنْ تَحْمِلَ لَهُ عَلَى ظَهْرِكَ، فارْجُ لِمَنْ مَضَى رَحْمَةَ اللّٰهِ، ولِمن بَقِيَ رِزْقَ اللّٰه.","ob":"(Voici une autre version rapportée par al-Sharīf al-Raḍī): Ce qui se trouve entre tes mains ici-bas appartenait à d'autres avant toi et sera le lot de parents après toi. Ou bien il appartiendra à un homme qui l'utilisera dans le cadre de l'obéissance de Dieu et, par conséquent, il sera heureux grâce à ton travail ardu, ou bien il appartiendra à un homme qui l'utilisera contrairement à la volonté divine et alors tu t'étais dévoué pour lui léguer tes biens. Aucun des deux n'est digne d'être préféré à toi-même et d'être porté sur ton dos. Demande à ceux qui sont partis la miséricorde de Dieu et à ceux qui restent les biens de Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m417":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِقَائِلٍ قَالَ بِحَضْرَتِهِ: «أَسْتَغْفِرُ اللّٰهَ»: ثَكِلَتْكَ أُمُّكَ، أَتَدْرِي مَا الِاسْتِغْفَارُ؟ الِاسْتِغْفَارُ دَرَجَةُ الْعِلِّيِّينَ، وَهُوَ اسْمٌ وَاقِعٌ على سِتَّةِ مَعَانٍ: أوَّلهما النَّدَمُ على مَا مَضَى، وَالثَّانِي الْعَزْمُ على تَرْكِ الْعَوْدِ إِلَيْهِ، وَالثَّالِثُ أَنْ تُؤَدِّيَ على الْمَخْلُوقِينَ حُقُوقَهُمْ حَتَّى تَلْقَى اللّٰهَ أَمْلَسَ لَيْسَ عَلَيْكَ تَبِعَةٌ، وَالرَّابِعُ أَنْ تَعْمِدَ إِلَى كُلِّ فَرِيضَةٍ عَلَيْكَ ضَيَّعْتَهَا فَتُؤَدِّيَ حَقَّهَا، وَالْخَامِسُ أَنْ تَعْمِدَ إِلَى اللَّحْمِ الَّذِي نَبَتَ على السُّحْتِ فَتُذِيبَهُ بِالْأَحْزَانِ، حَتَّى تُلْصِق الْجِلْدُ بِالْعَظْمِ، وَيَنْشَأَ بَيْنَهُمَا لَحْمٌ جَدِيدٌ، وَالسَّادِسُ أَنْ تُذِيقَ الْجِسْمَ أَلَمَ الطَّاعَةِ كَمَا أَذَقْتَهُ حَلاَوَةَ الْمَعْصِيَةِ، فَعِنْدَ ذلِكَ تَقُولُ: «أَسْتَغْفِرُ اللهَ».","ob":"(Il dit à un homme qui, en sa présence, avait dit: «je demande le pardon de Dieu»): Que ta mère te perde! Sais-tu ce que c'est la demande du pardon? C'est la demande de ceux qui ont atteint un très haut degré [de piété], et elle renferme six sens: le premier est la contrition, le second est la décision de ne plus pécher; le troisième est de donner aux créatures leurs dus pour que tu rencontres Dieu pur et sans responsabilité, le quatrième est de te pencher sur l'accomplissement de toute obligation que tu avais délaissée naguère, le cinquième est de faire maigrir par les tristesses ta chair qui s'est grossie par l'argent illicite, jusqu'à ce que ta peau colle sur tes os et entre les deux pousse une nouvelle chair, et le sixième est de faire subir à ton corps l'amertume de l'obéissance comme tu lui avais fait goûter les plaisirs de la désobéissance. Après avoir fait tout cela tu diras: «je demande le pardon de Dieu».","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m418":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الحِلم عشيرة.","ob":"La longanimité est une tribu [tant elle te rapporte l'amour des gens].","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m419":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مِسْكِينٌ ابْنُ آدَمَ: مَكْتُومُ الْأَجَلِ، مَكْنُونُ الْعِلَلِ، مَحْفُوظُ الْعَمَلِ، تُؤْلِمُهُ الْبَقَّةُ، وَتَقْتُلُهُ الشَّرْقَةُ، وَتُنْتِنُهُ الْعَرْقَةُ.","ob":"Le fils d'Adam est misérable: il méconnaît son terme et ses maladies et est voué au labeur. La puce lui fait mal, la salive le suffoque et la transpiration lui donne une odeur nauséabonde.","obNotes":[],"an":"Que le descendant d'Adam est misérable! Son terme lui est inconnu, ses maux lui sont voilés, son acte est noté, la punaise le fait souttir, le hoquet l'étouffe et la sueur le fait puer.","anIntro":"","anNotes":[],"diff":null}]},"m420":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَرُوِيَ أَنَّهُ عليه السلام كَانَ جَالِساً فِي أَصْحَابِهِ، فَمَرَّتْ بِهِمُ امْرَأَةٌ جَمِيلَةٌ، فَرَمَقَهَا الْقَوْمُ بِأَبْصَارِهِمْ، فَقَالَ عليه السلام: إِنَّ أَبْصَار هذِهِ الْفُحُولِ طَوَامِحُ؛ وَإِنَّ ذلِكَ سَبَبُ هَبَابِهَا، فإِذَا نَظَرَ أَحَدُكُمْ إِلَى امْرَأَةٍ تُعْجِبُهُ فَلْيُلاَمِسْ أَهْلَهُ، فَإِنَّمَا هِيَ امْرَأَةٌ كامرأته.","ob":"(On raconte qu'il était assis en compagnie de ses amis. Une jolie femme passa. Les amis l'ont poursuivie de leurs yeux. Alors il dit): Les regards de ces étalons se lèvent pour voir celle qui les irrite. Si quelqu'un parmi vous voit une femme qui lui plaît, qu'il aille toucher sa propre femme. Pas de différence entre les deux!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null},{"t":"c","nums":[2],"ar":"فَقَالَ رَجُلٌ مِنَ الْخَوَارِجِ: «قَاتَلَهُ اللَّهُ كَافِراً مَا أَفْقَهَهُ»! فَوَثَبَ الْقَوْمُ لِيَقْتُلُوهُ، فَقَالَ عليه السلام: رُوَيْداً إِنَّمَا هُوَ سَبٌّ بِسَبٍّ، أَوْ عَفْوٌ عَنْ ذَنْبٍ!","ob":"(Un Kharijite dit: «que Dieu le tue! C'est un athée bien doué d'intelligence»! Les compagnons d' 'Alī sursautent pour le tuer; alors il dit): Doucement! Ce n'est qu'un blasphème contre blasphème, ou bien le pardon d'une faute!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m421":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كَفَاكَ مِنْ عَقْلِكَ مَا أَوْضَحَ لَكَ سُبُل غَيِّكَ مِنْ رُشْدِكَ.","ob":"Il te suffit de ton intelligence qu'elle t'éclaire les voies de ton erreur déraisonnable.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m422":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"افْعَلُوا الْخَيْرَ وَلَا تَحْقِرُوا مِنْهُ شَيْئاً، فَإِنَّ صَغِيرَهُ كَبِيرٌ وَقَلِيلَهُ كَثِيرٌ، وَلَا يَقُولَنَّ أَحَدُكُمْ: إِنَّ أَحَداً أَوْلَى بِفِعْلِ الْخَيْرِ مِنِّي...","ob":"Faites le bien et n'en sous-estimez rien, car le peu de bien est déjà beaucoup. Que personne parmi vous ne dise: un tel est mieux placé que moi pour faire le bien...","obNotes":[],"an":"Faites le bien et n'en dédaignez rien: le moindre bien est en soi grand et le peu abondant.","anIntro":"","anNotes":[],"diff":null}]},"m423":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ أَصْلَحَ سَرِيرَتَهُ أَصْلَحَ اللّٰهُ عَلاَنِيَتَهُ، وَمَنْ عَمِلَ لِدِينِهِ كَفَاهُ اللّٰهُ أَمْرَ دُنْيَاهُ، وَمَنْ أَحْسَنَ فِيمَا بَيْنَهُ وبَيْنَ اللّٰهِ أَحْسَنَ اللَّهُ مَا بَيْنَهُ وَبَيْنَ النَّاسِ.","ob":"Celui qui améliore son for intérieur Dieu améliorera sa notoriété. Quiconque travaille pour sa religion Dieu lui garantit la suffisance en ce monde. Et quiconque établit de bonnes relations avec Dieu verra ses bonnes relations assurées.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m424":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"الْحِلْمُ غِطَاءٌ سَاتِرٌ، وَالْعَقْلُ حُسَامٌ قَاطِعٌ، فَاسْتُرْ خَلَلَ خُلُقِكَ بِحِلْمِكَ، وَقَاتِلْ هَوَاكَ بِعَقْلِكَ.","ob":"La mansuétude est une couverture qui cache et l'intelligence est un sabre tranchant. Cache les désordres de ton caractère par ta mansuétude, et combats tes passions par ton intelligence.","obNotes":[],"an":"L'indulgence est un voile protecteur, la raison une épée tranchante; voile le défaut de ton caractère avec ton indulgence et réprime ta passion avec ta raison.","anIntro":"","anNotes":[],"diff":null}]},"m425":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ لِلَّهِ عِبَاداً يَخْتَصُّهُمُ اللَّهُ بِالنِّعَمِ لِمَنَافِعِ الْعِبَادِ، فَيُقِرُّهَا فِي أَيْدِيهِمْ مَا بَذَلُوهَا؛ فَإِذَا مَنَعُوهَا نَزَعَهَا مِنْهُمْ، ثُمَّ حَوَّلَهَا إِلَى غَيْرِهِمْ.","ob":"Dieu s'est réservé des adorateurs qu'Il couvre de grâces pour le bien-être des serviteurs. Il maintient ces grâces dans leurs mains tant qu'ils s'en servent avec profusion, mais dès qu'ils les retiennent pour eux-mêmes Il les en prive et les transmet à d'autres.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m426":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"لَا يَنْبَغِي لِلْعَبْدِ أَنْ يَثِقَ بِخَصْلَتَيْنِ: الْعَافِيَةِ وَالْغِنَى. بَيْنَا تره مُعَافًى إِذْ سَقِمَ؛ وَبَيْنَا تَرَاهُ غَنِيّاً إِذِ افْتَقَرَ.","ob":"Le serviteur ne doit se fier ni à la santé, ni à la richesse. Tu le vois sain, et voici qu'il tombe malade; tu le connais riche, et voici qu'il s'appauvrit.","obNotes":[],"an":"L'homme ne doit pas se fier à deux choses précaires: la Santé et la Fortune; alors qu'il paraissait sain le voilà soudain malade et de riche qu'il était, il devient pauvre.","anIntro":"","anNotes":[],"diff":null}]},"m427":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مَنْ شَكَا الْحَاجَةَ إِلَى مُؤْمِنٍ، فكأنَّه شَكَاهَا إِلَى اللهِ؛ وَمَنْ شَكَاهَا إلَى كَافِرٍ فَكَأَنَّمَا شَكَا اللهَ.","ob":"Se plaindre devant un croyant qu'on a besoin de quoi vivre c'est comme se plaindre devant Dieu. Mais se plaindre devant un athée équivaut à se plaindre de Dieu.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m428":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي بَعْضِ الْأَعْيَادِ: إِنَّمَا هُوَ عِيدٌ لِمَنْ قَبِلَ اللّٰهُ صِيَامَهُ وَشَكَرَ قِيَامَهُ، وَكُلُّ يَوْمٍ لَا يُعْصَى اللّٰهُ فِيهِ فَهُوَ عِيدٌ.","ob":"(Il dit à propos d'une fête): C'est plutôt une fête pour celui dont Dieu a accepté le jeûne et qui Le remercie pour l'avoir imposé, et tout jour où l'on ne désobéit pas à Dieu est une fête.","obNotes":[],"an":"Lors d'une fête l'Imām dit: ce n'est point une fête sauf pour celui dont Dieu agrée le jeûne et la prière; mais toute journée est fête tant que Dieu n'y est pas désobéi.","anIntro":"","anNotes":[],"diff":null}]},"m429":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِنَّ أَعْظَمَ الْحَسَرَاتِ يَوْمَ الْقِيَامَةِ حَسْرَةُ رَجُلٍ كَسَبَ مَالًا فِي غَيْرِ طَاعَةِ اللهِ، فَوَرَّثَهُ رَجُلٌ فَأنْفَقَهُ فِي طَاعَةِ اللّٰهِ سُبْحَانَهُ، فَدَخَلَ بِهِ الْجَنَّةَ، وَدَخَلَ الْأَوَّلُ بِهِ النَّارَ.","ob":"Le plus grand soupir au Jour du Jugement est celui d'un homme qui a acquis de l'argent en désobéissant à Dieu et qui a été hérité par un homme qui l'a dépensé dans l'obéissance de Dieu et, par conséquent, est entré dans le Paradis tandis que le premier est voué au Feu.","obNotes":[],"an":"Au jour du Jugement la plus grande angoisse sera celle d'un homme qui aura amassé des biens contrairement aux ordres de Dieu et les aura légués à un autre qui les aura utilisés selon les préceptes divins. L'héritier gagnera la vie éternelle et l'autre entrera en enter.","anIntro":"","anNotes":[],"diff":null}]},"m430":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"إِنَّ أَخْسَرَ النَّاسِ صَفْقَةً، وَأَخْيَبَهُمْ سَعْياً، رَجُلٌ أَخْلَقَ بَدَنَهُ فِي طَلَبِ مَالِهِ، وَلَمْ تُسَاعِدْهُ الْمَقَادِيرُ عَلَى إِرَادَتِهِ، فَخَرَجَ مِنَ الدُّنْيَا بِحَسْرَتِهِ، وَقَدِمَ عَلَى الْآخِرَةِ بِتَبِعَتِهِ.","ob":"L'affaire perdante qui mène le plus à la frustration est celle d'un homme qui a exténué son corps dans la recherche de l'argent, mais que le destin n'a pas aidé, et alors il quitte la vie avec angoisse et passe à l'autre vie endetté envers Dieu et les hommes.","obNotes":[],"an":"Le plus perdant des hommes et le plus détaillant est celui qui s'épuisa à amasser des biens alors que le destin ne favorisait pas ses desseins: il quitta le monde avec amertume et aborda l'éternité en déshérité.","anIntro":"","anNotes":[],"diff":null}]},"m431":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"من طَلَبَ الدُّنْيَا طَلَبَهُ الْمَوْتُ، حَتَّى يُخْرِجَهُ عَنْهَا؛ وَمَنْ طَلَبَ الْآخِرَةَ طَلَبَتْهُ الدُّنْيَا حَتَّى يَسْتَوْفِيَ رِزْقَهُ مِنْهَا.","ob":"Quiconque demande les bien-fonds de la vie terrestre, la mort le demande pour l'en séparer. Mais quiconque demande l'autre vie, le monde le demande pour le dédommager.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m432":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إِنَّ أَوْلِيَاءَ اللّٰهِ هُمُ الَّذِينَ نَظَرُوا إِلَى بَاطِنِ الدُّنْيَا إِذَا نَظَرَ النَّاسُ إِلَى ظَاهِرِهَا، وَاشْتَغَلُوا بِآجِلِهَا إِذَا اشْتَغَلَ النَّاسُ بِعَاجِلِهَا، فَأَمَاتُوا مِنْهَا مَا خَشُوا أَنْ يُمِيتَهُمْ، وَتَرَكُوا مِنْهَا مَا عَلِمُوا أَنَّهُ سَيَتْرُكُهُمْ ... بِهِمْ عُلِمَ الْكِتَابُ وَبِهِ عُلِمُوا، وَبِهِمْ قَامَ الْكِتَابُ وَبِهِ قَامُوا، لَا يَرَوْنَ مَرْجُوّاً فَوْقَ مَا يَرْجُونَ، وَلَا مَخُوفاً فَوْقَ مَا يَخَافُونَ.","ob":"Les amis de Dieu sont ceux qui regardent l'intérieur du monde terrestre lorsque les gens regardent son extérieur, s'occupent uniquement de la vie future et se mortifient en s'abstenant de s'attacher à ses éléments périssables et mortels... Par eux le Livre fut connu et eux le connurent. Par eux le Livre a été suivi et eux le suivirent. Ils ne voient aucune espérance au-delà de la leur, ni aucun sujet de peur au-delà de ce dont ils ont peur ici-bas.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m433":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اذْكُرُوا انْقِطَاعَ الَّلَّذَّاتِ، وَبَقَاءَ التَّبِعَاتِ.","ob":"Souvenez-vous de l'arrêt des plaisirs et de la permanence des responsabilités.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m435":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا كَانَ اللّٰهُ لِيَفْتَحَ عَلَى عَبْدٍ بَابَ الشُّكْرِ وَيُغْلِقَ عَنْهُ بَابَ الزِّيَادَةِ، وَلَا لِيَفْتَحَ عَلَى عَبْدٍ بَابَ الدُّعَاءِ وَيُغْلِقَ عَنْهُ بَابَ الْإِجَابَةِ، وَلَا لِيَفْتَحَ لِعَبْدٍ بَابَ التَّوْبَةِ وَيُغْلِقَ عَنْهُ بَابَ الْمَغْفِرَةِ.","ob":"Dieu ne saurait ouvrir au serviteur les portes du remerciement, de l'invocation et du repentir sans lui fermer celles de la majoration, de l'exaucement et du pardon.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m436":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أوْلَى النَّاسِ بِالْكَرَمِ مَنْ عُرِفَتْ به الْكِرَامُ.","ob":"L'homme le plus digne de la générosité est celui qui devient une référence pour les généreux.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m437":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَسُئِلَ عليه السلام: أَيُّهُمَا أَفْضَلُ: الْعَدْلُ أَوِ الْجُودُ؟ فَقَالَ عليه السلام: الْعَدْلُ يَضَعُ الْأُمُورَ مَوَاضِعَهَا، والْجُودُ يُخْرِجُهَا مِن جِهَتِهَا؛ وَالْعَدْلُ سَائِسٌ عَامٌّ، وَالْجُودُ عَارضٌ خَاصٌّ، فَالْعَدْلُ أَشْرَفُهُمَا وَأَفْضَلُهُمَا.","ob":"(On lui demande: lequel est meilleur: la justice ou la générosité? Il répond): La justice met chaque chose à sa place, la générosité la déplace; la justice est un administrateur général tandis que la générosité est un accident spécial. Donc, la justice est la plus noble et la meilleure qualité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m438":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"النَّاسُ أَعْدَاءُ مَا جَهِلُوا.","ob":"Les hommes sont les ennemis de ce qu'ils ignorent.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m439":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الزُّهْدُ كُلُّهُ بَيْنَ كَلِمَتَينِ مِنَ الْقُرْآنِ: قَالَ اللّٰهُ سُبْحَانَهُ، «لِّكَيْلَا تَأْسَوْا عَلَىٰ مَا فَاتَكُمْ، وَلَا تَفْرَحُوا بِمَا آتَاكُمْ». وَمَنْ لَمْ يَأْسَ عَلَى الْمَاضِي، وَلَمْ يَفْرَحْ بِالْآتِي، فَقَدْ أَخَذَ الزُّهْدَ بِطَرَفَيْهِ.","ob":"Toute la continence est contenue entre deux mots du Coran. Dieu dit: «afin que vous ne vous tourmentiez pas au sujet de ce qui vous a échappé, ni n'exultiez pour ce qu'Il vous a donné» (57.23). Celui qui ne s'attriste pas des épisodes de son destin et ne se réjouit non plus de ses changements brusques, celui-ci tient les deux extrémités de la continence.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m440":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَنْقَضَ النَّوْمَ لِعَزَائِمِ الْيَوْمِ!","ob":"C'est le sommeil qui démolit les grandes décisions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m441":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْوِلَايَاتُ مَضَامِيرُ الرِّجَالِ.","ob":"Les gouvernements sont les hippodromes des hommes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m442":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَيْسَ بَلَدٌ بأَحَقَّ بِكَ مِنْ بَلَدٍ. خَيْرُ الْبِلاَدِ مَا حَمَلَكَ.","ob":"Il n'y a pas un pays qui te mérite plus qu'un autre. Le meilleur est celui qui te soutient.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m444":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"قَلِيلٌ مَدُومٌ عَلَيْهِ خَيْرٌ مِنْ كَثِيرٍ مَمْلُولٍ مِنْهُ.","ob":"Le peu qui dure vaut mieux que le beaucoup dont on s'ennuie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m445":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إذَا كَانَ في رَجُلٍ خَلَّةٌ رائقة فَانْتَظِرُوا أَخَوَاتِهَا.","ob":"Si une vertu sereine se trouve chez un homme, attendez ses sœurs.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m446":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِغَالِبِ بْنِ صَعْصَعَةَ أَبِي الْفَرَزْدَقِ، فِي كَلَامٍ دَارَ بَيْنَهُمَا: مَا فَعَلَتْ إِبِلُكَ الْكثِيرَةُ؟ قال: ذَعْذَعَتْها الحُقُوقُ يا أمير المؤمنين. فَقَالَ عليه السلام: ذلك أَحْمَدُ سُبُلِهَا.","ob":"(Dans un entretien entre Ṣa'ṣa'a Abī al-Farazdaq et 'Alī, celui-ci demande): Qu'en est-il arrivé à tes chameaux nombreux? (Et l'autre de répondre: ils ont été dispersés par la <i>zakāt</i> et les aumônes, ô Prince des Croyants). Alors 'Alī dit: c'est le meilleur moyen de s'en débarrasser.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m447":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنِ اتَّجَرَ بِغَيْرِ فِقْهٍ فَقَدِ ارْتَطَمَ فِي الرِّبَا.","ob":"Celui qui ne commerce pas en connaissance de cause se heurtera bientôt à l'usure.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m448":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ عَظَّمَ صِغَارَ الْمَصَائِبِ ابْتَلاَهُ اللّٰهُ بِكِبَارِهَا.","ob":"Quiconque aggrave les petits malheurs Dieu lui enverra les grands.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m449":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْ كَرُمَتْ عَلَيْهِ نَفْسُهُ هَانَتْ عَلَيْهِ شهواته.","ob":"Quiconque fait honneur à son âme dédaigne ses passions.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m450":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا مَزَحَ امْرُؤٌ مَزْحَةً إِلَّا مَجَّ مِنْ عَقْلِهِ مَجَّةً.","ob":"Chaque fois qu'un individu s'adonne au badinage, il rejette une portion de son intelligence.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m451":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"زُهْدُكَ فِي رَاغِبٍ فِيكَ نُقْصَانُ حَظٍّ، وَرَغْبَتُكَ فِي زَاهِدٍ فِيكَ ذُلُّ نَفْسٍ.","ob":"Ton éloignement de celui qui aspire à ton amitié est une perte d'une chance bienveillante, et ton aspiration à celui qui s'éloigne de toi est une humiliation.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m452":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْغِنَى وَالْفَقْرُ بَعْدَ الْعَرْضِ عَلَى اللهِ.","ob":"La vraie richesse et pauvreté n'apparaissent qu'après le Jugement dernier.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m453":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا زَالَ الزُّبَيْرُ رَجُلاً مِنَّا أَهْلَ الْبَيْتِ حَتَّى نَشَأَ ابْنُهُ الْمَشْؤُومُ عَبْدُ اللهِ.","ob":"Al-Zubayr est resté l'un de nous -les gens de la Maison du Prophète- jusqu'à l'apparition de son fils 'Abdallāh, de mauvais augure.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m454":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا لِابْنِ آدَمَ وَالْفَخْرِ: أَوَّلُهُ نُطْفَةٌ، وَآخِرُهُ جِيفَةٌ، وَلَا يَرْزُقُ نَفْسَهُ، وَلَا يَدفَعُ حَتْفَهُ.","ob":"Comment le fils d'Adam peut-il se vanter de gloire tant qu'il commence par être une goutte et qu'il finit par être une charogne, qu'il ne peut subsister à lui-même ni ne peut arrêter sa mort?!","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m456":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"أَلَا حُرٌّ يَدَعُ هذِهِ اللُّمَاظَةَ لِأَهْلِهَا؟ إلإنَّه لَيْسَ لِأَنْفُسِكُمْ ثَمَنٌ إِلَّا الْجَنَّةَ، فَلاَ تَبِيعُوهَا إِلَّا بِهَا.","ob":"N'y a-t-il pas un homme libre qui laisse la vie ici-bas aux esclaves? Vos âmes n'ont de prix que le Paradis; ne les vendez qu'à ce prix.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m457":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَنْهُومَانِ لَا يَشْبَعَانِ: طَالِبُ عِلْمٍ وَطَالِبُ دُنْيَا.","ob":"Il y a deux insatiables dont l'appétit est insatisfait: celui qui demande la science et celui qui demande la vie terrestre.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m458":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْإِيمَانُ أَنْ تُؤْثِرَ الصِّدْقَ حَيْثُ يَضُرُّكَ، عَلَى الْكَذِبِ حَيْثُ يَنْفَعُكَ، وَأَلَّا يَكُونَ فِي حَدِيثِكَ فَضْلٌ عَنْ عملِك، وَأَنْ تَتَّقِيَ اللّٰهَ فِي حَدِيثِ غَيْرِكَ.","ob":"La foi exige que tu préfères la véracité, quitte à t'être nuisible, au mensonge qui t'est utile; elle exige aussi que tu ne laisses pas les paroles l'emporter sur tes actions et que tu craignes Dieu en parlant d'autrui.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m460":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْحِلْمُ وَالْأَنَاةُ تَوْأَمَانِ يُنْتِجُهُمَا عُلُوُّ الْهِمَّةِ.","ob":"La clémence et la douceur sont deux jumelles engendrées par la magnanimité.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m461":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الْغِيبَةُ جُهْدُ الْعَاجزِ.","ob":"La médisance est l'effort ultime de l'impuissant.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m462":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"رُبَّ مَفْتُونٍ بِحُسْنِ الْقَوْلِ فِيهِ.","ob":"Il arrive souvent qu'on soit séduit à force d'éloges.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m463":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"الدُّنْيَا خُلِقَتْ لِغَيْرِهَا، ولَمْ تُخْلَقْ لِنَفْسِهَا.","ob":"La vie terrestre a été créée pour autre chose que soi-même.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m465":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام فِي مَدْحِ الْأَنْصَارِ: هُمْ وَاللّٰهِ رَبَّوُا الْإِسْلَامَ كَمَا يُرَبَّى الْفَلُوُّ مَعَ غَنَائِهِمْ، بِأَيْدِيهِمُ السِّبَاطِ، وَأَلْسِنَتِهِمُ السِّلاَطِ.","ob":"(Il dit pour vanter les Anṣār: ceux qui avaient épaulé le Prophète à Médine): Par Dieu! ils ont élevé l'Islam comme on élève l'étalon, bien qu'ils n'en avaient pas besoin, et ce avec leurs mains généreuses et leurs langues mordantes.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m468":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَأْتِي عَلَى النَّاسِ زَمَانٌ عَضُوضٌ، يَعَضُّ الْمُوسِرُ فِيهِ عَلَى مَا فِي يَدَيْهِ وَلَمْ يُؤْمَرْ بِذلِكَ، قَالَ اللّٰهُ سُبْحَانَهُ: «وَلَا تَنسَوُا الْفَضْلَ بَيْنَكُمْ». تَنْهَدُ فِيهِ الْأَشْرَارُ، وَتُسْتَذَلُّ الْأَخْيَارُ، ويُبَايعُ الْمُضْطَرُّونَ، وَقَدْ نَهَى رَسُولُ اللّٰهِ صَلى اللّٰهُ عليه وآله وسلَّم عَنْ بَيْعِ الْمُضْطَرِّينَ.","ob":"Les gens connaîtront un temps difficile où le riche ferme ses mains sur ce qu'il tient contrairement à l'ordre de Dieu qui dit: «Et n'oubliez pas votre faveur mutuelle» (2,237), où les mauvais sont haussés, les bons humiliés et ceux qui se trouvent dans le besoin sont vendus contrairement aux interdictions du Messager d'Allah (s).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m469":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"يَهْلِكُ فِيَّ رَجُلاَنِ: مُحِبٌّ مُفْرِطٌ، وَبَاهِتٌ مُفْتَرٍ.","ob":"Deux hommes seront damnés par leur attitude envers moi: celui qui exagère dans mon amour et celui qui me calomnie.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m470":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"التَّوْحِيدُ أَلَّا تَتَوَهَّمَهُ، وَالْعَدْلُ أَلَّا تَتَّهِمَهُ.","ob":"L'unicité consiste à ne pas se représenter Dieu, et la justice à ne pas lui attribuer des actes dénués de sagesse.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m471":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"لَا خَيْرَ فِي الصَّمْتِ عَنِ الْحُكْمِ، كَمَا أَنَّهُ لَا خَيْرَ فِي الْقوْلِ بِالْجَهْلِ.","ob":"Il n'est pas bon de se taire lorsqu'il faut émettre un jugement, de même qu'il n'est pas bon de parler d'une affaire qu'on ignore.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m472":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"اللَّهُمَّ اسْقِنَا ذُلُلَ السَّحَابِ دُونَ صِعَابِهَا.","ob":"Notre Seigneur, envoie-nous des nuages semblables aux chamelles qui se laissent traire facilement.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m473":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقِيلَ لَهُ عليه السلام: لَوْ غَيَّرْتَ شَيْبَكَ يَا أَمِيرَ الْمُؤْمِنِينَ، فَقَالَ عليه السلام: الْخِضَابُ زِينَةٌ وَنَحْنُ قَوْمٌ فِي مُصِيبَةٍ! (يُرِيدُ وَفَاةَ رَسُولِ اللَّهِ صلى اللّٰه عليه وآله وسلَّم).","ob":"(On lui demande de cacher ses cheveux blancs, il dit): Teindre les cheveux est un embellissement, mais nous sommes en deuil! (le décès du Messager d'Allah (s)).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m474":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"مَا الْمُجَاهِدُ الشَّهِيدُ فِي سَبِيلِ اللّٰهِ بِأَعْظَمَ أَجْراً مِمَّنْ قَدَرَ فَعَفَّ: لَكَادَ الْعَفِيفُ أَنْ يَكُونَ مَلَكاً مِنَ الْمَلاَئِكَةِ.","ob":"Celui qui meurt martyr durant le <i>jihād</i> n'aura point une récompense plus grande que celui qui arrive à s'abstenir de venger, car celui-ci faillit être un ange.","obNotes":[],"an":"Le combattant qui trouve la mort au service de Dieu n'a point plus de mérite que celui qui pardonne tout en étant puissant: sa clémence le rend comparable aux anges.","anIntro":"","anNotes":[],"diff":null}]},"m475":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"«الْقَنَاعَةُ مَالٌ لَا يَنْفَدُ». (قال الرضي: وقد روي بعضهم هذا الكلام لرسول اللّٰه صلي اللّٰه عليه وآله وسلّم).","ob":"«La tempérance est un bien inépuisable». (D'après al-Raḍī, cette expression a été dite par le Messager d'Allah (s)).","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m476":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"وَقَالَ عليه السلام لِزِيَادِ بن أَبِيهِ - وَقَدِ اسْتَخْلَفَهُ لِعَبْدِ اللَّهِ ابن الْعَبَّاسِ عَلَى فَارِسَ وَأَعْمَالِهَا، فِي كَلَامٍ طَوِيلٍ كَانَ بَيْنَهُمَا، نَهَاهُ فِيهِ عَنْ تَقَدُّمِ الْخَرَاجِ: اسْتَعْمِلِ الْعَدْلَ، وَاحْذَرِ الْعَسْفَ والْحَيْفَ، فَإِنَّ الْعَسْفَ يَعُودُ بِالْجَلاَءِ، وَالْحَيْفَ يَدْعُو إِلَى السَّيْفِ.","ob":"(Il dit à Ziyād fils de son père (Ibn Abīh) qu'il avait nommé gouverneur de la Perse pour remplacer 'Abdallāh ibn al-'Abbās, l'exhortant à ne pas augmenter l'impôt): Emploie la justice, évite l'oppression et l'injustice, car l'oppression mène à l'exode et l'injustice à l'épée.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m477":{"title":"","an":true,"items":[{"t":"c","nums":[1],"ar":"أَشَدُّ الذُّنُوبِ مَا اسْتَخَفَّ بِهِ صَاحِبُهُ.","ob":"Le péché le plus grave est celui qui est dédaigné par celui qui le commet.","obNotes":[],"an":"Le plus grave des péchés est celui que sous - estime son auteur.","anIntro":"","anNotes":[],"diff":null}]},"m478":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"مَا أَخَذَ اللّٰهُ عَلَى أَهْلِ الْجَهْلِ أَنْ يَتَعَلَّمُوا حَتَّى أَخَذَ عَلَى أَهْلِ الْعِلْمِ أَنْ يُعَلِّمُوا.","ob":"Dès que Dieu imposa aux ignorants de s'instruire il demanda aux savants de leur faire apprendre.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"m479":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"شَرُّ الْإِخْوَانِ مَنْ تُكُلِّفَ لَهُ.","ob":"Le pire des frères est celui qui demande de son frère de se charger d'une tâche difficile.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"g1":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"فإذا كان ذلك ضَرَب يعسوب الدين بِذَنَبه، فيجتمعون إليه كما يجتمع قَزَع الخريف.","ob":"Si cela était, le chef de la religion frappe de sa queue, et alors les hommes se rassembleraient autour de lui comme s'assemblent les nuages sans pluies.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"g3":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إن للخصومة قُحَماً.","ob":"La querelle conduit à la ruine.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"g5":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إنَّ الإيمان يبدو لُمْظَة في القلب، كُلَّما ازداد الإيمان ازدادت اللُّمْظة.","ob":"La foi paraît semblable à une blancheur dans le cœur. Plus elle croît plus cette blancheur s'étend.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"g6":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"إنَّ الرَّجُل إذا كان له الدَّين الظَّنون، يجب عليه أنْ يُزَكِّيه، لِما مضى، إذا قَبَضه.","ob":"Si l'homme avait une dette et ne savait pas si elle est solvable, il devrait, au cas où il la toucherait, payer sa dîme comme s'il l'avait reçue auparavant.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]},"g9":{"title":"","an":false,"items":[{"t":"c","nums":[1],"ar":"كُنّا إذا احْمَرَّ البَأْسُ اتَّقَيْنا برسول اللّٰه صلى اللّٰه عليه وآله وسلَّم، فلم يكُن أحَدٌ مِنا أقرَب إلى العدُوّ منه.","ob":"Lorsque le combat s'acharnait, nous demandions au Messager d'Allah (s) de combattre avec nous. Personne parmi nous n'était plus rapproché que lui de l'ennemi.","obNotes":[],"an":null,"anIntro":"","anNotes":[],"diff":null}]}};
